-- fast function below
function various_fast_logic()
 -- CG flight cheat
 cg_flight_cheat = knob_ZFWCG*0.01 + 2 -- 1 is offset
 -- limits 
 if cg_flight_cheat <= 53.0 then cg_flight_cheat = 53.0 end 
 if cg_flight_cheat >= 53.5 then cg_flight_cheat = 53.5 end 
 -- CG test 1% aft shift
 if cg_shift_aft_test == 1 then
  test_cg_aft_offset = test_cg_aft_offset + 0.001
  if test_cg_aft_offset >= 1 then test_cg_aft_offset = 1 end
 else
  test_cg_aft_offset = test_cg_aft_offset - 0.001
  if test_cg_aft_offset <= 0 then test_cg_aft_offset = 0 end
 end
 -- CG Aft fast logic 
 if display_cgacweight >= 10500 then -- only heavy, changed from 16500
 if MACH_SPEED_VALUE < 1 then
  -- applied TO limit 
  if CG_LIMITER_SWITCH == 2 then -- 54 % limit increased
   if cg_aft_offset > 0.5 then -- decrease 
    cg_aft_offset = cg_aft_offset - 0.001
    if cg_aft_offset <= 0.5 then cg_aft_offset = 0.5 end
   else -- increase 
    cg_aft_offset = cg_aft_offset + 0.001
    if cg_aft_offset >= 0.5 then cg_aft_offset = 0.5 end
   end
  else -- normal ops 53.5%
   if cg_aft_offset > 0 then -- decrease 
    cg_aft_offset = cg_aft_offset - 0.001
    if cg_aft_offset <= 0 then cg_aft_offset = 0 end
   --else -- increase 
   -- cg_aft_offset = cg_aft_offset + 0.001
   -- if cg_aft_offset >= 0.3 then cg_aft_offset = 0.3 end
   end
  end
 end
 if MACH_SPEED_VALUE >= 1 and MACH_SPEED_VALUE < 1.3 then
  if cg_aft_offset > 0.6 then -- decrease 
   cg_aft_offset = cg_aft_offset - 0.001
   if cg_aft_offset <= 0.6 then cg_aft_offset = 0.6 end
  else -- increase 
   cg_aft_offset = cg_aft_offset + 0.001
   if cg_aft_offset >= 0.6 then cg_aft_offset = 0.6 end
  end
 end
 if MACH_SPEED_VALUE >= 1.3 and MACH_SPEED_VALUE < 1.6 then
  if cg_aft_offset > 0.8 then -- decrease 
   cg_aft_offset = cg_aft_offset - 0.001
   if cg_aft_offset <= 0.8 then cg_aft_offset = 0.8 end
  else -- increase 
   cg_aft_offset = cg_aft_offset + 0.001
   if cg_aft_offset >= 0.8 then cg_aft_offset = 0.8 end
  end
 end
 if MACH_SPEED_VALUE >= 1.6 then
  --if cg_aft_offset >= 1 then -- decrease 
  -- cg_aft_offset = cg_aft_offset - 0.001
  -- if cg_aft_offset <= 1 then cg_aft_offset = 1 end
  --else -- increase 
   cg_aft_offset = cg_aft_offset + 0.001
   if cg_aft_offset >= 1 then cg_aft_offset = 1 end
  --end
 end
 else -- default CG limit
  cg_aft_offset = cg_aft_offset - 0.001
  if cg_aft_offset <= 0 then cg_aft_offset = 0 end
 end
 -- altitude warning fast logic 
 if FUEL_TRIM_COMMAND == 4 then 
  adjusted_dh_bug_altitude = DH_BUG_ALTITUDE + 20 -- offset
  if altitude <= adjusted_dh_bug_altitude then 
   play_altitude_warning = 1
   VOLUME_11 = VOLUME_11 + 0.0033
   if VOLUME_11 >= 1.0 then VOLUME_11 = 1.0 end
   set_sound_gain(C_ALT, VOLUME_11);
  end
 else
  play_altitude_warning = 0
  VOLUME_11 = 0
  adjusted_dh_bug_altitude = 0
  played_altitude = 0 -- reset for next landing 
 end
 --TEST1=VOLUME_11 
 --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
 --initial fast Distance to Go selector, the rest is slow in next function
 if DTG_SETRUN_ON == 0 then
   CON_DTG_DISPLAY = DTG_SELECTOR
  --function round(CON_DTG_DISPLAY) -- round numbers for next if condition
  --return CON_DTG_DISPLAY % 1 >= 0.5 and math.ceil(CON_DTG_DISPLAY)
  --end
  setDatai(findDataref("Gastonreif/Heritage/distancetogo"),CON_DTG_DISPLAY)
 end
 -- Fast LEDs on consumed fuel displays
  -- TANK1
 if ENG1_N1 ~= 0 then
   if RANDGEN >= 0.69 and delay_flash_consumed1_m == 0 then -- random logic for flash 
    -- flash duration is how long stay condition active
    flashed_m_consumed1 = 1	
   end
   if RANDGEN >= 0.79 and delay_flash_consumed1_rh == 0 then 
    flashed_rh_consumed1 = 1	
   end
   -- timing Main 
   if flashed_m_consumed1 == 1 then -- how long will lit 
	-- flash standby duration below 
	delay_flash_consumed1_m = delay_flash_consumed1_m + random_number_everytime
	if delay_flash_consumed1_m >= 5 then 
	 delay_flash_consumed1_m = 0 -- exit  
	 flashed_m_consumed1 = 0
	end 
   else -- no flash conditions met, how long will NOT lit 
    delay_flash_consumed1_m = delay_flash_consumed1_m + random_number_everytime
	if delay_flash_consumed1_m <= 10 then 
     flashed_m_consumed1 = 0 -- no lit please 
	else
	 delay_flash_consumed1_m = 0 -- reset after hit 10
	end 
   end 
   -- timing Reheat  
   if flashed_rh_consumed1 == 1 then -- how long will lit 
	-- flash standby duration below 
	delay_flash_consumed1_rh = delay_flash_consumed1_rh + random_number_everytime
	if delay_flash_consumed1_rh >= 5 then 
