	 flashed_rh_consumed1 = 0
	end 
   else -- no flash conditions met, how long will NOT lit 
    delay_flash_consumed1_rh = delay_flash_consumed1_rh + random_number_everytime
	if delay_flash_consumed1_rh <= 20 then 
     flashed_rh_consumed1 = 0 -- no lit please 
	else
	 delay_flash_consumed1_rh = 0 -- reset after hit 20
	end 
   end 
  -- execute light or not 
  if knob_consumed1 == 0 then -- normals ops only
   lamp_consumed1_main = flashed_m_consumed1
   setDatai(findDataref("Gastonreif/Heritage/lamp_consumed1_main"),lamp_consumed1_main)
   lamp_consumed1_rh = flashed_rh_consumed1
   setDatai(findDataref("Gastonreif/Heritage/lamp_consumed1_rh"),lamp_consumed1_rh)
  end 
 end 
 -- TANK2 
 if ENG2_N1 ~= 0 then
   if RANDGEN >= 0.59 and RANDGEN <= 0.79 then -- random logic for flash 
    if delay_flash_consumed2_m == 0 then 
    -- flash duration is how long stay condition active
