   -- timing Main 
   if flashed_m_consumed2 == 1 then -- how long will lit 
	-- flash standby duration below 
	delay_flash_consumed2_m = delay_flash_consumed2_m + random_number_everytime
	if delay_flash_consumed2_m >= 5 then 
