	end 
   else -- no flash conditions met, how long will NOT lit 
    delay_flash_consumed2_m = delay_flash_consumed2_m + random_number_everytime
	if delay_flash_consumed2_m <= 10 then 
     flashed_m_consumed2 = 0 -- no lit please 
	else
	 delay_flash_consumed2_m = 0 -- reset after hit 10
	end 
   end 
   -- timing Reheat  
   if flashed_rh_consumed2 == 1 then -- how long will lit 
	-- flash standby duration below 
	delay_flash_consumed2_rh = delay_flash_consumed2_rh + random_number_everytime
	if delay_flash_consumed2_rh >= 5 then 
	 delay_flash_consumed2_rh = 0 -- exit  
	 flashed_rh_consumed2 = 0
	end 
   else -- no flash conditions met, how long will NOT lit 
    delay_flash_consumed2_rh = delay_flash_consumed2_rh + random_number_everytime
	if delay_flash_consumed2_rh <= 20 then 
     flashed_rh_consumed2 = 0 -- no lit please 
	else
	 delay_flash_consumed2_rh = 0 -- reset after hit 20
	end 
   end 
  -- execute light or not 
  if knob_consumed2 == 0 then -- normals ops only
   lamp_consumed2_main = flashed_m_consumed2
   setDatai(findDataref("Gastonreif/Heritage/lamp_consumed2_main"),lamp_consumed2_main)
   lamp_consumed2_rh = flashed_rh_consumed2
   setDatai(findDataref("Gastonreif/Heritage/lamp_consumed2_rh"),lamp_consumed2_rh)
  end 
 end 
 -- TANK3 
 if ENG3_N1 ~= 0 then
	--heritage_debug2=RANDGEN
    --setDataf(findDataref("Gastonreif/Heritage/debug2"),heritage_debug2)
   if RANDGEN >= 0.19 and RANDGEN <= 0.29 then -- random logic for flash 
    if delay_flash_consumed3_m == 0 then 
    -- flash duration is how long stay condition active
    flashed_m_consumed3 = 1	
	end 
   end
   if RANDGEN >= 0.09 and RANDGEN <= 0.19 then 
    if delay_flash_consumed3_rh == 0 then
    flashed_rh_consumed3 = 1	
	end
   end
   -- timing Main 
   if flashed_m_consumed3 == 1 then -- how long will lit 
	-- flash standby duration below 
	delay_flash_consumed3_m = delay_flash_consumed3_m + random_number_everytime
	if delay_flash_consumed3_m >= 5 then 
