	end 
   else -- no flash conditions met, how long will NOT lit 
    delay_flash_consumed3_m = delay_flash_consumed3_m + random_number_everytime
	if delay_flash_consumed3_m <= 10 then 
     flashed_m_consumed3 = 0 -- no lit please 
