	end 
   end 
   --heritage_debug1=delay_flash_consumed2_m
   --setDataf(findDataref("Gastonreif/Heritage/debug1"),heritage_debug1)
   -- timing Reheat  
   if flashed_rh_consumed3 == 1 then -- how long will lit 
	-- flash standby duration below 
	delay_flash_consumed3_rh = delay_flash_consumed3_rh + random_number_everytime
	if delay_flash_consumed3_rh >= 5 then 
	 delay_flash_consumed3_rh = 0 -- exit  
