	end 
   else -- no flash conditions met, how long will NOT lit 
    delay_flash_consumed3_rh = delay_flash_consumed3_rh + random_number_everytime
	if delay_flash_consumed3_rh <= 20 then 
     flashed_rh_consumed3 = 0 -- no lit please 
	else
	 delay_flash_consumed3_rh = 0 -- reset after hit 20
	end 
   end 
  -- execute light or not 
  if knob_consumed3 == 0 then -- normals ops only
   lamp_consumed3_main = flashed_m_consumed3
   setDatai(findDataref("Gastonreif/Heritage/lamp_consumed3_main"),lamp_consumed3_main)
   lamp_consumed3_rh = flashed_rh_consumed3
   setDatai(findDataref("Gastonreif/Heritage/lamp_consumed3_rh"),lamp_consumed3_rh)
