 -- TANK4 
 if ENG4_N1 ~= 0 then
   if RANDGEN >= 0.09 and RANDGEN <= 0.19 then -- random logic for flash 
    if delay_flash_consumed4_m == 0 then 
    -- flash duration is how long stay condition active
    flashed_m_consumed4 = 1	
	end
   end
   if RANDGEN >= 0.81 and delay_flash_consumed4_rh == 0 then 
    flashed_rh_consumed4 = 1	
   end
   -- timing Main 
   if flashed_m_consumed4 == 1 then -- how long will lit 
