 -- next fast logic below 
end
-- timers 
function various_timers()
 --global CPU power saving variables
 --lights override
 if ROOF_SW_ANTICOLL == 1 and anticol_once == false then 
  if EMERG_EVAC_SWITCH == 1 then
   OVERRIDE_STROBES = 1 
   setDatai(findDataref("sim/flightmodel2/lights/override_beacons_and_strobes"),OVERRIDE_STROBES)
  else
   OVERRIDE_STROBES = 0 
   setDatai(findDataref("sim/flightmodel2/lights/override_beacons_and_strobes"),OVERRIDE_STROBES)
  end
  anticol_once = true
 end
 if ROOF_SW_ANTICOLL == 0 and anticol_once == true then
  OVERRIDE_STROBES = 0
  setDatai(findDataref("sim/flightmodel2/lights/override_beacons_and_strobes"),OVERRIDE_STROBES)
  anticol_once = false
 end
 random_number_everytime = RANDGEN -- every second store new random number
 -- quick pressure indicator effect
 if PRESS_SYS_SEL_L == 0 and PRESS_SYS_SEL_R == 0 then -- SYS1 
  if delay_rate_counter == 0 then 
   stored_current_rate = stored_previous_rate
  end
  delay_rate_counter = delay_rate_counter + 1 -- count once 
  if delay_rate_counter == 1 then -- counter finished 
   stored_previous_rate = PRESS_RATE_SEL1
   delay_rate_counter = 0
  end
  if stored_previous_rate ~= stored_current_rate then
   quickpress_indicator_offset_active = 1
  else 
   quickpress_indicator_offset_active = 0
  end 
 end
 if PRESS_SYS_SEL_L == 1 and PRESS_SYS_SEL_R == 1 then -- SYS2 
  if delay_rate_counter == 0 then 
   stored_current_rate = stored_previous_rate
  end
  delay_rate_counter = delay_rate_counter + 1 -- count once 
  if delay_rate_counter == 1 then -- counter finished 
   stored_previous_rate = PRESS_RATE_SEL2
   delay_rate_counter = 0
  end
  if stored_previous_rate ~= stored_current_rate then
   quickpress_indicator_offset_active = 1
  else 
   quickpress_indicator_offset_active = 0
  end 
 end
 -- Fuel consumed test and reset logic 
  -- test 
 if knob_consumed1 == 1 then -- test 
  display_fuel_consumed1 = 8888
  setDataf(findDataref("Gastonreif/Heritage/display_fuel_consumed1"),display_fuel_consumed1)
  lamp_consumed1_main = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed1_main"),lamp_consumed1_main)
  lamp_consumed1_rh = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed1_rh"),lamp_consumed1_rh)
 end
 if knob_consumed2 == 1 then -- test 
  display_fuel_consumed2 = 8888
  setDataf(findDataref("Gastonreif/Heritage/display_fuel_consumed2"),display_fuel_consumed2)
  lamp_consumed2_main = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed2_main"),lamp_consumed2_main)
  lamp_consumed2_rh = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed2_rh"),lamp_consumed2_rh)
 end
 if knob_consumed3 == 1 then -- test 
  display_fuel_consumed3 = 8888
  setDataf(findDataref("Gastonreif/Heritage/display_fuel_consumed3"),display_fuel_consumed3)
  lamp_consumed3_main = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed3_main"),lamp_consumed3_main)
  lamp_consumed3_rh = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed3_rh"),lamp_consumed3_rh)
 end
 if knob_consumed4 == 1 then -- test 
  display_fuel_consumed4 = 8888
  setDataf(findDataref("Gastonreif/Heritage/display_fuel_consumed4"),display_fuel_consumed4)
  lamp_consumed4_main = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed4_main"),lamp_consumed4_main)
  lamp_consumed4_rh = 1
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed4_rh"),lamp_consumed4_rh)
 end
  -- reset 
 if knob_consumed1 == -1 then -- reset 
  counter_fuel_consumed1 = 0
  lamp_consumed1_main = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed1_main"),lamp_consumed1_main)
  lamp_consumed1_rh = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed1_rh"),lamp_consumed1_rh)
 end
 if knob_consumed2 == -1 then 
  counter_fuel_consumed2 = 0
  lamp_consumed2_main = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed2_main"),lamp_consumed2_main)
  lamp_consumed2_rh = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed2_rh"),lamp_consumed2_rh)
 end
 if knob_consumed3 == -1 then
  counter_fuel_consumed3 = 0
  lamp_consumed3_main = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed3_main"),lamp_consumed3_main)
  lamp_consumed3_rh = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed3_rh"),lamp_consumed3_rh)
 end
 if knob_consumed4 == -1 then
  counter_fuel_consumed4 = 0
  lamp_consumed4_main = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed4_main"),lamp_consumed4_main)
  lamp_consumed4_rh = 0
  setDatai(findDataref("Gastonreif/Heritage/lamp_consumed4_rh"),lamp_consumed4_rh)
 end
 -- 3 seconds to normal operation, switch back previous knobs
 if knob_consumed1 ~= 0 and delay_fuel_consumed_counter1 < 4 then  -- until counting 
  delay_fuel_consumed_counter1 = delay_fuel_consumed_counter1 + 1
  if delay_fuel_consumed_counter1 >= 3 then -- 3 is max 
  	-- delay_fuel_consumed_counter1 = 0 -- this condition is elsewhere
  	knob_consumed1 = 0 -- exit 
  	setDatai(findDataref("Gastonreif/Heritage/knob_consumed1"),knob_consumed1)
  end
 end 
 if knob_consumed2 ~= 0 and delay_fuel_consumed_counter2 < 4 then
  delay_fuel_consumed_counter2 = delay_fuel_consumed_counter2 + 1
  if delay_fuel_consumed_counter2 >= 3 then -- 3 is max 
  	-- delay_fuel_consumed_counter1 = 0 -- this condition is elsewhere
  	knob_consumed2 = 0 -- exit 
  	setDatai(findDataref("Gastonreif/Heritage/knob_consumed2"),knob_consumed2)
  end
 end 
 if knob_consumed3 ~= 0 and delay_fuel_consumed_counter3 < 4 then  -- until counting 
  delay_fuel_consumed_counter3 = delay_fuel_consumed_counter3 + 1
  if delay_fuel_consumed_counter3 >= 3 then -- 3 is max 
  	-- delay_fuel_consumed_counter1 = 0 -- this condition is elsewhere
  	knob_consumed3 = 0 -- exit 
  	setDatai(findDataref("Gastonreif/Heritage/knob_consumed3"),knob_consumed3)
  end
 end 
 if knob_consumed4 ~= 0 and delay_fuel_consumed_counter4 < 4 then  -- until counting 
  delay_fuel_consumed_counter4 = delay_fuel_consumed_counter4 + 1
  if delay_fuel_consumed_counter4 >= 3 then -- 3 is max 
  	-- delay_fuel_consumed_counter1 = 0 -- this condition is elsewhere
  	knob_consumed4 = 0 -- exit 
  	setDatai(findDataref("Gastonreif/Heritage/knob_consumed4"),knob_consumed4)
  end
 end 
 -- various FLAGS
 -- FE FUEL totals
 fuel_counters_low = FUEL_TANK_1_LOWLEVEL_LIGHT + FUEL_TANK_2_LOWLEVEL_LIGHT + FUEL_TANK_3_LOWLEVEL_LIGHT + FUEL_TANK_4_LOWLEVEL_LIGHT
 if battery_on == 0 or fuel_counters_low >= 2 then
  flag_aft_total_counters = 0 -- 0 is ON
  setDatai(findDataref("Gastonreif/Heritage/flag_aft_total_counters"), flag_aft_total_counters) -- 1 flag is off
 end
 if battery_on == 1 and fuel_counters_low <= 1 then
  flag_aft_total_counters = 1 -- 0 is off
  setDatai(findDataref("Gastonreif/Heritage/flag_aft_total_counters"), flag_aft_total_counters)
 end
 -- AFR4590 scenario 
 if transponder_code == 4590 then
  -- tire blown
  if failure_code == 1 and braketemp <= 170 then
   tire_blown_multiplier = 0.1 
  end  
  if failure_code == 1 and braketemp > 170 then -- reset, prevents exponential rise of temperature 
   tire_blown_multiplier = 0 
  end
  -- blue hydr overpress
  if failure_code == 1 then
   blue_overpress_plus = 2  -- no reset, stay forever
  end  
 else -- all reset no AFR4590 scenario
  tire_blown_multiplier = 0
  blue_overpress_plus = 0
 end
 -- GPU loadup
 if ENGINEERS_INTERCOM == 1 and GROUND_CALL_BUTTON == 1 then
  if gpu_loadup_once == 0 then  -- load once, prevents menu colision
   GPU_UNIT_ON = 1
   setDatai(findDataref("Colimata/CON_VEH_sw_load_gpu_i"),GPU_UNIT_ON)
   GUI_GPU_SELECTED = 1
   setDatai(findDataref("Colimata/CON_GUI_ACF_DG_UT_gpu_i"),GUI_GPU_SELECTED)
   gpu_loadup_once = 1
  end
 end 
 if gpu_loadup_once == 1 then -- unload GPU once
  if ENGINEERS_INTERCOM == 0 and GROUND_CALL_BUTTON == 0 then
   GPU_UNIT_ON = 0
   setDatai(findDataref("Colimata/CON_VEH_sw_load_gpu_i"),GPU_UNIT_ON)
   GUI_GPU_SELECTED = 0
   setDatai(findDataref("Colimata/CON_GUI_ACF_DG_UT_gpu_i"),GUI_GPU_SELECTED)
   gpu_loadup_once = 0
  end 
 end 
 --
 if battery_on == 1 then
 -- CLOCK and Distance to Go
 -- distance remaining
 if DTG_SETRUN_ON == 1 then
  --store value
  if stored_dtg == 0 and CON_DTG_DISPLAY ~= 0 then
   stored_dtg_value = DTG_SELECTOR
   CON_DTG_DISPLAY = stored_dtg_value
   setDatai(findDataref("Gastonreif/Heritage/distancetogo"),CON_DTG_DISPLAY)
   stored_dtg = 1
  end 
  if stored_dtg == 1 and CON_DTG_DISPLAY ~= 0 then -- main formula
   distance_flown = (distance_traveled_meters*0.000539) - last_trip_distance -- nautical miles
   --distance_flown = 1 -- test only
   function round(distance_flown) -- round numbers for next if condition
   return distance_flown % 1 >= 0.5 and math.ceil(distance_flown)
   end
   if distance_flown < 0 then distance_flown = 0 end -- protection 
   CON_DTG_DISPLAY = stored_dtg_value - distance_flown/10
   setDatai(findDataref("Gastonreif/Heritage/distancetogo"),CON_DTG_DISPLAY)
   --limits
   if CON_DTG_DISPLAY >= 999 then 
    CON_DTG_DISPLAY = 999 
    setDatai(findDataref("Gastonreif/Heritage/distancetogo"),CON_DTG_DISPLAY)
	stored_dtg = 0
   end
   if CON_DTG_DISPLAY <= 0 then 
    CON_DTG_DISPLAY = 0 
	setDatai(findDataref("Gastonreif/Heritage/distancetogo"),CON_DTG_DISPLAY)
