 -- Pilots Clock
 -- Chronometer
 if CON_CLOCK_TIMER_MODE == 1 then 
 was_chrono_mode = 1
 -- Chrono button
 if CON_CLOCK_CHRONO_BUTTON == 1 and chrono_skip_once == 0 then
 -- start stop reset - 0 - 1 - 2 
  chrono_button_pressed = chrono_button_pressed + 1
 end
 --
 if CON_CLOCK_CHRONO_BUTTON == 1 then
  chrono_skip_once = 1
 end
 if CON_CLOCK_CHRONO_BUTTON == 0 then
  chrono_skip_once = 0
 end
 if chrono_button_pressed == 3 then
 -- reset chrono
  chrono_button_pressed = 0
 end
 -- Chrono reset
 if chrono_button_pressed == 0 then -- set chrono to zero
  con_chrono_sec = 100
  con_chrono_min = 100
 end
 -- Chrono stop
 if chrono_button_pressed == 2 then -- no change in chrono
  con_chrono_sec = con_chrono_sec + 0
  con_chrono_min = con_chrono_min + 0
 end
 -- Chrono start
 if chrono_button_pressed == 1 then
  -- seconds first
  if chrono_seconds_again == 0 then
   con_chrono_sec = 100
   chrono_seconds_again = 1
  end 
  if con_chrono_sec <= 158 and chrono_seconds_again == 1 then 
   con_chrono_sec = con_chrono_sec+1
  else -- 1 minute passed
   chrono_seconds_again = 0
   con_chrono_sec = 100
   -- minutes here
   if chrono_minutes_again == 0 then
    con_chrono_min = 100
    chrono_minutes_again = 1
   end 
   if con_chrono_min <= 158 and chrono_minutes_again == 1 then 
    con_chrono_min = con_chrono_min+1
   else -- 1 hour passed
    chrono_minutes_again = 0
	con_chrono_min = 100
   end 
   -- end minutes
  end 
 end -- chrono pressed 1 end 
 else -- Timer mode
 if CON_CLOCK_CHRONO_BUTTON == 1 and timer_skip_once == 0 then
 -- start stop reset - 0 - 1 - 2 
  timer_button_pressed = timer_button_pressed + 1
 end
 --
 if CON_CLOCK_CHRONO_BUTTON == 1 then
  timer_skip_once = 1
 end
 if CON_CLOCK_CHRONO_BUTTON == 0 then
  timer_skip_once = 0
 end
 -- Timer defaults 
 if timer_button_pressed == 0 and was_chrono_mode == 1 then -- set timer to zero
  if was_chrono_mode == 1 then -- do only once
  con_timer_sec = 100
  con_timer_min = 100
  was_chrono_mode = 0 -- reset
  end
 end
 -- Timer set 
 if CON_CLOCK_TIMER_SET == 0 then --  minutes per second 
  con_timer_min = con_timer_min + 1
  if con_timer_min >= 199 then con_timer_min = 199 end -- display limit 
 end
 if CON_CLOCK_TIMER_SET == 1 then --  seconds 
  con_timer_sec = con_timer_sec + 1
  if con_timer_sec >= 159 then con_timer_sec = 159 end -- display limit 
 end
 if CON_CLOCK_TIMER_SET == 2 then --  hold 
  con_timer_min = con_timer_min + 0
  con_timer_sec = con_timer_sec + 0
 end
 if CON_CLOCK_TIMER_SET == 4 then --  reset
  con_timer_min = 100
  con_timer_sec = 100
 end
 if CON_CLOCK_TIMER_SET ~= 3 then 
  timer_last_minute = 0 
  timer_seconds_again = 1
  timer_button_pressed = 0
 end -- reset timer when finished
 -- Timer start
 if timer_button_pressed >= 1 and CON_CLOCK_TIMER_SET == 3 then -- run countdown 
    -- seconds 
  if con_timer_sec >= 100 and timer_seconds_again == 1 then 
   con_timer_sec = con_timer_sec-1
   timer_minutes_again = 0
   if con_timer_sec < 100 then 
    if timer_last_minute == 0 then 
     con_timer_sec = 159
	 timer_minutes_again = 1
	else -- last minute
	 con_timer_sec = 100
	 timer_seconds_again = 0
	end
 -- 1 minute counted down 
  end   
   -- end minutes
  end 
  -- minutes here
  if con_timer_min >= 101 and timer_minutes_again == 1 then 
   con_timer_min = con_timer_min-1
   timer_minutes_again = 0
  end
  if con_timer_min == 100 then timer_last_minute = 1 end
 end -- chrono pressed 1 end 
 end -- end chrono display logic 
 -- drive the Chrono display 
 if CON_CLOCK_TIMER_MODE == 1 then 
  CON_CHRONO_DISP_SEC = con_chrono_sec 
  setDatai(findDataref("Gastonreif/Heritage/clock_chrono_seconds"),CON_CHRONO_DISP_SEC)
  CON_CHRONO_DISP_MIN = con_chrono_min 
  setDatai(findDataref("Gastonreif/Heritage/clock_chrono_minutes"),CON_CHRONO_DISP_MIN)
 else
  CON_CHRONO_DISP_SEC = con_timer_sec 
  setDatai(findDataref("Gastonreif/Heritage/clock_chrono_seconds"),CON_CHRONO_DISP_SEC)
  CON_CHRONO_DISP_MIN = con_timer_min 
  setDatai(findDataref("Gastonreif/Heritage/clock_chrono_minutes"),CON_CHRONO_DISP_MIN)
 end
 -- Elapsed timer
 -- Elapsed reset
 if CON_CLOCK_ELAPSED_SWITCH == 2 then -- set elapsed to zero
  CON_ELAPSED_DISP_MIN = 100 
  setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_minutes"),CON_ELAPSED_DISP_MIN)
  CON_ELAPSED_DISP_HOURS = 100
  setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_hours"),CON_ELAPSED_DISP_HOURS)
  CON_ELAPSED_DUMMY_SEC = 100
  elapsed_reset_skip = elapsed_reset_skip+1
  if elapsed_reset_skip == 2 then -- spring load to stop 
   elapsed_reset_skip = 0 -- reset
   CON_CLOCK_ELAPSED_SWITCH = 1
   setDatai(findDataref("Colimata/CON_IP_CLOCK_sw_run_stop_reset_i"),CON_CLOCK_ELAPSED_SWITCH) 
  end
 end
 -- Elapsed stop
 if CON_CLOCK_ELAPSED_SWITCH == 1 then -- no change in elapsed
  CON_ELAPSED_DISP_MIN = CON_ELAPSED_DISP_MIN + 0
  setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_minutes"),CON_ELAPSED_DISP_MIN)
  CON_ELAPSED_DISP_HOURS = CON_ELAPSED_DISP_HOURS + 0
  setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_hours"),CON_ELAPSED_DISP_HOURS)
  CON_ELAPSED_DUMMY_SEC = CON_ELAPSED_DUMMY_SEC + 0
 end
 -- Run
 if CON_CLOCK_ELAPSED_SWITCH == 0 then
  -- seconds first, not visible
  if elapsed_seconds_again == 0 then
   CON_ELAPSED_DUMMY_SEC = 100
   elapsed_seconds_again = 1
  end 
  if CON_ELAPSED_DUMMY_SEC <= 158 and elapsed_seconds_again == 1 then 
   CON_ELAPSED_DUMMY_SEC = CON_ELAPSED_DUMMY_SEC+1
  else -- 1 minute passed
   elapsed_seconds_again = 0
   CON_ELAPSED_DUMMY_SEC = 100 -- place 00 seconds after 59 here for one second before 01
   -- minutes here
   if elapsed_minutes_again == 0 then
    CON_ELAPSED_DISP_MIN = 100
    setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_minutes"),CON_ELAPSED_DISP_MIN)
    elapsed_minutes_again = 1
   end 
   if CON_ELAPSED_DISP_MIN <= 158 and elapsed_minutes_again == 1 then 
    CON_ELAPSED_DISP_MIN = CON_ELAPSED_DISP_MIN+1
    setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_minutes"),CON_ELAPSED_DISP_MIN)
   else -- 1 hour passed
    elapsed_minutes_again = 0
	CON_ELAPSED_DISP_MIN = 100 -- place 00 minutes after 59 here for one minutes before 01
    setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_minutes"),CON_ELAPSED_DISP_MIN)
	-- hours here
    if elapsed_hours_again == 0 then
     CON_ELAPSED_DISP_HOURS = 100
     setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_hours"),CON_ELAPSED_DISP_HOURS)
     elapsed_hours_again = 1
    end 
    if CON_ELAPSED_DISP_HOURS <= 199 and elapsed_hours_again == 1 then 
     CON_ELAPSED_DISP_HOURS = CON_ELAPSED_DISP_HOURS+1
     setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_hours"),CON_ELAPSED_DISP_HOURS)
    else -- 99 hours passed
     elapsed_hours_again = 0
	 CON_ELAPSED_DISP_HOURS = 100 -- place 00 hours after 99 here for one hour before 01
     setDatai(findDataref("Gastonreif/Heritage/clock_elapsed_hours"),CON_ELAPSED_DISP_HOURS)
    end 
    -- end hours
   end 
   -- end minutes
  end 
 end
