     pwr_ac3 = all_aircondition_power/split_load_gens
    else 
     pwr_ac3 = 0
    end 
    if GEN4_LIGHT == 0 then 
     pwr_ac4 = all_aircondition_power/split_load_gens
    else 
     pwr_ac4 = 0
    end 
  end
 -- generator dials are in faster function, here are only inputs  
 if battery_on == 1 then 
  if ELEC_GEN1 == 0 then
   pwr_gen1total_load=pwr_eng1start+pwr_avionics1+pwr_ac_avi1+pwr_brkfan1+pwr_cpress1+pwr_fuelheat1+pwr_galley1+pwr_fuelpumps1+pwr_heatlo1+pwr_heatmid1+pwr_heathi1+pwr_lights1+pwr_ac1
  end
  if ELEC_GEN1 == 1 then -- no gen1 connected 
   pwr_gen1total_load = 0
  end 
  if ELEC_GEN1 == 2 then -- test 
   pwr_gen1total_load = 60
  end 
  if ELEC_GEN2 == 0 then
   pwr_gen2total_load=pwr_eng2start+pwr_avionics2+pwr_ac_avi2+pwr_brkfan2+pwr_cpress2+pwr_fuelheat2+pwr_galley2+pwr_fuelpumps2+pwr_heatlo2+pwr_heatmid2+pwr_heathi2+pwr_lights2+pwr_ac2  
  end
  if ELEC_GEN2 == 1 then
   pwr_gen2total_load = 0
  end
  if ELEC_GEN2 == 2 then
   pwr_gen2total_load = 60
  end
  if ELEC_GEN3 == 0 then
   pwr_gen3total_load=pwr_eng3start+pwr_avionics3+pwr_ac_avi3+pwr_brkfan3+pwr_cpress3+pwr_fuelheat3+pwr_galley3+pwr_fuelpumps3+pwr_heatlo3+pwr_heatmid3+pwr_heathi3+pwr_lights3+pwr_ac3   
  end
  if ELEC_GEN3 == 1 then
   pwr_gen3total_load = 0
  end
  if ELEC_GEN3 == 2 then
   pwr_gen3total_load = 60
  end
  if ELEC_GEN4 == 0 then
   pwr_gen4total_load=pwr_eng4start+pwr_avionics4+pwr_ac_avi4+pwr_brkfan4+pwr_cpress4+pwr_fuelheat4+pwr_galley4+pwr_fuelpumps4+pwr_heatlo4+pwr_heatmid4+pwr_heathi4+pwr_lights4+pwr_ac4
  end
  if ELEC_GEN4 == 1 then
   pwr_gen4total_load = 0
  end
  if ELEC_GEN4 == 2 then
   pwr_gen4total_load = 60
  end
  -- 5th gen here 
  if GEN5_SELECTED_LIGHT == 1 and AFT_LIGHTS_TEST ~= 2 then 
   pwr_5thgen_ac = all_aircondition_power/split_load_gens
   pwr_5thgen_lights = (20+cabin_and_outside_lights_lit)/split_load_gens
   pwr_5thgen_hipow = (hipower_heaters_2pos*4)/split_load_gens
   pwr_5thgen_midpow = (midpower_heaters_2pos*0.5)/split_load_gens
   pwr_5thgen_lowpow = ((1+lowpower_heaters_3pos)*0.25)/split_load_gens
   pwr_5thgen_fuelpumps = ((1+all_pumps_runs)*0.25)/split_load_gens
   pwr_5thgen_cpress = pwr_cpress_all
   pwr_5thgen_avi = 6/split_load_gens -- fixed 4+2kW must run for avionics if all engines are out 
   pwr_5thgen_start = pwr_eng1startbygen5 + pwr_eng2startbygen5 + pwr_eng3startbygen5 + pwr_eng4startbygen5
   pwr_5thgentotal_load=pwr_5thgen_ac+pwr_5thgen_lights+pwr_5thgen_hipow+pwr_5thgen_midpow+pwr_5thgen_lowpow+pwr_5thgen_fuelpumps+pwr_5thgen_cpress+pwr_5thgen_avi+pwr_5thgen_start
  else -- 5th gen deactivated 
   pwr_5thgentotal_load = 0
  end 
  -- overheat of the 5th gen 
  if pwr_5thgentotal_load >= 35 then
   gen5_counter = gen5_counter + 1 -- at 15 sec is overloaded, value has effect in light section 
  else
   gen5_counter = 0 -- reset 
  end
 else -- no bat
  pwr_gen1total_load = 0
  pwr_gen2total_load = 0
  pwr_gen3total_load = 0
  pwr_gen4total_load = 0
  pwr_5thgentotal_load = 0
 end
 -- TRU amperage comes from P = U x I, 115V is generator voltage
 if battery_on == 1 then
  -- initials
  if ELEC_TRU1 == 0 then tru1_not_isolated = 1 else tru1_not_isolated = 0 end
  if ELEC_TRU2 == 0 then tru2_not_isolated = 1 else tru2_not_isolated = 0 end
  if ELEC_TRU3 == 0 then tru3_not_isolated = 1 else tru3_not_isolated = 0 end
  if ELEC_TRU4 == 0 then tru4_not_isolated = 1 else tru4_not_isolated = 0 end
  split_load_trus = tru1_not_isolated + tru2_not_isolated + tru3_not_isolated + tru4_not_isolated
  if split_load_trus == 0 then split_load_trus = 0.5 end -- divide by zero protection
  -- TRU1 
  if AC1_ESS_LIGHT == 0 and ELEC_TRU1 == 0 then 
   tru1_ampers = ((pwr_gen1total_load*1000)/115)/split_load_trus
  else -- isol 
   tru1_ampers = 0
  end
  -- TRU2 
  if AC2_ESS_LIGHT == 0 and ELEC_TRU2 == 0 then 
   tru2_ampers = ((pwr_gen2total_load*1000)/115)/split_load_trus
  else -- isol 
   tru2_ampers = 0
  end
  -- TRU3 
  if AC3_ESS_LIGHT == 0 and ELEC_TRU3 == 0 then 
   tru3_ampers = ((pwr_gen3total_load*1000)/115)/split_load_trus
  else -- isol 
   tru3_ampers = 0
  end
  -- TRU4 
  if AC4_ESS_LIGHT == 0 and ELEC_TRU4 == 0 then 
   tru4_ampers = ((pwr_gen4total_load*1000)/115)/split_load_trus
  else -- isol 
   tru4_ampers = 0
  end
 else -- batt off 
  tru1_ampers = 0
  tru2_ampers = 0
  tru3_ampers = 0
  tru4_ampers = 0
 end 
 -- TRU overheat logic
 if tru1_ampers >= 200 then
  tru1_counter = tru1_counter + 1 -- at 300 sec is overloaded, value has effect in light section 
 else
  tru1_counter = 0 -- reset 
 end
 if tru2_ampers >= 200 then
  tru2_counter = tru2_counter + 1
 else
  tru2_counter = 0 -- reset 
 end
 if tru3_ampers >= 200 then
  tru3_counter = tru3_counter + 1 
 else
  tru3_counter = 0 -- reset 
 end
 if tru4_ampers >= 200 then
  tru4_counter = tru4_counter + 1 
 else
  tru4_counter = 0 -- reset 
 end
 -- Battery recharger
 -- initials
 SOME_ACESS_AVAIL = AC1_ESS_POWERED + AC2_ESS_POWERED + AC3_ESS_POWERED + AC4_ESS_POWERED
  -- power on only batteries 
 if DC_BAT_LEFT_SWITCH == 1 and SOME_ACESS_AVAIL == 0 then -- discharging
  battery_a_amps = battery_a_amps - 0.027 -- 100Ah rate 
  battery_a_volts = battery_a_volts - 0.0078
  -- limit
  if battery_a_amps <= 0 then battery_a_amps = 0 end
  if battery_a_volts <= 0 then battery_a_volts = 0 end
  --recharging_battery_a_time = recharging_battery_a_time + 1
  -- limit
  --if recharging_battery_a_time >= 3600 then recharging_battery_a_time = 3600 end
 end 
  -- power off drain bug fixer
  if DC_BAT_LEFT_SWITCH == 2 then 
   battery_a_volts = 0
   battery_a_was_off = 1
  end
  if DC_BAT_LEFT_SWITCH == 1 and battery_a_was_off == 1 then -- was switched off 
   battery_a_volts = 26
   battery_a_was_off = 0
  end
  -- all powered and recharging 
 if DC_BAT_LEFT_SWITCH == 1 and SOME_ACESS_AVAIL ~= 0 then -- recharging
  battery_a_amps = battery_a_amps + 0.0185
  battery_a_volts = battery_a_volts + 0.0078 -- same rate for discharge and rechgarge 
  -- limit
  if battery_a_amps >= 100 then battery_a_amps = 100 end
  if battery_a_volts >= 28 then battery_a_volts = 28 end
  --recharging_battery_a_time = recharging_battery_a_time - 1
  -- limit 
  --if recharging_battery_a_time <= 0 then recharging_battery_a_time = 0 end
 end -- end battery left charger 
 -- right battery 
 if DC_BAT_RIGHT_SWITCH == 1 and SOME_ACESS_AVAIL == 0 then -- discharging
  battery_b_amps = battery_b_amps - 0.027 -- 100Ah rate 
  battery_b_volts = battery_b_volts - 0.0078
  -- limit
  if battery_b_amps <= 0 then battery_b_amps = 0 end
  if battery_b_volts <= 0 then battery_b_volts = 0 end
  --recharging_battery_b_time = recharging_battery_b_time + 1
  -- limit
  --if recharging_battery_b_time >= 3600 then recharging_battery_b_time = 3600 end
 end 
  -- power off drain bug fixer
  if DC_BAT_RIGHT_SWITCH == 2 then 
   battery_b_volts = 0
   battery_b_was_off = 1
  end
  if DC_BAT_RIGHT_SWITCH == 1 and battery_b_was_off == 1 then -- was switched off 
   battery_b_volts = 26
   battery_b_was_off = 0
  end
  -- all powered and recharging 
 if DC_BAT_RIGHT_SWITCH == 1 and SOME_ACESS_AVAIL ~= 0 then -- recharging
  battery_b_amps = battery_b_amps + 0.0185
  battery_b_volts = battery_b_volts + 0.0078 
  -- limit
  if battery_b_amps >= 100 then battery_b_amps = 100 end
  if battery_b_volts >= 28 then battery_b_volts = 28 end
  --recharging_battery_b_time = recharging_battery_b_time - 1
  -- limit 
  --if recharging_battery_b_time <= 0 then recharging_battery_b_time = 0 end
 end -- end battery right charger 
 -- debug
 --heritage_debug1=battery_a_amps
 --setDataf(findDataref("Gastonreif/Heritage/debug1"),heritage_debug1)
 --heritage_debug2=SOME_ACESS_AVAIL
 --setDataf(findDataref("Gastonreif/Heritage/debug1"),heritage_debug1)
 -- Oxygen counters
 if OXYGEN_XP_CREW_OPEN == 1 then
  -- crew 1200 seconds is capacity for 20 minutes 
  if oxygen_crew_psig >= 600 then
   oxygen_crew_psig = oxygen_crew_psig - 1
  else -- 20 minutes passed 
   oxygen_crew_psig = oxygen_crew_psig - 5 -- 120 seconds 
   if oxygen_crew_psig <= 0 then oxygen_crew_psig = 0 end
  end
  -- pax 1320 seconds is capacity for 22 minutes 
  if OXYGEN_XP_PSIG >= 480 then
   OXYGEN_XP_PSIG=OXYGEN_XP_PSIG-1
   setDataf(findDataref("sim/cockpit2/oxygen/indicators/o2_bottle_pressure_psi"),OXYGEN_XP_PSIG)
  else-- 22 minutes passed 
   OXYGEN_XP_PSIG=OXYGEN_XP_PSIG-5 -- 96 sec to zero 
   setDataf(findDataref("sim/cockpit2/oxygen/indicators/o2_bottle_pressure_psi"),OXYGEN_XP_PSIG)
   if OXYGEN_XP_PSIG <= 0 then 
   	OXYGEN_XP_PSIG = 0
   	setDataf(findDataref("sim/cockpit2/oxygen/indicators/o2_bottle_pressure_psi"),OXYGEN_XP_PSIG)
   	OXYGEN_XP_CREW_OPEN = 0 
	setDatai(findDataref("sim/cockpit2/oxygen/actuators/o2_valve_on"),OXYGEN_XP_CREW_OPEN)
   end -- end empty 
  end --end masks on 
 end -- end oxygen valve 
 -- replenish Oxygen bottles
 if REFUEL_AVAILABLE == 9 and OXYGEN_XP_PSIG <= 479 then
  OXYGEN_XP_PSIG=1800 --initial O2 reserves
  setDataf(findDataref("sim/cockpit2/oxygen/indicators/o2_bottle_pressure_psi"),OXYGEN_XP_PSIG)
 end
 -- V1.99 exterior lights counter logic 
 -- mode 0 is standing, 12 reds, then 4 white 
 if flash_mode_strobes == 0 then
  red_flash_counted = red_flash_counted + 1
  if red_flash_counted == 1 then 
   white_flash_counted = -1 
   counter_light_strobe_white = 0
  end -- reset white 
  if red_flash_counted >= 13 then 
   red_flash_counted = 13
   --white started
   white_flash_counted = white_flash_counted + 1
   if white_flash_counted >= 5 then 
   	white_flash_counted = 5 -- reset above 
	counter_light_strobe_red = 0
   	red_flash_counted = 0 -- reset red and exit, start over again
   end
  end
 end
 -- mode 1 is taxiing, 4 reds, then 4 white
 if flash_mode_strobes == 1 then
  red_flash_counted = red_flash_counted + 1
  if red_flash_counted == 1 then 
   white_flash_counted = 0 
   counter_light_strobe_white = 0
  end -- reset white 
  if red_flash_counted >= 5 then 
   red_flash_counted = 5
   --white started
   white_flash_counted = white_flash_counted + 1
   if white_flash_counted >= 5 then 
   	white_flash_counted = 5 -- reset above 
 	counter_light_strobe_red = 0
   	red_flash_counted = 0 -- reset red and exit, start over again
   end
  end
 end
 -- mode 2 is flight, 1 reds, then 1 white
 --if flash_mode_strobes == 2 then
 -- counter_light_strobe_white = 0
 -- red_flash_counted = red_flash_counted + 1
 -- if red_flash_counted == 1 then 
 --  white_flash_counted = 0 
 --  counter_light_strobe_white = 0
 -- end -- reset white 
 -- if red_flash_counted >= 2 then 
 --  red_flash_counted = 2
 -- end
 --end
   --white started
 --if red_flash_counted == 2 then
 --  counter_light_strobe_red = 0
 --  white_flash_counted = white_flash_counted + 1
 --  if white_flash_counted >= 2 then 
 --  	white_flash_counted = 2 -- reset above 
 --	counter_light_strobe_red = 0
 --  	red_flash_counted = 1 -- reset red and exit, start over again
 --  end
 --end
 -- old V1 buggy 
 --V2 lights
 -- mode 2 is flight, 1 reds, then 1 white
 if flash_mode_strobes == 2 then
  -- red 
  if PINGPONG <= 0 then
   red_flash_counted = red_flash_counted + 1
   if red_flash_counted >= 1 then
    red_flash_counted = 1
    LIGHT_STROBE_FLASH=1
    setDatai(findDataref("sim/flightmodel2/lights/strobe_flash_now"),LIGHT_STROBE_FLASH)
	light_strobe_red = 1 -- flash
	counter_light_strobe_red = match_frame_rate*1.2 -- 2msec delay 
	white_flash_counted = 0 -- reset
   end
  else
  -- white 
   white_flash_counted = white_flash_counted + 1
   if white_flash_counted >= 1 then
    white_flash_counted = 1
    LIGHT_STROBE_FLASH=1
    setDatai(findDataref("sim/flightmodel2/lights/strobe_flash_now"),LIGHT_STROBE_FLASH)
	light_strobe_white = 1 -- flash
	counter_light_strobe_white = match_frame_rate*1.2
	red_flash_counted = 0 -- reset
   end
  end
 end
 heritage_debug8=red_flash_counted
 setDataf(findDataref("Gastonreif/Heritage/debug8"),heritage_debug8)
 heritage_debug9=white_flash_counted
 setDataf(findDataref("Gastonreif/Heritage/debug9"),heritage_debug9)
 -- ADC test mode MON steps 
 if ADC1_TEST_ROT == -1 or ADC2_TEST_ROT == -1 then
  adc1_in_testmode = adc1_in_testmode + 1 -- seqencer, every five seconds 
  -- 1 test alpha incidence 
  -- 5 autopilot
  -- 10 trim 
  -- 15 art. feel 
  -- 20 autostab 
  -- 25 ins 
  -- 30 CG 
  -- 35 stall 
  if adc1_in_testmode >= 36 then adc1_in_testmode = 36 end
 end
 if ADC1_TEST_ROT == 0 and ADC2_TEST_ROT == 0 then
  adc1_in_testmode = 0 -- reset seqencer
  adc2_in_testmode = 0
 end
 if ADC1_TEST_ROT == 1 or ADC2_TEST_ROT == 1 then
  adc2_in_testmode = adc2_in_testmode + 1 -- seqencer, every five seconds 
  -- 1 altitude 
  -- 5 airspeed
  -- 10 others 
  if adc2_in_testmode >= 11 then adc2_in_testmode = 11 end
 end
end -- end function 
--random generator
function random_generator()
 -- RND 
 if RANDGEN >= 0.00001 then --run save after transponder is active
    --TEST2 = 1 -- debug item 3 can be shown on datarefs TESTVALUE3
       if random_saved == false then -- save random value once for decision
	    random_saved_value = RANDGEN --actual saved value in uSv/h of dose
		--TEST3 = random_saved_value -- debug item 3 can be shown on datarefs TESTVALUE3
		--play_sound(FOUR) -- debug sound, disable
		--setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3) --OK seems works
		random_saved = true
       end 
	--else TEST2 = 0
	-- second random generator for signs by ping pong -1 + 1
   if random2_saved == false then -- save random2 value once for decision
   	random2_saved_value = PINGPONG + 0.9 -- offset, we expect mostly plus 
    random2_saved = true
   end 
   -- set ISA sign 
	if random2_saved_value >= 0 then 
	 CON_ISA_SIGN = 0 -- means plus 
	 setDatai(findDataref("Colimata/CON_CC_TEMP_isa_plus_minus_i"),CON_ISA_SIGN)
	else
	 CON_ISA_SIGN = 1 -- means minus 
	 setDatai(findDataref("Colimata/CON_CC_TEMP_isa_plus_minus_i"),CON_ISA_SIGN)
	end
   -- set ISA temperature upto 20
    if random_saved_value <= 0.0001 then
     CON_ISA = 1
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.0001 and random_saved_value <= 0.005 then
     CON_ISA = 2
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.005 and random_saved_value <= 0.01 then
     CON_ISA = 3
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.01 and random_saved_value <= 0.05 then
     CON_ISA = 4
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.05 and random_saved_value <= 0.1 then
     CON_ISA = 5
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.1 and random_saved_value <= 0.2 then
     CON_ISA = 6
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.2 and random_saved_value <= 0.3 then
     CON_ISA = 7
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.3 and random_saved_value <= 0.4 then
     CON_ISA = 8
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.4 and random_saved_value <= 0.6 then
     CON_ISA = 9
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.6 and random_saved_value <= 0.8 then
     CON_ISA = 10
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.8 and random_saved_value <= 0.91 then
     CON_ISA = 11
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.91 and random_saved_value <= 0.92 then
     CON_ISA = 12
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.92 and random_saved_value <= 0.93 then
     CON_ISA = 13
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.93 and random_saved_value <= 0.94 then
     CON_ISA = 14
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.94 and random_saved_value <= 0.95 then
     CON_ISA = 15
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.95 and random_saved_value <= 0.96 then
     CON_ISA = 16
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.96 and random_saved_value <= 0.97 then
     CON_ISA = 17
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.97 and random_saved_value <= 0.98 then
     CON_ISA = 18
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.98 and random_saved_value <= 0.99 then
     CON_ISA = 19
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
    if random_saved_value > 0.99 then
     CON_ISA = 20
     setDatai(findDataref("Colimata/CON_CC_TEMP_isa_deg_i"),CON_ISA)
    end
   -- end ISA table 
 end
end

