function failures_on()
 --birdstrike
 if FAIL_BIRDSTRIKE == 1 then
  if random_saved_value >= 0.0 and random_saved_value <= 0.00025 then
   birdstrike_on_1=1
   else
   birdstrike_on_1=0
  end
  if random_saved_value >= 0.00026 and random_saved_value <= 0.00050 then
   birdstrike_on_2=1
   else
   birdstrike_on_2=0
  end
  if random_saved_value >= 0.00051 and random_saved_value <= 0.00075 then
   birdstrike_on_3=1
   else
   birdstrike_on_3=0
  end
  if random_saved_value >= 0.00076 and random_saved_value <= 1.0 then
   birdstrike_on_4=1
   else
   birdstrike_on_4=0
  end
 end
 --engine 1
 engine1_is_overheated=FAIL_ENG1_FLAME+FAIL_ENG1_FIRE+birdstrike_on_1+cty1_limit+rev1_limit+oheat_test1+tca1_fail
 --TEST3=engine1_is_overheated
 --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
 --engine 2
 engine2_is_overheated=FAIL_ENG2_FLAME+FAIL_ENG2_FIRE+birdstrike_on_2+cty2_limit+rev2_limit+oheat_test2+tca2_fail
 --engine 3
 engine3_is_overheated=FAIL_ENG3_FLAME+FAIL_ENG3_FIRE+birdstrike_on_3+cty3_limit+rev3_limit+oheat_test3+tca3_fail
 --engine 4
 engine4_is_overheated=FAIL_ENG4_FLAME+FAIL_ENG4_FIRE+birdstrike_on_4+cty4_limit+rev4_limit+oheat_test4+tca4_fail
 --fuel leak 
 if FAIL_FUELLEAK == 1 then
  if random_saved_value >= 0.0 and random_saved_value <= 0.00025 then
   fuelleak_on_1=1
   else
   fuelleak_on_1=0
  end
  if random_saved_value >= 0.00026 and random_saved_value <= 0.00050 then
   fuelleak_on_4=1
   else
   fuelleak_on_4=0
  end
  if random_saved_value >= 0.00051 and random_saved_value <= 0.00075 then
   fuelleak_on_3=1
   else
   fuelleak_on_3=0
  end
  if random_saved_value >= 0.00076 and random_saved_value <= 1.0 then
   fuelleak_on_2=1
   else
   fuelleak_on_2=0
  end
 end 
--  
end

