 -- ADC1 
 --prerequisites, for example when pitot icing
 speed_discrepacy_absolute = math.abs(INDICATOR_PILOT_AIRSPEED - indicated_air_speed)
 if speed_discrepacy_absolute >= 50 then SPEED_DISCREPACY = 1 else SPEED_DISCREPACY = 0 end
 --
 altimeter_discrepacy_absolute_pilot = INDICATOR_PILOT_ALTITUDE - INDICATOR_COPILOT_ALTITUDE
 if altimeter_discrepacy_absolute_pilot >= 250 then ALTIMETER_PILOT_DISCREPACY = 1 else ALTIMETER_PILOT_DISCREPACY = 0 end
 ADC1_FAILURE = SPEED_DISCREPACY + ALTIMETER_PILOT_DISCREPACY
 --
 if ADC1_FAILURE ~= 0 then
  if ADC1_SW == 1 then 
   light_console_adc1=1
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc1"),light_console_adc1)
  else -- de-energize warning, switch is off 
   light_console_adc1=0
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc1"),light_console_adc1)
  end
 else
  if adc2_in_testmode == 1 or adc2_in_testmode == 5  then 
   light_console_adc1=1
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc1"),light_console_adc1)
  else
   light_console_adc1=0
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc1"),light_console_adc1)
  end
 end
 -- ADC2
 --prerequisites
 altitude_discrepacy_absolute = math.abs(INDICATOR_PILOT_ALTITUDE - altitude)
 if altitude_discrepacy_absolute >= 1000 then ALTITUDE_DISCREPACY = 1 else ALTITUDE_DISCREPACY = 0 end
 --
 altimeter_discrepacy_absolute_copilot = INDICATOR_COPILOT_ALTITUDE - INDICATOR_PILOT_ALTITUDE
 if altimeter_discrepacy_absolute_copilot >= 250 then ALTIMETER_COPILOT_DISCREPACY = 1 else ALTIMETER_COPILOT_DISCREPACY = 0 end
 ADC2_FAILURE = ALTITUDE_DISCREPACY + ALTIMETER_COPILOT_DISCREPACY
 --
 if ADC2_FAILURE ~= 0 then
  if ADC2_SW == 1 then 
   light_console_adc2=1
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc2"),light_console_adc2)
  else --de-energize warning, switch is off 
   light_console_adc2=0
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc2"),light_console_adc2)
  end
 else
  if adc2_in_testmode == 10  then 
   light_console_adc2=1
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc2"),light_console_adc2)
  else
   light_console_adc2=0
   setDatai(findDataref("Gastonreif/Heritage/light_console_adc2"),light_console_adc2)
  end
 end
 -- ADC TEST 1
 --prerequisites
 -- TEST2 , overspeed and nose down 
 if ADC1_TEST_ROT == -3 then 
  if touch_down == 1 then -- only at ground 
   adc_delay_counter = adc_delay_counter + 0.01
   VMO_EXCEEDED = 1
   setDatai(findDataref("Colimata/CON_IP_AIRSPEED_FLAG_Vmo_i"),VMO_EXCEEDED)
   if adc_delay_counter >= 2 and adc_delay_counter <= 3 then 
    NOSE_DOWN_GREEN = 1
    setDatai(findDataref("Colimata/CON_IP_lgt_nv_green_lgt_i"),NOSE_DOWN_GREEN)
	light_console_test1=0
    setDatai(findDataref("Gastonreif/Heritage/light_console_test1"),light_console_test1)
   else
    NOSE_DOWN_GREEN = 0
    setDatai(findDataref("Colimata/CON_IP_lgt_nv_green_lgt_i"),NOSE_DOWN_GREEN)
   end
   if adc_delay_counter >= 4 then 
    light_console_test1=1
    setDatai(findDataref("Gastonreif/Heritage/light_console_test1"),light_console_test1)
	adc_delay_counter = 4
   --else
   -- light_console_test1=0
   -- setDatai(findDataref("Gastonreif/Heritage/light_console_test1"),light_console_test1)
   end
  end
  whoop_whoop_signal = 0
 end
 -- TEST1 , excessive angle of attack, stall warning 
 if ADC1_TEST_ROT == -2 then 
  if touch_down == 1 then -- only at ground 
   adc_delay_counter = adc_delay_counter + 0.01 
   if adc_delay_counter >= 1 and adc_delay_counter <= 2 then 
    light_console_test1=0
    setDatai(findDataref("Gastonreif/Heritage/light_console_test1"),light_console_test1)
   end
   if adc_delay_counter >= 5 and adc_delay_counter <= 6 then 
    whoop_whoop_signal = 1
   end
   if adc_delay_counter >= 7 then
    light_console_test1=1
    setDatai(findDataref("Gastonreif/Heritage/light_console_test1"),light_console_test1)
	adc_delay_counter = 0 -- reset for -3 mode 
	whoop_whoop_signal = 0
   --else
   -- light_console_test1=0
   -- setDatai(findDataref("Gastonreif/Heritage/light_console_test1"),light_console_test1)
   end 
   -- resets 
   VMO_EXCEEDED = 0 -- reset previous only here 
   setDatai(findDataref("Colimata/CON_IP_AIRSPEED_FLAG_Vmo_i"),VMO_EXCEEDED)
   NOSE_DOWN_GREEN = 0 -- reset previous only here 
   setDatai(findDataref("Colimata/CON_IP_lgt_nv_green_lgt_i"),NOSE_DOWN_GREEN)
   AP_LIGHT_ON = 0
