   MCG_WARN_RED = 0
   setDatai(findDataref("Colimata/CON_RF_lgt_MASTER_MCG_i"),MCG_WARN_RED)
  end
 end
 -- MONitor , create failure instruments
 if ADC1_TEST_ROT == -1 then 
