function enhanced_start_up()
  --ground switch corrector
  if GROUND_SWITCH == 0 then GROUND_SWITCH_ON = 1 end --closed
  if GROUND_SWITCH == 1 then --tripped
   GROUND_SWITCH_ON = 0 
   GROUND_HYD_SWITCH1 = 0
   setDatai(findDataref("Colimata/CON_EG_CPR_sw_pump_1_i"),GROUND_HYD_SWITCH1)
   GROUND_HYD_SWITCH2 = 0
   setDatai(findDataref("Colimata/CON_EG_CPR_sw_pump_2_i"),GROUND_HYD_SWITCH2)
  end 
  --ground power or engine running
  RESULT5_COUNT = ENG1_N1 + ENG2_N1 + ENG3_N1 + ENG4_N1 -- check if some engines are providing power
  --TEST1 = RESULT5_COUNT
  if RESULT5_COUNT >= 40 then WEHAVEPOWER_E = 1 else WEHAVEPOWER_E = 0 end -- by engine power available

  if GPU_UNIT_ON == 1 and GROUND_SWITCH_ON == 1 then WEHAVEPOWER_G = 1 end -- ground power available, ground switch is on, power on
  if GPU_UNIT_ON == 1 and GROUND_SWITCH_ON == 0 then WEHAVEPOWER_G = 0 end -- ground power available, ground switch is off, no power
  if GPU_UNIT_ON == 0 and GROUND_SWITCH_ON == 1 then WEHAVEPOWER_G = 0 end -- no ground power, no power at all
  if GPU_UNIT_ON == 0 and GROUND_SWITCH_ON == 0 then WEHAVEPOWER_G = 0 end -- no ground power, no power at all
  --ground hydraulics
  if GROUND_HYD_SWITCH1 == 1 or GROUND_HYD_SWITCH2 == 1 then WEHAVEAIR_G = 1 end -- ground hyd yellow (two top left switches on EG panel)
  if GROUND_HYD_SWITCH1 == 0 or GROUND_HYD_SWITCH2 == 0 then WEHAVEAIR_G = 0 end -- no ground hydraulics
    --ground idle fuel flow disabled
  ----if WEHAVEPOWER_E == 1 and speed <= 60 then
  -- GROUND_IDLE14 = 1
   --setDatai(findDataref("Colimata/CON_EG_CPR_sw_eng14_grd_i"),GROUND_IDLE14)
  -- GROUND_IDLE23 = 1
  -- setDatai(findDataref("Colimata/CON_EG_CPR_sw_eng23_grd_i"),GROUND_IDLE23)
  ----end
  --hydraulics
  HYDR_A = HYD_BLUE_3 + HYD_BLUE_4 + HYD_GREEN_1 + HYD_GREEN_2 --0 all on, 1+1+1+1 all off, 2+2+2+2 all shut
  HYDR_G = HYD_YELLOW_2 + HYD_YELLOW_4 -- 1 is mmaximum, normal is 0 as ON
  --TEST1 = HYDR_G
  --if touch_down == 0 then --on air 
  if speed >= 180 then --on air 
   -- if HYDR_G >=3 then --possible bug here now disabled
    --   RAM_AIR_COVER1 = 1 -- emergency hydraulics automatic on and ram air turnine on, not need to disable
	--   RAM_AIR_COVER2 = 1
    --   RAM_AIR_1 = 1
	--   RAM_AIR_2 = 1
	--   WEHAVEPOWER_B = 1
	--   else 
	 --  WEHAVEPOWER_B = 0
	--end 
	if HYDR_A >=4 then
       RAM_AIR_COVER1 = 1
	   setDatai(findDataref("Colimata/CON_EG_LL_sw_RAT_1_cover_i"),RAM_AIR_COVER1)
	   RAM_AIR_COVER2 = 1
	   setDatai(findDataref("Colimata/CON_EG_LL_sw_RAT_2_cover_i"),RAM_AIR_COVER2)
       RAM_AIR_1 = 1
	   setDatai(findDataref("Colimata/CON_EG_LL_sw_RAT_1_i"),RAM_AIR_1) 
	   RAM_AIR_2 = 1
	   setDatai(findDataref("Colimata/CON_EG_LL_sw_RAT_2_i"),RAM_AIR_2)
	   WEHAVEPOWER_B = 1
	   else 
	   WEHAVEPOWER_B = 0
    end
  else 
  WEHAVEPOWER_B = 0 --no ram air power on ground while not moving - protection
  --TEST2 = WEHAVEPOWER_B
  end
  
  --ENG1 green, ENG2 yellow/green, ENG3 blue, ENG4 yellow/blue
  --check engines power for available hydraulics systems
  --green
  if ENG1_N1 <= 20 and ENG2_N1 <= 20 then
   if WEHAVEPOWER_B == 0 then -- when RAT are deployed one green hydraulic is still usable
   HYD_GREEN_1 = 1 -- 0 is ON, 1 is off, 2 is shut
   setDatai(findDataref("Colimata/CON_EG_HYD_sw_pump_1_green_i"),HYD_GREEN_1)
   end
   HYD_GREEN_2 = 1
   setDatai(findDataref("Colimata/CON_EG_HYD_sw_pump_2_green_i"),HYD_GREEN_2)
  end 
  --end green
  --blue
  if ENG3_N1 <= 20 and ENG4_N1 <= 20 then
   HYD_BLUE_3 = 1 -- 0 is ON, 1 is off, 2 is shut
   setDatai(findDataref("Colimata/CON_EG_HYD_sw_pump_3_blue_i"),HYD_BLUE_3)
   HYD_BLUE_4 = 1
   setDatai(findDataref("Colimata/CON_EG_HYD_sw_pump_4_blue_i"),HYD_BLUE_4)
  end 
  --blue end
  --yellow
  if ENG2_N1 <= 20 then 
   if HYD_YELLOW_2 == 0 then -- on 
   	HYD_YELLOW_2 = 1
    setDatai(findDataref("Colimata/CON_EG_HYD_sw_pump_2_yellow_i"),HYD_YELLOW_2)
   end
  end
  if ENG4_N1 <= 20 then
   if HYD_YELLOW_4 == 0 then -- on 
   	HYD_YELLOW_4 = 1
    setDatai(findDataref("Colimata/CON_EG_HYD_sw_pump_4_yellow_i"),HYD_YELLOW_4)
   end
  end
  --yellow end
  --yellow check -only for nose position
  --if HYDR_G >= 2 then --both off, jam the current nose position --not work now
   --if NOSE_POSITION <= 0 then NOSE_POSITION = 0 end
   --if NOSE_POSITION >= 1 then NOSE_POSITION = NOSE_POSITION-0 end
   --if NOSE_POSITION == 1 then NOSE_POSITION = 1 end
   --if NOSE_POSITION == 2 then NOSE_POSITION = 2 end
   --if NOSE_POSITION == 3 then NOSE_POSITION = 3 end
  --end
  --end yellow
  --ailerons check for power -- 0 is blue, 1 is green, 2 is mech
  HYDR_B = HYD_BLUE_3 + HYD_BLUE_4 -- 0 is OK
  HYDR_C = HYD_GREEN_1 + HYD_GREEN_2
  if HYDR_B >= 2 then --no blue avail
    if ELEV_IN_SW == 0 then
	 ELEV_IN_SW = 1
	 setDatai(findDataref("Colimata/CON_RF_ELEC_sw_elev_in_i"),ELEV_IN_SW)
	end -- switch to green
    if ELEV_OM_SW == 0 then 
	 ELEV_OM_SW = 1
	 setDatai(findDataref("Colimata/CON_RF_ELEC_sw_elev_om_i"),ELEV_OM_SW)
	end
    if ELEV_RUD_SW == 0 then
	 ELEV_RUD_SW = 1
	 setDatai(findDataref("Colimata/CON_RF_ELEC_sw_rudder_i"),ELEV_RUD_SW)
	end
   if HYDR_C >= 2 then --no green avail
      if ELEV_IN_SW == 1 then
	   ELEV_IN_SW = 2
	   setDatai(findDataref("Colimata/CON_RF_ELEC_sw_elev_in_i"),ELEV_IN_SW)
	  end -- fall to mech
      if ELEV_OM_SW == 1 then
	   ELEV_OM_SW = 2
	   setDatai(findDataref("Colimata/CON_RF_ELEC_sw_elev_om_i"),ELEV_OM_SW)
	  end
      if ELEV_RUD_SW == 1 then
	   ELEV_RUD_SW = 2
	   setDatai(findDataref("Colimata/CON_RF_ELEC_sw_rudder_i"),ELEV_RUD_SW)
	  end
   end
  end
--end aileron check
--art feel jack drops
 if HYDR_B >= 2 and HYDR_C >= 2 then --no hydraulics avail
  if STAB1_PITCH == 0 then 
   STAB1_PITCH = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_no1_pitch_i"),STAB1_PITCH)
  end
  if STAB2_PITCH == 0 then 
   STAB2_PITCH = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_no2_pitch_i"),STAB2_PITCH)
  end
  if STAB1_ROLL == 0 then 
   STAB1_ROLL = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_no1_roll_i"),STAB1_ROLL)
  end
  if STAB2_ROLL == 0 then 
   STAB2_ROLL = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_no2_roll_i"),STAB2_ROLL)
  end
  if STAB1_YAW == 0 then
   STAB1_YAW = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_no1_yaw_i"),STAB1_YAW)
  end
  if STAB2_YAW == 0 then 
   STAB2_YAW = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_no2_yaw_i"),STAB2_YAW)
  end
  if FEEL1_PITCH == 0 then 
   FEEL1_PITCH = 1 
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_feel1_pitch_i"),FEEL1_PITCH)
  end
  if FEEL2_PITCH == 0 then 
   FEEL2_PITCH = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_feel2_pitch_i"),FEEL2_PITCH)
  end
  if FEEL1_ROLL == 0 then 
   FEEL1_ROLL = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_feel1_roll_i"),FEEL1_ROLL)
  end
  if FEEL2_ROLL == 0 then
   FEEL2_ROLL = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_feel2_roll_i"),FEEL2_ROLL)
  end
  if FEEL1_YAW == 0 then 
   FEEL1_YAW = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_feel1_yaw_i"),FEEL1_YAW)
  end
  if FEEL2_YAW == 0 then 
   FEEL2_YAW = 1
   setDatai(findDataref("Colimata/CON_RF_AUTOSTAB_feel2_yaw_i"),FEEL2_YAW)
  end
 end
--end art feel drop

  -----start up enhanced procedure
----generator check WORKS OK
--generator test position spring -- disabled
--if ELEC_GEN1 == 2 then 
-- ELEC_GEN1 = 1 
-- setDatai(findDataref("Colimata/CON_EG_ELEC_sw_gen_sel_1_i"),ELEC_GEN1)
--end --sping loads the switch to off
--if ELEC_GEN2 == 2 then 
-- ELEC_GEN2 = 1 
-- setDatai(findDataref("Colimata/CON_EG_ELEC_sw_gen_sel_2_i"),ELEC_GEN2)
--end
--if ELEC_GEN3 == 2 then 
-- ELEC_GEN3 = 1 
-- setDatai(findDataref("Colimata/CON_EG_ELEC_sw_gen_sel_3_i"),ELEC_GEN3)
--end
--if ELEC_GEN4 == 2 then 
-- ELEC_GEN4 = 1 
-- setDatai(findDataref("Colimata/CON_EG_ELEC_sw_gen_sel_4_i"),ELEC_GEN4)
--end
--if WEHAVEPOWER_G == 0 and WEHAVEPOWER_B == 0 then --we have no ground unit on and no backup RAT too, this ensure starting procedure OK
if WEHAVEPOWER_G == 0 and EMERGENCY_GENERATOR_ON == 0 then --we have no ground unit on and no 5th gen on, this ensure starting procedure OK
--TEST1 = 1
--no ssb
if SSB_ON == 0 then --tripped, no power from other source only engines left/right
 --also works for total engine fail
 --left side
 if ENG1_N1 <= 20 and ENG2_N1 <= 20 then -- both engines lost power
    --TEST2 = 1
    if ELEC_GEN1 == 0 then 
	 ELEC_GEN1 = 1 
