   setDatai(findDataref("Colimata/CON_CC_INS1_lgt_alert_i"),INS1_ALERT) 
   INS2_ALERT=0
   setDatai(findDataref("Colimata/CON_CC_INS2_lgt_alert_i"),INS2_ALERT) 
   INS3_ALERT=0
   setDatai(findDataref("Colimata/CON_CC_INS3_lgt_alert_i"),INS3_ALERT) 
  end --end battery protection for last INS1 function 
    -- Depressurization check, part II is in pressurization section 
	if EMERG_DEPRESS_ON == 1 then -- opens the discharge valves
	 if PRESS_DISCHARGE_SYS1_SWITCH ~= 0 then
	  PRESS_DISCHARGE_SYS1_SWITCH=0
	  setDatai(findDataref("Colimata/CON_EG_CPR_sw_disch_sys1_i"),PRESS_DISCHARGE_SYS1_SWITCH)
	 end
	 if PRESS_DISCHARGE_SYS2_SWITCH ~= 0 then
	  PRESS_DISCHARGE_SYS2_SWITCH=0
	  setDatai(findDataref("Colimata/CON_EG_CPR_sw_disch_sys2_i"),PRESS_DISCHARGE_SYS2_SWITCH)
	 end
	end 
	-- 
end

function various_temperatures()
 -- Visor ice corrector
 if visor_is_down == false then -- killer grows, hide windshield icing 
  if visor_was_down == 0 then -- first init only, restart elsewhere
   kill_icing_on_fronts = kill_icing_on_fronts + 0.001 -- we need it faster, visor is by default up
   if kill_icing_on_fronts >= 1 then kill_icing_on_fronts = 1 end
  else -- if visor was down kill is not effective and ice stays
   kill_icing_on_fronts = kill_icing_on_fronts - 0.0001 --veeery slowly decrease killer, icrease icing
   if kill_icing_on_fronts <= 0 then kill_icing_on_fronts = 0 end
  end
 else -- killer decrease, allow show windshield icing 
  kill_icing_on_fronts = kill_icing_on_fronts - 0.0001 --veeery slowly decrease killer, icrease icing
  if kill_icing_on_fronts <= 0 then kill_icing_on_fronts = 0 end
 end
 --de-ice active
 WINDSHIELD_DEICERS = WINDSHIELD_RIGHT + WINDSHIELD_LEFT 
 if WINDSHIELD_DEICERS ~= 0 then -- killer to default
  kill_icing_on_fronts = kill_icing_on_fronts + 0.001 
  if kill_icing_on_fronts >= 1 then kill_icing_on_fronts = 1 end
 end
 -- this variable is in OBJ files for front glass/windshield
 icing_on_front_windows = icing_on_all_windows - kill_icing_on_fronts
 if icing_on_front_windows <= 0 then icing_on_front_windows = 0 end 
