 end
 -- overide of N2
 --prerequisites 1st stage 
 if isa_was_changed == 0 then 
  fast_delay_isa_counter = fast_delay_isa_counter + 1
  if fast_delay_isa_counter >= 350 then -- this is fast so at 150 FPS is 2.2 seconds 
  -- ISA is plus 
  variable_a_affected_isa = -(CON_ISA*0.75) -- prevents routine errors, penalty
  -- ISA is minus 
  variable_b_affected_isa = CON_ISA*0.75 -- advantage
  fast_delay_isa_counter = 0 -- reset
  delay_isa_counter = 0
 end
 else -- isa changed, adjust it slowly, speed and success depends on isa_was_changed duration delay in another section, works sometimes 
  if current_isa_stored < previous_isa_stored then -- increase and match ISA changed 
   -- var a penalty 
   variable_a_affected_isa = variable_a_affected_isa - 0.01
   if variable_a_affected_isa <= -(previous_isa_stored*0.75) then
   	variable_a_affected_isa = -(previous_isa_stored*0.75)
	delay_isa_counter = 0
   end  
   -- var b advantage
   variable_b_affected_isa = variable_b_affected_isa + 0.01
   if variable_b_affected_isa >= previous_isa_stored*0.75 then
   	variable_b_affected_isa = previous_isa_stored*0.75
	delay_isa_counter = 0
   end
  end   
  if current_isa_stored > previous_isa_stored then-- decrease and match ISA which seems lower 
   -- var a penalty 
   variable_a_affected_isa = variable_a_affected_isa + 0.01
   if variable_a_affected_isa >= -(previous_isa_stored*0.75) then
   	variable_a_affected_isa = -(previous_isa_stored*0.75)
	delay_isa_counter = 0
   end  
   -- var b advantage
   variable_b_affected_isa = variable_b_affected_isa - 0.01
   if variable_b_affected_isa <= previous_isa_stored*0.75 then
   	variable_b_affected_isa = previous_isa_stored*0.75
	delay_isa_counter = 0
   end 
  end -- end difference comparsion 
 end
 -- ISA deviation and effects, ISA + 10 means lower N2 and vice versa 
 if CON_ISA_SIGN == 0 then -- 0 is plus
  if isa_was_minus == 1 then -- transition adjustment, if ISA was changed significaly, probably never happens 
   by_isa_affected_performance = by_isa_affected_performance - 0.001 -- we need from 7.5 to -7.5 slow transition
   if by_isa_affected_performance <= variable_a_affected_isa then -- transition limit 
   	by_isa_affected_performance = variable_a_affected_isa
   	isa_was_minus = 0 -- transition done 
   end 
