   	by_isa_affected_performance4 = variable_a_affected_isa
   	isa_was_minus = 0 -- transition done 
   end 
  else -- transition done and normal plus operation 
   -- by_isa_affected_performance = -(CON_ISA*0.75) -- ISA at +10 gives 7.5 % at N2 penalty 
   -- Final N2 behavior
   -- ENG1 
   if ENG1_N2 <= 30 then -- negative N2 protection, first only with + ISA 
 	-- shut off 
 	if engine1_was_running == 1 and engine1_was_running_and_adjusted == 1 then -- do not reset engine1_was_running, used elsewhere 
 	 by_isa_affected_performance = by_isa_affected_performance + 0.01 -- if ISA is +10, there is penalty
 	 if by_isa_affected_performance >= 0 then
 	  by_isa_affected_performance = 0
 	  engine1_was_running_and_adjusted = 0 -- reset to off 
 	 end
 	else -- completely off, default 
 	 by_isa_affected_performance = 0 -- negative N2 protection 
 	 engine1_was_running_and_adjusted = 0 -- reset 
 	end
   else -- running 
 	-- starting 
 	if engine1_was_running == 0 and engine1_was_running_and_adjusted == 0 then -- do not reset engine1_was_running, used elsewhere 
 	 by_isa_affected_performance = by_isa_affected_performance - 0.01
 	 if by_isa_affected_performance <= variable_a_affected_isa then
 	  by_isa_affected_performance = variable_a_affected_isa
	  engine1_was_running = 1
 	  engine1_was_running_and_adjusted = 1
 	 end
 	end
 	-- engine is running, normal operation 
 	if engine1_was_running == 1 and engine1_was_running_and_adjusted == 1 then 
 	  by_isa_affected_performance = variable_a_affected_isa
 	end
    -- shut of in previous condition 
   end 
   -- ENG1 end
   -- ENG2
