 	  by_isa_affected_performance4 = variable_a_affected_isa
 	end
    -- shut of in previous condition 
   end 
   -- ENG4 end
  end -- of normnal ops
  isa_was_plus = 1 -- set transition condition 
 end
 if CON_ISA_SIGN == 1 then -- 1 is minus 
  if isa_was_plus == 1 then -- transition adjustment 
   by_isa_affected_performance = by_isa_affected_performance + 0.001 -- we need from -7.5 to +7.5 slow transition
   if by_isa_affected_performance >= variable_b_affected_isa then -- transition limit 
   	by_isa_affected_performance = variable_b_affected_isa
   	isa_was_plus = 0 -- transition done 
   end 
   by_isa_affected_performance2 = by_isa_affected_performance2 + 0.001 -- we need from -7.5 to +7.5 slow transition
   if by_isa_affected_performance2 >= variable_b_affected_isa then -- transition limit 
