 	  engine3_was_running_and_adjusted = 0 -- reset to off 
 	 end
 	else -- completely off, default 
 	 by_isa_affected_performance3 = 0 -- negative N2 protection 
 	 engine3_was_running_and_adjusted = 0 -- reset 
 	end
   else -- running 
 	-- starting 
 	if engine3_was_running == 0 and engine3_was_running_and_adjusted == 0 then -- do not reset engine1_was_running, used elsewhere 
 	 by_isa_affected_performance3 = by_isa_affected_performance3 + 0.01
 	 if by_isa_affected_performance3 >= variable_b_affected_isa then
 	  by_isa_affected_performance3 = variable_b_affected_isa
	  engine3_was_running = 1
 	  engine3_was_running_and_adjusted = 1
 	 end
 	end
 	-- engine is running, normal operation 
 	if engine3_was_running == 1 and engine3_was_running_and_adjusted == 1 then -- do not reset engine1_was_running, used elsewhere 
 	  by_isa_affected_performance3 = variable_b_affected_isa
 	end
    -- shut of in previous condition 
   end 
   -- ENG3 end
   -- ENG4 
   if ENG4_N2 <= 30 then -- negative N2 protection, first only with + ISA 
 	-- shut off 
 	if engine4_was_running == 1 and engine4_was_running_and_adjusted == 1 then 
 	 by_isa_affected_performance4 = by_isa_affected_performance4 - 0.01 -- if ISA is -10, there is benefit
 	 if by_isa_affected_performance4 <= 0 then
 	  by_isa_affected_performance4 = 0
 	  engine4_was_running_and_adjusted = 0 -- reset to off 
 	 end
 	else -- completely off, default 
 	 by_isa_affected_performance4 = 0 -- negative N2 protection 
 	 engine4_was_running_and_adjusted = 0 -- reset 
 	end
   else -- running 
 	-- starting 
 	if engine4_was_running == 0 and engine4_was_running_and_adjusted == 0 then -- do not reset engine1_was_running, used elsewhere 
 	 by_isa_affected_performance4 = by_isa_affected_performance4 + 0.01
 	 if by_isa_affected_performance4 >= variable_b_affected_isa then
 	  by_isa_affected_performance4 = variable_b_affected_isa
	  engine4_was_running = 1
 	  engine4_was_running_and_adjusted = 1
 	 end
 	end
 	-- engine is running, normal operation 
 	if engine4_was_running == 1 and engine4_was_running_and_adjusted == 1 then -- do not reset engine1_was_running, used elsewhere 
 	  by_isa_affected_performance4 = variable_b_affected_isa
 	end
    -- shut of in previous condition 
   end 
   -- ENG4 end
  end
  isa_was_minus = 1
 end
