 -- ENGINE CONTROL SCHEDULE
 -- first two manual modes 
 if ENGCONTROL_SCHEDULE_HILO == 2 then -- dry power - LO 
  eng1_con_status = 0 -- switch to lo 
  eng2_con_status = 0 
  eng3_con_status = 0 
  eng4_con_status = 0 
 end
 if ENGCONTROL_SCHEDULE_HILO == 1 then -- eff. power - HI
  -- prerequisites
  if GEAR_DOWN == 1 then 
  	eng1_con_status = 0 -- switch to lo 
  	eng2_con_status = 0 
  	eng3_con_status = 0 
  	eng4_con_status = 0 
  end 
  if GEAR_DOWN == 0 then 
   if FLIGHT_RATING_1 == 0 and REHEAT_1 == 0 then eng1_con_status = 0 end -- after reheated takeoff, switch to lo 
   if FLIGHT_RATING_2 == 0 and REHEAT_2 == 0 then eng2_con_status = 0 end 
   if FLIGHT_RATING_3 == 0 and REHEAT_3 == 0 then eng3_con_status = 0 end 
   if FLIGHT_RATING_4 == 0 and REHEAT_4 == 0 then eng4_con_status = 0 end 
   if FLIGHT_RATING_1 == 1 and REHEAT_1 == 0 then eng1_con_status = 1 end -- reheated climb, switch to mid 
   if FLIGHT_RATING_2 == 1 and REHEAT_2 == 0 then eng2_con_status = 1 end 
   if FLIGHT_RATING_3 == 1 and REHEAT_3 == 0 then eng3_con_status = 1 end 
   if FLIGHT_RATING_4 == 1 and REHEAT_4 == 0 then eng4_con_status = 1 end 
  end 
 end
  -- end of two manual modes
  -- Engine control schedule AUTO 
 if ENGCONTROL_SCHEDULE_HILO == 0 then
  if ENGCONTROL_SCHEDULE_SWITCH == 0 then -- normal 
   if speed > 220 then 
    if REHEAT_1 == 2 then eng1_con_status = 2 end -- select hi 
    if REHEAT_2 == 2 then eng2_con_status = 2 end
    if REHEAT_3 == 2 then eng3_con_status = 2 end
    if REHEAT_4 == 2 then eng4_con_status = 2 end
    -- reheated climb 
    if REHEAT_1 == 0 then 
     if FLIGHT_RATING_1 == 1 and CRUISE_1 == 0 then eng1_con_status = 1 end -- select mid 
    end
    if REHEAT_2 == 0 then 
     if FLIGHT_RATING_2 == 1 and CRUISE_2 == 0 then eng2_con_status = 1 end
    end
    if REHEAT_3 == 0 then 
     if FLIGHT_RATING_3 == 1 and CRUISE_3 == 0 then eng3_con_status = 1 end 
    end
    if REHEAT_4 == 0 then 
     if FLIGHT_RATING_4 == 1 and CRUISE_4 == 0 then eng4_con_status = 1 end
    end
   end
  end  
  --
  if ENGCONTROL_SCHEDULE_SWITCH == -1 then -- flyover
   if speed > 220 and MACH_SPEED_VALUE < 1 then 
   	if REHEAT_1 == 2 then eng1_con_status = 3 end -- select flyover 
   	if REHEAT_2 == 2 then eng2_con_status = 3 end
   	if REHEAT_3 == 2 then eng3_con_status = 3 end
   	if REHEAT_4 == 2 then eng4_con_status = 3 end
   end
   -- over M 1.0
   if MACH_SPEED_VALUE >= 1 then 
   	if REHEAT_1 == 2 then eng1_con_status = 2 end -- select hi 
   	if REHEAT_2 == 2 then eng2_con_status = 2 end
   	if REHEAT_3 == 2 then eng3_con_status = 2 end
   	if REHEAT_4 == 2 then eng4_con_status = 2 end
   end
  end 
  --
  if ENGCONTROL_SCHEDULE_SWITCH == 1 then -- approach 
   if touch_down ~= 1 then -- only on air 
   	eng1_con_status = 1  -- select mid
   	eng2_con_status = 1
   	eng3_con_status = 1 
   	eng4_con_status = 1
   end
  end
  -- any position here 
  if ENGCONTROL_SCHEDULE_SWITCH ~= 1 then -- except approach 
   if speed <= 220 then 
   	eng1_con_status = 0 -- select lo
   	eng2_con_status = 0
   	eng3_con_status = 0
   	eng4_con_status = 0
   end  
  end
 end -- end all rotary under auto 
