  	--exclusive ENG4 TO limiter here only
  	if speed <= 60 and TO4_LIMITER_SWITCH == 0 then
     --if ENG4_N1 >=88 then ENG4_N1 = 88 end --temporary disabled because stuck at 88
     ENG4_GREEN_LIGHT = 0
    end
   if TO_MONITOR_ENG1_FAIL ~= 0 then 
     ENG1_GREEN_LIGHT = 0
   end --eng ENG1
   if TO_MONITOR_ENG2_FAIL ~= 0 then 
     ENG2_GREEN_LIGHT = 0
   end --eng ENG2
   if TO_MONITOR_ENG3_FAIL ~= 0 then 
     ENG3_GREEN_LIGHT = 0
   end --eng ENG3
   if TO_MONITOR_ENG4_FAIL ~= 0 then 
     ENG4_GREEN_LIGHT = 0
   end --eng ENG4 
  end -- end TO monitor active 
 end -- end OAT low 
end -- end light tests
 --naccelle overheat 
 if FIRE_NAC_OHEAT_TEST_SWITCH == 0 then
  nacoheat_test1 = 0
  nacoheat_test2 = 0
  nacoheat_test3 = 0
  nacoheat_test4 = 0
 end
 if FIRE_NAC_OHEAT_TEST_SWITCH >= 1 and FIRE_NAC_OHEAT_TEST_SWITCH <= 3 then
  nacoheat_test1 = 1
  nacoheat_test2 = 1
  nacoheat_test3 = 1
  nacoheat_test4 = 1
 end
 if FIRE_NAC_OHEAT_TEST_SWITCH == 4 then
  nacoheat_test1 = 1
  nacoheat_test2 = 0
  nacoheat_test3 = 0
  nacoheat_test4 = 0
 end
 if FIRE_NAC_OHEAT_TEST_SWITCH == 5 then
  nacoheat_test1 = 0
  nacoheat_test2 = 1
  nacoheat_test3 = 0
  nacoheat_test4 = 0
 end
 if FIRE_NAC_OHEAT_TEST_SWITCH == 6 then
  nacoheat_test1 = 0
  nacoheat_test2 = 0
  nacoheat_test3 = 1
  nacoheat_test4 = 0
 end
 if FIRE_NAC_OHEAT_TEST_SWITCH == 7 then
  nacoheat_test1 = 0
  nacoheat_test2 = 0
  nacoheat_test3 = 0
  nacoheat_test4 = 1
 end
 NACOHEAT_1 = FAIL_NACWING_LEFT + nacoheat_test1
 NACOHEAT_2 = FAIL_NACWING_LEFT + nacoheat_test2
 NACOHEAT_3 = FAIL_NACWING_RIGHT + nacoheat_test3
 NACOHEAT_4 = FAIL_NACWING_RIGHT + nacoheat_test4
 -- V 1.5 dials 
 -- Air Intake error indicators, off state all left 
  -- ideal table min/max/ideal
  -- MACH no -        Altitude        - N2 -    OAT       - Ramp 
  -- 1.3       38.000/56.000/38.000    100 - -80/-30/-60 - 0
  -- 1.4       40.000/60.000/40.000    100 - -70/-30/-60 - 5
  -- 1.5       41.000/60.000/41.000    100 - -80/-35/-60 - 10
  -- 1.6       42.000/60.000/42.000    100 - -80/-35/-60 - 20
  -- 1.7       43.000/60.000/43.000    100 - -80/-35/-60 - 30
  -- 1.8       45.000/60.000/45.000    100 - -85/-35/-60 - 40
  -- 1.9       48.000/60.000/48.000    100 - -87/-35/-60 - 45
  -- 2.0       50.000/60.000/50.000    100 - -90/-35/-60 - 50
  --get altitude coeficient
  ie_coef_1 = 1-(altitude / 100000) --altitude coeficient in range of 0.1-0.6
  --ie_coef_1 = 1 - (altitude / 100000) --altitude coeficient in range of 0.1-0.6
  --limits protection
  if ie_coef_1 <= 0.4 then ie_coef_1 = 0.4 end
  if ie_coef_1 >= 0.7 then ie_coef_1 = 0.7 end
  --get OAT 
  --ie_coef_2 = 1 - math.abs(OAT/100)
  --if ie_coef_2 <= 0.2 then ie_coef_2 = 0.2 end
  --if ie_coef_2 >= 0.7 then ie_coef_2 = 0.7 end
   --get MACH
  ie_coef_2 = 1 - (MACH_SPEED_VALUE/4)
  if ie_coef_2 <= 0.5 then ie_coef_2 = 0.5 end
  if ie_coef_2 >= 0.675 then ie_coef_2 = 0.675 end
  --get N1 ENG1 
  	ie_coef_3_ENG_1 = 1-(ENG1_N1/100)
  if ie_coef_3_ENG_1 <= 0.1 then ie_coef_3_ENG_1 = 0.1 end
  if ie_coef_3_ENG_1 >= 1 then ie_coef_3_ENG_1 = 1 end
  --get N1 ENG2 
  	ie_coef_3_ENG_2 = 1-(ENG2_N1/100)
  if ie_coef_3_ENG_2 <= 0.1 then ie_coef_3_ENG_2 = 0.1 end
  if ie_coef_3_ENG_2 >= 1 then ie_coef_3_ENG_2 = 1 end
  --get N1 ENG3 
  	ie_coef_3_ENG_3 = 1-(ENG3_N1/100)
  if ie_coef_3_ENG_3 <= 0.1 then ie_coef_3_ENG_3 = 0.1 end
  if ie_coef_3_ENG_3 >= 1 then ie_coef_3_ENG_3 = 1 end
  --get N1 ENG4 
  	ie_coef_3_ENG_4 = 1-(ENG4_N1/100)
  if ie_coef_3_ENG_4 <= 0.1 then ie_coef_3_ENG_4 = 0.1 end
  if ie_coef_3_ENG_4 >= 1 then ie_coef_3_ENG_4 = 1 end
  --debug datarefs
  --TEST1 = ie_coef_1 --debug
  --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
  --TEST2 = ie_coef_2 --debug
  --setDataf(findDataref("Colimata/CON_TESTVALUE_2_f"),TEST2)
  --TEST3 = ie_coef_3_ENG_1 --debug
  --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
  --intake ramp positions
  --get ramps ENG1 
  	ie_coef_4_ENG_1 = RAMP_ENG1/100
    if ie_coef_4_ENG_1 <= 0.01 then ie_coef_4_ENG_1 = 0.01 end
    if ie_coef_4_ENG_1 >= 0.5 then ie_coef_4_ENG_1 = 0.5 end
	--get ramps ENG2 
  	ie_coef_4_ENG_2 = RAMP_ENG2/100
    if ie_coef_4_ENG_2 <= 0.01 then ie_coef_4_ENG_2 = 0.01 end
    if ie_coef_4_ENG_2 >= 0.5 then ie_coef_4_ENG_2 = 0.5 end
	--get ramps ENG3 
  	ie_coef_4_ENG_3 = RAMP_ENG3/100
    if ie_coef_4_ENG_3 <= 0.01 then ie_coef_4_ENG_3 = 0.01 end
    if ie_coef_4_ENG_3 >= 0.5 then ie_coef_4_ENG_3 = 0.5 end
	--get ramps ENG4 
  	ie_coef_4_ENG_4 = RAMP_ENG4/100
    if ie_coef_4_ENG_4 <= 0.01 then ie_coef_4_ENG_4 = 0.01 end
    if ie_coef_4_ENG_4 >= 0.5 then ie_coef_4_ENG_4 = 0.5 end
  --main intake error formula
  if WEHAVEPOWER ~= 0 then 
   if MACH_SPEED_VALUE >= 1.3 then
    dial_intake_error1 = ie_coef_4_ENG_1+(ie_coef_1 + ie_coef_2 + ie_coef_3_ENG_1)/3
    setDataf(findDataref("Gastonreif/Heritage/dial_intake_error1"),dial_intake_error1)
    dial_intake_error2 = ie_coef_4_ENG_2+(ie_coef_1 + ie_coef_2 + ie_coef_3_ENG_2)/3
    setDataf(findDataref("Gastonreif/Heritage/dial_intake_error2"),dial_intake_error2)
    dial_intake_error3 = ie_coef_4_ENG_3+(ie_coef_1 + ie_coef_2 + ie_coef_3_ENG_3)/3
    setDataf(findDataref("Gastonreif/Heritage/dial_intake_error3"),dial_intake_error3)
    dial_intake_error4 = ie_coef_4_ENG_4+(ie_coef_1 + ie_coef_2 + ie_coef_3_ENG_4)/3
    setDataf(findDataref("Gastonreif/Heritage/dial_intake_error4"),dial_intake_error4)
   else -- under M1.3 
   	dial_intake_error1 = dial_intake_error1+0.01
   	if dial_intake_error1 >= 0.5 then dial_intake_error1 = 0.5 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error1"),dial_intake_error1)
   	dial_intake_error2 = dial_intake_error2+0.01
   	if dial_intake_error2 >= 0.5 then dial_intake_error2 = 0.5 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error2"),dial_intake_error2)
   	dial_intake_error3 = dial_intake_error3+0.01
   	if dial_intake_error3 >= 0.5 then dial_intake_error3 = 0.5 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error3"),dial_intake_error3)
   	dial_intake_error4 = dial_intake_error4+0.01
   	if dial_intake_error4 >= 0.5 then dial_intake_error4 = 0.5 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error4"),dial_intake_error4)
   end
  else -- no power 
  	dial_intake_error1 = dial_intake_error1-0.01
   	if dial_intake_error1 <= 0.01 then dial_intake_error1 = 0.01 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error1"),dial_intake_error1)
   	dial_intake_error2 = dial_intake_error2-0.01
   	if dial_intake_error2 <= 0.01 then dial_intake_error2 = 0.01 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error2"),dial_intake_error2)
   	dial_intake_error3 = dial_intake_error3-0.01
   	if dial_intake_error3 <= 0.01 then dial_intake_error3 = 0.01 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error3"),dial_intake_error3)
   	dial_intake_error4 = dial_intake_error4-0.01
   	if dial_intake_error4 <= 0.01 then dial_intake_error4 = 0.01 end
   	setDataf(findDataref("Gastonreif/Heritage/dial_intake_error4"),dial_intake_error4)
  end
  --cabin pressure
  ----simple design first
  --if WEHAVEPOWER ~= 0 then -- we need power source
  -- if dial_cabin_press < PRESS_CABIN_ALT/1000 then   --match slowly the cabin altitude, then normal 
  --  dial_cabin_press = dial_cabin_press + 0.01
  --	setDataf(findDataref("Gastonreif/Heritage/dial_cabin_press"),dial_cabin_press)
  -- else  
  --  dial_cabin_press = PRESS_CABIN_ALT/1000
  --  setDataf(findDataref("Gastonreif/Heritage/dial_cabin_press"),dial_cabin_press) -- 0-33
  -- end
  -- dial_cabin_diff = PRESS_CABIN_DIFF
  -- setDataf(findDataref("Gastonreif/Heritage/dial_cabin_diff"),dial_cabin_diff) -- 0-13
  -- dial_cabin_rate = PRESS_CABIN_RATE/1000
  -- setDataf(findDataref("Gastonreif/Heritage/dial_cabin_rate"),dial_cabin_rate) -- -6..0--6
  -- --system selectors
  -- if PRESS_SYS_SEL_L == 0 and PRESS_SYS_SEL_R == 0 then --SYS1 active
  --   --if PRESS_SYS_RESET == 0 then
  --	  dial_cabin_sys1 = PRESS_RATE_SEL/10
  --	  --if dial_cabin_sys1 >= 10 then dial_cabin_sys1 = 10 end -- limiter
  --	  setDataf(findDataref("Gastonreif/Heritage/dial_cabin_sys1"),dial_cabin_sys1) --0-10
  --	--this allows both dials to be set, no to zero drops 
  -- end
  -- if PRESS_SYS_SEL_L == 1 and PRESS_SYS_SEL_R == 1 then --SYS2 active
  --    dial_cabin_sys2 = PRESS_RATE_SEL/10
  --	  --if dial_cabin_sys2 >= 10 then dial_cabin_sys2 = 10 end
  --	  setDataf(findDataref("Gastonreif/Heritage/dial_cabin_sys2"),dial_cabin_sys2)
  -- --this allows both dials to be set, no to zero drops 
  -- end
  -- --note wrong configuration does nothing 
  -- --end system selectors
  -- else --drop to 0
  -- dial_cabin_press = dial_cabin_press-0.01
  -- if dial_cabin_press <= 0.01 then dial_cabin_press = 0.01 end
  -- setDataf(findDataref("Gastonreif/Heritage/dial_cabin_press"),dial_cabin_press) -- 0-33
  -- dial_cabin_diff = dial_cabin_press-0.01
  -- if dial_cabin_diff <= 0.01 then dial_cabin_diff = 0.01 end
  -- setDataf(findDataref("Gastonreif/Heritage/dial_cabin_diff"),dial_cabin_diff) -- 0-13
  -- dial_cabin_rate = dial_cabin_rate-0.01
  -- if dial_cabin_rate <= 0.01 then dial_cabin_rate = 0.01 end
  -- setDataf(findDataref("Gastonreif/Heritage/dial_cabin_rate"),dial_cabin_rate) -- -6..0--6
  --end
  --end automatic simple preesurization system 
  --manual presurization system here
  if WEHAVEPOWER ~= 0 then -- we need power source
   -- prerequisites
   --quick offset logic effect 
   if PRESS_SYS_SEL_L == 0 and PRESS_SYS_SEL_R == 0 then --SYS1 active
    if quickpress_indicator_offset_active == 1 then 
     --quickpress_indicator_offset = (PRESS_RATE_SEL1/100) 
	 quickpress_indicator_offset = 4 -- fixed value, prevents indicator moves overlimits
	 quickpress_indicator_offset_active = 0
    else -- smoothly go steady
     if PRESS_RATE_SEL1 > 0 then 
      quickpress_indicator_offset =  quickpress_indicator_offset - 0.5
      if quickpress_indicator_offset <= 0 then quickpress_indicator_offset = 0 end
	 else
	  quickpress_indicator_offset =  quickpress_indicator_offset + 0.5
      if quickpress_indicator_offset >= 0 then quickpress_indicator_offset = 0 end
	 end
    end
   end -- end SYS1
   if PRESS_SYS_SEL_L == 1 and PRESS_SYS_SEL_R == 1 then --SYS2 active
    if quickpress_indicator_offset_active == 1 then 
     --quickpress_indicator_offset = (PRESS_RATE_SEL2/100) 
	 quickpress_indicator_offset = 4
	 quickpress_indicator_offset_active = 0
    else -- smoothly go steady
     if PRESS_RATE_SEL1 > 0 then 
      quickpress_indicator_offset =  quickpress_indicator_offset - 0.5
      if quickpress_indicator_offset <= 0 then quickpress_indicator_offset = 0 end
	 else
	  quickpress_indicator_offset =  quickpress_indicator_offset + 0.5
      if quickpress_indicator_offset >= 0 then quickpress_indicator_offset = 0 end
	 end
    end
   end -- end SYS2   
   
   --LEFT_POWER_MAX = ENG1_POWERMAX + ENG2_POWERMAX
   --RIGHT_POWER_MAX = ENG3_POWERMAX + ENG4_POWERMAX
   --MAX_POWER_SET = LEFT_POWER_MAX + RIGHT_POWER_MAX
   -- discharge valve position 
   if touch_down == 1 then
     if PRESS_SYS_SEL_L == 0 and PRESS_SYS_SEL_R == 0 then --SYS1 active
      if EMERG_DITCH1_ON == 1 then -- emergency water protection 
       sys1_fwd_indicator_value = sys1_fwd_indicator_value + 1 -- close 
       sys1_aft_indicator_value = sys1_aft_indicator_value + 1
       -- limits
       if sys1_fwd_indicator_value >= 100 then sys1_fwd_indicator_value = 100 end
       if sys1_aft_indicator_value >= 100 then sys1_aft_indicator_value = 100 end
      else -- normal ops 
       -- one exemption
       --if MAX_POWER_SET == 0 then -- away from full throttle 
       --	sys2_fwd_indicator_value = sys2_fwd_indicator_value + 1 -- close 
       -- sys2_aft_indicator_value = sys2_aft_indicator_value + 1
       -- -- limits
       -- if sys2_fwd_indicator_value >= 100 then sys2_fwd_indicator_value = 100 end
       -- if sys2_aft_indicator_value >= 100 then sys2_aft_indicator_value = 100 end
       --else 
       -- main here
        -- depress 
        if PRESS_CABIN_RATE < 0 then
         sys1_fwd_indicator_value = sys1_fwd_indicator_value - 1 
         sys1_aft_indicator_value = sys1_aft_indicator_value - 1  -- open 
         -- limits
         if sys1_fwd_indicator_value <= 0 then sys1_fwd_indicator_value = 0 end
         if sys1_aft_indicator_value <= 50 then sys1_aft_indicator_value = 50 end
        else
        -- compress 
         sys1_fwd_indicator_value = sys1_fwd_indicator_value + 1 
         sys1_aft_indicator_value = sys1_aft_indicator_value + 1  -- regulate 
         -- limits
         if sys1_fwd_indicator_value >= 60 then sys1_fwd_indicator_value = 60 end
         if sys1_aft_indicator_value >= 90 then sys1_aft_indicator_value = 90 end
        end
      -- end -- end normal ops with exemption
      end -- end normal ops with ditching condition 
     end
     --
     if PRESS_SYS_SEL_L == 1 and PRESS_SYS_SEL_R == 1 then --SYS2 active
      if EMERG_DITCH2_ON == 1 then -- emergency water protection 
       sys2_fwd_indicator_value = sys2_fwd_indicator_value + 1
       sys2_aft_indicator_value = sys2_aft_indicator_value + 1  -- close
       -- limits
       if sys2_fwd_indicator_value >= 100 then sys2_fwd_indicator_value = 100 end
       if sys2_aft_indicator_value >= 100 then sys2_aft_indicator_value = 100 end
      else --  normal ops 
       --if MAX_POWER_SET == 0 then -- away from full throttle 
       --	sys1_fwd_indicator_value = sys1_fwd_indicator_value + 1 -- close 
       -- sys1_aft_indicator_value = sys1_aft_indicator_value + 1
        -- limits
       --if sys1_fwd_indicator_value >= 100 then sys1_fwd_indicator_value = 100 end
        --if sys1_aft_indicator_value >= 100 then sys1_aft_indicator_value = 100 end
       --else 
       -- main here
        -- depress 
        if PRESS_CABIN_RATE < 0 then
         sys2_fwd_indicator_value = sys2_fwd_indicator_value - 1 
         sys2_aft_indicator_value = sys2_aft_indicator_value - 1  -- open 
         -- limits
         if sys2_fwd_indicator_value <= 0 then sys2_fwd_indicator_value = 0 end
         if sys2_aft_indicator_value <= 50 then sys2_aft_indicator_value = 50 end
        else
        -- compress 
         sys2_fwd_indicator_value = sys2_fwd_indicator_value + 1 
         sys2_aft_indicator_value = sys2_aft_indicator_value + 1 -- regulate
         -- limits
         if sys2_fwd_indicator_value >= 60 then sys2_fwd_indicator_value = 60 end
         if sys2_aft_indicator_value >= 90 then sys2_aft_indicator_value = 90 end
        end
      -- end -- end normal ops with exemption
      end -- end normal ops with ditching condition
     end
   else -- airborne
    if EMERG_DEPRESS_ON == 0 then -- normal ops 
     -- main here 
     if PRESS_SYS_SEL_L == 0 and PRESS_SYS_SEL_R == 0 then --SYS1 active
      if EMERG_DITCH1_ON == 1 then -- emergency water protection, but unlikely airborne, false switch 
       sys1_fwd_indicator_value = sys1_fwd_indicator_value + 1  
       sys1_aft_indicator_value = sys1_aft_indicator_value + 1  -- close 
       -- limits
       if sys1_fwd_indicator_value >= 100 then sys1_fwd_indicator_value = 100 end
       if sys1_aft_indicator_value >= 100 then sys1_aft_indicator_value = 100 end
      else -- normal ops 
       -- one exemption
       --if MAX_POWER_SET == 0 then -- away from full throttle 
       --	sys2_fwd_indicator_value = sys2_fwd_indicator_value + 1 -- close 
       -- sys2_aft_indicator_value = sys2_aft_indicator_value + 1
        -- limits
       -- if sys2_fwd_indicator_value >= 100 then sys2_fwd_indicator_value = 100 end
       -- if sys2_aft_indicator_value >= 100 then sys2_aft_indicator_value = 100 end
       --else 
       -- main here
        -- depress 
        if PRESS_CABIN_RATE < 0 then
         sys1_fwd_indicator_value = sys1_fwd_indicator_value - 1 -- open 
         sys1_aft_indicator_value = sys1_aft_indicator_value - 1 
         -- limits
         if sys1_fwd_indicator_value <= 0 then sys1_fwd_indicator_value = 0 end
         if sys1_aft_indicator_value <= 50 then sys1_aft_indicator_value = 50 end
        else
        -- compress 
         sys1_fwd_indicator_value = sys1_fwd_indicator_value + 1  -- regulate 
         sys1_aft_indicator_value = sys1_aft_indicator_value + 1
         -- limits
         if sys1_fwd_indicator_value >= 60 then sys1_fwd_indicator_value = 60 end
         if sys1_aft_indicator_value >= 90 then sys1_aft_indicator_value = 90 end
        end
       --end -- end normal ops with exemption
      end -- end normal ops with ditching condition 
     end
     --
     if PRESS_SYS_SEL_L == 1 and PRESS_SYS_SEL_R == 1 then --SYS2 active
      if EMERG_DITCH2_ON == 1 then -- emergency water protection 
       sys2_fwd_indicator_value = sys2_fwd_indicator_value + 1  -- close 
       sys2_aft_indicator_value = sys2_aft_indicator_value + 1 
       -- limits
       if sys2_fwd_indicator_value >= 100 then sys2_fwd_indicator_value = 100 end
       if sys2_aft_indicator_value >= 100 then sys2_aft_indicator_value = 100 end
      else --  normal ops 
      -- if MAX_POWER_SET == 0 then -- away from full throttle 
       --	sys1_fwd_indicator_value = sys1_fwd_indicator_value + 1 -- close 
       -- sys1_aft_indicator_value = sys1_aft_indicator_value + 1
       -- -- limits
       -- if sys1_fwd_indicator_value >= 100 then sys1_fwd_indicator_value = 100 end
       -- if sys1_aft_indicator_value >= 100 then sys1_aft_indicator_value = 100 end
       --else 
       -- main here
        -- depress 
        if PRESS_CABIN_RATE < 0 then
         sys2_fwd_indicator_value = sys2_fwd_indicator_value - 1  -- open 
         sys2_aft_indicator_value = sys2_aft_indicator_value - 1 
         -- limits
         if sys2_fwd_indicator_value <= 0 then sys2_fwd_indicator_value = 0 end
         if sys2_aft_indicator_value <= 50 then sys2_aft_indicator_value = 50 end
        else
        -- compress 
         sys2_fwd_indicator_value = sys2_fwd_indicator_value + 1 -- regulate 
         sys2_aft_indicator_value = sys2_aft_indicator_value + 1 
         -- limits
         if sys2_fwd_indicator_value >= 60 then sys2_fwd_indicator_value = 60 end
         if sys2_aft_indicator_value >= 90 then sys2_aft_indicator_value = 90 end
        end
      -- end -- end normal ops with exemption
      end -- end normal ops with ditching condition
     end
    else -- depress active 
     if PRESS_SYS_SEL_L == 0 and PRESS_SYS_SEL_R == 0 then --SYS1 active
      sys1_fwd_indicator_value = sys1_fwd_indicator_value - 1 -- open 
      sys1_aft_indicator_value = sys1_aft_indicator_value - 1
      sys2_fwd_indicator_value = sys2_fwd_indicator_value + 1 -- close 
      sys2_aft_indicator_value = sys2_aft_indicator_value + 1
      -- limits
      if sys1_fwd_indicator_value <= 0 then sys1_fwd_indicator_value = 0 end
      if sys1_aft_indicator_value <= 0 then sys1_aft_indicator_value = 0 end
      if sys2_fwd_indicator_value >= 100 then sys2_fwd_indicator_value = 100 end
      if sys2_aft_indicator_value >= 100 then sys2_aft_indicator_value = 100 end
     end
     if PRESS_SYS_SEL_L == 1 and PRESS_SYS_SEL_R == 1 then --SYS2 active
      sys1_fwd_indicator_value = sys1_fwd_indicator_value + 1 -- close 
      sys1_aft_indicator_value = sys1_aft_indicator_value + 1
      sys2_fwd_indicator_value = sys2_fwd_indicator_value - 1 -- open 
      sys2_aft_indicator_value = sys2_aft_indicator_value - 1
      -- limits
      if sys1_fwd_indicator_value >= 100 then sys1_fwd_indicator_value = 100 end
      if sys1_aft_indicator_value >= 100 then sys1_aft_indicator_value = 100 end
      if sys2_fwd_indicator_value <= 0 then sys2_fwd_indicator_value = 0 end
      if sys2_aft_indicator_value <= 0 then sys2_aft_indicator_value = 0 end
     end
    end
