   	 if dial_fueltank_press >= 0 then 
      dial_fueltank_press=dial_fueltank_press-0.001 --slowly down to 0
      if dial_fueltank_press <= 0.01 then dial_fueltank_press = 0.01 end
   	  setDataf(findDataref("Gastonreif/Heritage/dial_fueltank_press"),dial_fueltank_press) 
     else
