   	 end
   	 if dial_fueltank_press < 0 then 
      dial_fueltank_press=dial_fueltank_press+press_diff_speed --slowly increase
      --if dial_fueltank_press <= 0.01 then dial_fueltank_press = 0.01 end --low limit 
   	  if dial_fueltank_press >= 1.2 then dial_fueltank_press = 1.2 end --high limit 
   	  setDataf(findDataref("Gastonreif/Heritage/dial_fueltank_press"),dial_fueltank_press) 
