	setDataf(findDataref("Gastonreif/Heritage/dial_oil_press_eng2"),dial_oil_press_eng2)
	dial_oil_press_eng3 = dial_oil_press_eng3+0.1
	if dial_oil_press_eng3 >= ENG3_OIL_PRESS_ADJUSTED then dial_oil_press_eng3 = ENG3_OIL_PRESS_ADJUSTED end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_press_eng3"),dial_oil_press_eng3)
	dial_oil_press_eng4 = dial_oil_press_eng4+0.1
	if dial_oil_press_eng4 >= ENG4_OIL_PRESS_ADJUSTED then dial_oil_press_eng4 = ENG4_OIL_PRESS_ADJUSTED end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_press_eng4"),dial_oil_press_eng4)
   else -- no power
    dial_oil_press_eng1 = dial_oil_press_eng1-0.1
	if dial_oil_press_eng1 <= 0 then dial_oil_press_eng1 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_press_eng1"),dial_oil_press_eng1)
	dial_oil_press_eng2 = dial_oil_press_eng2-0.1
	if dial_oil_press_eng2 <= 0 then dial_oil_press_eng2 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_press_eng2"),dial_oil_press_eng2)
	dial_oil_press_eng3 = dial_oil_press_eng3-0.1
	if dial_oil_press_eng3 <= 0 then dial_oil_press_eng3 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_press_eng3"),dial_oil_press_eng3)
	dial_oil_press_eng1 = dial_oil_press_eng1-0.1
	if dial_oil_press_eng4 <= 0 then dial_oil_press_eng4 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_press_eng4"),dial_oil_press_eng4)  
   end --end engine oil pressure 
   --Engine oil temperature 
   if battery_on == 1 then
    -- conversion from F to deg C
	ENG1_OIL_TEMP_C=(ENG1_OIL_TEMP-32)*(5/9)
	ENG2_OIL_TEMP_C=(ENG2_OIL_TEMP-32)*(5/9)
	ENG3_OIL_TEMP_C=(ENG3_OIL_TEMP-32)*(5/9)
	ENG4_OIL_TEMP_C=(ENG4_OIL_TEMP-32)*(5/9)
   	-- definition of engine oil temperature 
	eng1_oiltemp_adjusted = ENG1_OIL_TEMP_C*0.5
	if eng1_oiltemp_adjusted <= 1 then eng1_oiltemp_adjusted = 1 end --low limit
	if eng1_oiltemp_adjusted >= 250 then eng1_oiltemp_adjusted = 250 end -- high limit
	eng2_oiltemp_adjusted = ENG2_OIL_TEMP_C*0.5
	if eng2_oiltemp_adjusted <= 1 then eng2_oiltemp_adjusted = 1 end 
	if eng2_oiltemp_adjusted >= 250 then eng2_oiltemp_adjusted = 250 end 
	eng3_oiltemp_adjusted = ENG3_OIL_TEMP_C*0.5
	if eng3_oiltemp_adjusted <= 1 then eng3_oiltemp_adjusted = 1 end 
	if eng3_oiltemp_adjusted >= 250 then eng3_oiltemp_adjusted = 250 end 
	eng4_oiltemp_adjusted = ENG4_OIL_TEMP_C*0.5
	if eng4_oiltemp_adjusted <= 1 then eng4_oiltemp_adjusted = 1 end 
	if eng4_oiltemp_adjusted >= 250 then eng4_oiltemp_adjusted = 250 end 
   	--eng1_oiltemp=eng1_oiltemp_adjusted+(ENG1_HEATSELF*0.1)+TAT 
	eng1_oiltemp=eng1_oiltemp_adjusted+(tca1_heat*0.3)+Total 
   	eng2_oiltemp=eng2_oiltemp_adjusted+(tca2_heat*0.3)+Total
   	eng3_oiltemp=eng3_oiltemp_adjusted+(tca3_heat*0.3)+Total
   	eng4_oiltemp=eng4_oiltemp_adjusted+(tca4_heat*0.3)+Total
   	--recirculation fuel pumps effect 
   	if RECIRC1_ON == 1 then --recirc valve on 
   		--recir effect initial 1
	 if ENG1_N1 > 20 and ENG1_N1 < 70 then 
   	  recirc_effect1 = recirc_effect1 + 0.001 --cooling effect arise 
   	  if recirc_effect1 >= 1.33 then recirc_effect1 = 1.33 end
	 else -- engines off or high demand of fuel 
	  recirc_effect1 = recirc_effect1 - 0.001 -- get back to 1
      if recirc_effect1 <= 1.001 then recirc_effect1 = 1 end
	 end
   	else -- no recirculation 
     recirc_effect1 = recirc_effect1 - 0.001 -- get back to 1
     if recirc_effect1 <= 1.001 then recirc_effect1 = 1 end
   	end
   	if RECIRC2_ON == 1 then
	 if ENG2_N1 > 20 and ENG2_N1 < 70 then
   	  recirc_effect2 = recirc_effect2 + 0.001
   	  if recirc_effect2 >= 1.33 then recirc_effect2 = 1.33 end
	 else
	  recirc_effect2 = recirc_effect2 - 0.001
      if recirc_effect2 <= 1.001 then recirc_effect2 = 1 end
	 end
   	else 
     recirc_effect2 = recirc_effect2 - 0.001
     if recirc_effect2 <= 1.001 then recirc_effect2 = 1 end
   	end
   	if RECIRC3_ON == 1 and ENG3_N1 < 70 then
	 if ENG3_N1 > 20 and ENG3_N1 < 70 then
   	  recirc_effect3 = recirc_effect3 + 0.001
   	  if recirc_effect3 >= 1.33 then recirc_effect3 = 1.33 end
	 else
	  recirc_effect3 = recirc_effect3 - 0.001
      if recirc_effect3 <= 1.001 then recirc_effect3 = 1 end
	 end
   	else 
     recirc_effect3 = recirc_effect3 - 0.001
     if recirc_effect3 <= 1.001 then recirc_effect3 = 1 end
   	end
   	if RECIRC4_ON == 1 and ENG4_N1 < 70 then
	 if ENG4_N1 > 20 and ENG4_N1 < 70 then
   	  recirc_effect4 = recirc_effect4 + 0.001
   	  if recirc_effect4 >= 1.33 then recirc_effect4 = 1.33 end
	 else
	  recirc_effect4 = recirc_effect4 - 0.001
      if recirc_effect4 <= 1.001 then recirc_effect4 = 1 end
	 end 
   	else 
     recirc_effect4 = recirc_effect4 - 0.001
     if recirc_effect4 <= 1.001 then recirc_effect4 = 1 end
   	end
   	-- cooled with fuel 
   	eng1_oil_supercooler=(eng1_oiltemp+fueltemp1_agregated)/(recirc_effect1+(ENG1_N1/100))
   	eng2_oil_supercooler=(eng2_oiltemp+fueltemp2_agregated)/(recirc_effect2+(ENG2_N1/100))
   	eng3_oil_supercooler=(eng3_oiltemp+fueltemp3_agregated)/(recirc_effect3+(ENG3_N1/100))
   	eng4_oil_supercooler=(eng4_oiltemp+fueltemp4_agregated)/(recirc_effect4+(ENG4_N1/100))
   if ENG1_FUEL_FLOW > 1000 then
    dial_oil_temp_eng1 = dial_oil_temp_eng1+0.1
	if dial_oil_temp_eng1 >= eng1_oil_supercooler then dial_oil_temp_eng1 = eng1_oil_supercooler end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng1"),dial_oil_temp_eng1)
   else -- no fuel flow
    dial_oil_temp_eng1 = dial_oil_temp_eng1-0.01
	if dial_oil_temp_eng1 <= eng1_oiltemp_adjusted then dial_oil_temp_eng1 = eng1_oiltemp_adjusted end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng1"),dial_oil_temp_eng1)
   end
   if ENG2_FUEL_FLOW > 1000 then
	dial_oil_temp_eng2 = dial_oil_temp_eng2+0.1
	if dial_oil_temp_eng2 >= eng2_oil_supercooler then dial_oil_temp_eng2 = eng2_oil_supercooler end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng2"),dial_oil_temp_eng2)
   else
    dial_oil_temp_eng2 = dial_oil_temp_eng2-0.01
	if dial_oil_temp_eng2 <= eng2_oiltemp_adjusted then dial_oil_temp_eng2 = eng2_oiltemp_adjusted end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng2"),dial_oil_temp_eng2)
   end
   if ENG3_FUEL_FLOW > 1000 then
	dial_oil_temp_eng3 = dial_oil_temp_eng3+0.1
	if dial_oil_temp_eng3 >= eng3_oil_supercooler then dial_oil_temp_eng3 = eng3_oil_supercooler end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng3"),dial_oil_temp_eng3)
   else
    dial_oil_temp_eng3 = dial_oil_temp_eng3-0.01
	if dial_oil_temp_eng3 <= eng3_oiltemp_adjusted then dial_oil_temp_eng3 = eng3_oiltemp_adjusted end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng3"),dial_oil_temp_eng3)
   end
   if ENG4_FUEL_FLOW > 1000 then
	dial_oil_temp_eng4 = dial_oil_temp_eng4+0.1
	if dial_oil_temp_eng4 >= eng4_oil_supercooler then dial_oil_temp_eng4 = eng4_oil_supercooler end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng4"),dial_oil_temp_eng4)
   else
    dial_oil_temp_eng4 = dial_oil_temp_eng4-0.01
	if dial_oil_temp_eng4 <= eng4_oiltemp_adjusted then dial_oil_temp_eng4 = eng4_oiltemp_adjusted end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng4"),dial_oil_temp_eng4)
   end 
   -- no power at all
   else 
    dial_oil_temp_eng1 = dial_oil_temp_eng1-0.1
	if dial_oil_temp_eng1 <= -50 then dial_oil_temp_eng1 = -50 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng1"),dial_oil_temp_eng1)
	dial_oil_temp_eng2 = dial_oil_temp_eng2-0.1
	if dial_oil_temp_eng2 <= -50 then dial_oil_temp_eng2 = -50 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng2"),dial_oil_temp_eng2)
	dial_oil_temp_eng3 = dial_oil_temp_eng3-0.1
	if dial_oil_temp_eng3 <= -50 then dial_oil_temp_eng3 = -50 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng3"),dial_oil_temp_eng3)
	dial_oil_temp_eng4 = dial_oil_temp_eng4-0.1
	if dial_oil_temp_eng4 <= -50 then dial_oil_temp_eng4 = -50 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_temp_eng4"),dial_oil_temp_eng4)
   end 
   -- Engine oil contents 
   if battery_on == 1 then
    dial_oil_contents_eng1 = dial_oil_contents_eng1+0.1
	if dial_oil_contents_eng1 >= 11 then dial_oil_contents_eng1 = 11 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng1"),dial_oil_contents_eng1)
	dial_oil_contents_eng2 = dial_oil_contents_eng2+0.1
	if dial_oil_contents_eng2 >= 11 then dial_oil_contents_eng2 = 11 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng2"),dial_oil_contents_eng2)
	dial_oil_contents_eng3 = dial_oil_contents_eng3+0.1
	if dial_oil_contents_eng3 >= 11 then dial_oil_contents_eng3 = 11 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng3"),dial_oil_contents_eng3)
	dial_oil_contents_eng4 = dial_oil_contents_eng4+0.1
	if dial_oil_contents_eng4 >= 11 then dial_oil_contents_eng4 = 11 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng4"),dial_oil_contents_eng4)
   else -- no power 
    dial_oil_contents_eng1 = dial_oil_contents_eng1-0.1
	if dial_oil_contents_eng1 <= 0 then dial_oil_contents_eng1 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng1"),dial_oil_contents_eng1)
	dial_oil_contents_eng2 = dial_oil_contents_eng2-0.1
	if dial_oil_contents_eng2 <= 0 then dial_oil_contents_eng2 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng2"),dial_oil_contents_eng2)
	dial_oil_contents_eng3 = dial_oil_contents_eng3-0.1
	if dial_oil_contents_eng3 <= 0 then dial_oil_contents_eng3 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng3"),dial_oil_contents_eng3)
	dial_oil_contents_eng4 = dial_oil_contents_eng4-0.1
	if dial_oil_contents_eng4 <= 0 then dial_oil_contents_eng4 = 0 end
	setDataf(findDataref("Gastonreif/Heritage/dial_oil_contents_eng4"),dial_oil_contents_eng4)
   end 
   -- P7 instrument
    --pressure adjustments
	if ENG1_N1 >= 70 then -- under power 
	 psi_boost1 = psi_boost1 - 0.2 -- 33 at idle, 16.5 at reheats full power and full power too
	 if psi_boost1 <= 16.5 then psi_boost1 = 16.5 end
	else -- idle 
	 if GROUND_IDLE14 == 1 then -- idle power savings
	  psi_boost1 = psi_boost1 + 0.2 
	  if psi_boost1 >= 33 then psi_boost1 = 33 end
	 else -- high fuel flow and pressure 
	  psi_boost1 = psi_boost1 - 0.2
	  if psi_boost1 <= 16.5 then psi_boost1 = 16.5 end  
	 end 
	end
	if ENG2_N1 >= 70 then 
	 psi_boost2 = psi_boost2 - 0.2
	 if psi_boost2 <= 16.5 then psi_boost2 = 16.5 end
	else -- idle 
	 if GROUND_IDLE23 == 1 then 
	  psi_boost2 = psi_boost2 + 0.2
	  if psi_boost2 >= 33 then psi_boost2 = 33 end
	 else 
	  psi_boost2 = psi_boost2 - 0.2
	  if psi_boost2 <= 16.5 then psi_boost2 = 16.5 end  
	 end 
	end
	if ENG3_N1 >= 70 then 
	 psi_boost3 = psi_boost3 - 0.2
	 if psi_boost3 <= 16.5 then psi_boost3 = 16.5 end
	else 
	 if GROUND_IDLE23 == 1 then 
	  psi_boost3 = psi_boost3 + 0.2
	  if psi_boost3 >= 33 then psi_boost3 = 33 end
	 else 
	  psi_boost3 = psi_boost3 - 0.2
	  if psi_boost3 <= 16.5 then psi_boost3 = 16.5 end  
	 end 
	end
    if ENG4_N1 >= 70 then 
	 psi_boost4 = psi_boost4 - 0.2 
	 if psi_boost4 <= 16.5 then psi_boost4 = 16.5 end
	else 
	 if GROUND_IDLE14 == 1 then 
	  psi_boost4 = psi_boost4 + 0.2 
	  if psi_boost4 >= 33 then psi_boost4 = 33 end
	 else 
	  psi_boost4 = psi_boost4 - 0.2
	  if psi_boost4 <= 16.5 then psi_boost4 = 16.5 end  
	 end 
	end
	
   if battery_on == 1 then -- should read 7 idle, 40 takeoff, 30 climb, 26 mach 1.5 and 22 at mach 2
    --dial_P7_eng1 = ENG1_P7*(ENG1_N2/100)*(1-(altitude/100000))
	dial_P7_eng1 = (ENG1_EGT/psi_boost1)*(1-(altitude/300000))
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng1"),dial_P7_eng1)
	--dial_P7_eng2 = 2*(ENG2_FUEL_FLOW/1000)*(1-(altitude/100000)) -- 1100/100 reading at idle, 100% is 11000/100 and afterburner 22000/100
	dial_P7_eng2 = (ENG2_EGT/psi_boost2)*(1-(altitude/300000))
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng2"),dial_P7_eng2)
	--dial_P7_eng3 = 2.5*(ENG3_FUEL_FLOW/1000)*(1-(altitude/100000))
	dial_P7_eng3 = (ENG3_EGT/psi_boost3)*(1-(altitude/300000))
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng3"),dial_P7_eng3)
	dial_P7_eng4 = (ENG4_EGT/psi_boost4)*(1-(altitude/300000))
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng4"),dial_P7_eng4)
   else -- no power 
    dial_P7_eng1 = ENG1_P7
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng1"),dial_P7_eng1)
	dial_P7_eng2 = ENG2_P7
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng2"),dial_P7_eng2)
	dial_P7_eng3 = ENG3_P7
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng3"),dial_P7_eng3)
	dial_P7_eng4 = ENG4_P7
	setDataf(findDataref("Gastonreif/Heritage/dial_P7_eng4"),dial_P7_eng4)
   end 
    -- Airbleed 
    -- 0-80 psi with 65 reducing valve, more air needed then less air pressure from engine 
    -- no engines running 
    if ENG1_N2 == 0 and ENG2_N2 == 0 then 
      airbleed_from_eng2 = airbleed_from_eng2 - 1
      if airbleed_from_eng2 <= 0 then airbleed_from_eng2 = 0 end
      airbleed_from_eng1 = airbleed_from_eng1 - 1
      if airbleed_from_eng1 <= 0 then airbleed_from_eng1 = 0 end
      -- air sources
      if GPU_UNIT_ON == 1 then 
	   if ENG1_CROSSBLEED == 1 then -- ground air avail 
        airbleed_from_ground1 = airbleed_from_ground1 + 1
        if airbleed_from_ground1 >= 35 then airbleed_from_ground1 = 35 end
	   else
	    airbleed_from_ground1 = airbleed_from_ground1 - 1
        if airbleed_from_ground1 <= 0 then airbleed_from_ground1 = 0 end
	   end
	   if ENG2_CROSSBLEED == 1 then -- ground air avail 
	    airbleed_from_ground2 = airbleed_from_ground2 + 1
        if airbleed_from_ground2 >= 35 then airbleed_from_ground2 = 35 end
	   else
	    airbleed_from_ground2 = airbleed_from_ground2 - 1
        if airbleed_from_ground2 <= 0 then airbleed_from_ground2 = 0 end
	   end
      end 
      if GPU_UNIT_ON == 0 then -- no bleed air from other source 
       airbleed_from_ground1 = airbleed_from_ground1 - 1
       if airbleed_from_ground1 <= 0 then airbleed_from_ground1 = 0 end
	   airbleed_from_ground2 = airbleed_from_ground2 - 1
       if airbleed_from_ground2 <= 0 then airbleed_from_ground2 = 0 end
      end -- end gpu off
     bleed_pressure_group1 = airbleed_from_ground1+airbleed_from_eng1 -- main pressure 
     bleed_pressure_group2 = airbleed_from_ground2+airbleed_from_eng2 -- main pressure 
    end
    -- Group 1 from ENG1 
    if ENG1_N2 ~= 0 and ENG2_N2 == 0 then -- eng1 is running only 
	 --airbleed_from_eng2 = airbleed_from_eng2 - 1
     --if airbleed_from_eng2 <= 0 then airbleed_from_eng2 = 0 end 
     if ENG1_BLEED_AIR == 0 then -- bleed valve is open 
      airbleed_from_eng1 = airbleed_from_eng1 + 1
      if airbleed_from_eng1 >= ENG1_N1 then airbleed_from_eng1 = ENG1_N1 end
	  -- ENG2 crossbleed effect 
	  if CROSSBLEED12 == 0 then
	   crossbleed2to1_gain=crossbleed2to1_gain-0.1
	   if crossbleed2to1_gain <= 0 then crossbleed2to1_gain = 0 end
	   crossbleed1to2_gain=crossbleed1to2_gain-0.1
	   if crossbleed1to2_gain <= 0 then crossbleed1to2_gain = 0 end
	  else -- crosbleed on gain needed
	   crossbleed2to1_gain=crossbleed2to1_gain-0.1
	   if crossbleed2to1_gain <= -10 then crossbleed2to1_gain = -10 end
	   crossbleed1to2_gain=crossbleed1to2_gain+0.1
	   if crossbleed1to2_gain >= 10 then crossbleed1to2_gain = 10 end
	  end
	  --if ENG2_BLEED_AIR == 1 then 
	 --  if airbleed_from_eng1 >= (airbleed_from_eng2)/2 then -- here bleed2 is actually supllied from eng1
	  -- airbleed_from_eng2 = airbleed_from_eng2 + 0.1 -- getting pressure from ENG1
	  -- airbleed_from_eng1 = airbleed_from_eng1 - 0.1 -- ENG1 is loosing pressure
      -- --if airbleed_from_eng2 >= 0 then airbleed_from_eng2 = 0 end 
	  -- else 
	 --  airbleed_from_eng2 = airbleed_from_eng2 - 0.1
	 --  airbleed_from_eng1 = airbleed_from_eng1 + 0.1
	 --  end
	 -- else
	 --  airbleed_from_eng2 = airbleed_from_eng2 - 1
     --  if airbleed_from_eng2 <= 0 then airbleed_from_eng2 = 0 end 
	 -- end --end crosbleed
     else -- valve shut 
      airbleed_from_eng1 = airbleed_from_eng1 - 1
      if airbleed_from_eng1 <= 0 then airbleed_from_eng1 = 0 end
	  airbleed_from_eng2 = airbleed_from_eng2 - 1
      if airbleed_from_eng2 <= 0 then airbleed_from_eng2 = 0 end
	  crossbleed2to1_gain=crossbleed2to1_gain-0.1
	  if crossbleed2to1_gain <= 0 then crossbleed2to1_gain = 0 end
	  crossbleed1to2_gain=crossbleed1to2_gain-0.1
	  if crossbleed1to2_gain <= 0 then crossbleed1to2_gain = 0 end
     end -- end bleed air open  
	  -- GPU effect
      if GPU_UNIT_ON == 1 and ENG1_CROSSBLEED == 1 then -- ground air avail 
       airbleed_from_ground1 = airbleed_from_ground1 + 1
       if airbleed_from_ground1 >= 35 then airbleed_from_ground1 = 35 end
      else -- no bleed air from other source 
       airbleed_from_ground1 = airbleed_from_ground1 - 1
       if airbleed_from_ground1 <= 0 then airbleed_from_ground1 = 0 end
      end -- end gpu on
	  if GPU_UNIT_ON == 1 and ENG2_CROSSBLEED == 1 then -- ground air avail 
       airbleed_from_ground2 = airbleed_from_ground2 + 1
       if airbleed_from_ground2 >= 35 then airbleed_from_ground2 = 35 end
      else -- no bleed air from other source 
       airbleed_from_ground2 = airbleed_from_ground2 - 1
       if airbleed_from_ground2 <= 0 then airbleed_from_ground2 = 0 end
      end -- end gpu on
     if airbleed_from_eng1 >= 65 then airbleed_from_eng1 = 65 end -- reducing valve 
     if airbleed_from_eng2 >= 65 then airbleed_from_eng2 = 65 end
	 --
     bleed_pressure_group1 = airbleed_from_eng1+airbleed_from_ground1+crossbleed2to1_gain -- main pressure 
     bleed_pressure_group2 = airbleed_from_eng2+airbleed_from_ground2+crossbleed1to2_gain -- main pressure 
    end
    -- Group 1 from ENG2 
    if ENG1_N2 == 0 and ENG2_N2 ~= 0 then -- eng1 is off and eng2 is running 
     if ENG2_BLEED_AIR == 0 then -- bleed valve is open 
      airbleed_from_eng2 = airbleed_from_eng2 + 1
      if airbleed_from_eng2 >= ENG2_N1 then airbleed_from_eng2 = ENG2_N1 end
	  -- ENG2 crossbleed effect 
	  if CROSSBLEED12 == 0 then
	   crossbleed1to2_gain=crossbleed1to2_gain-0.1
	   if crossbleed1to2_gain <= 0 then crossbleed1to2_gain = 0 end
	   crossbleed2to1_gain=crossbleed2to1_gain-0.1
	   if crossbleed2to1_gain <= 0 then crossbleed2to1_gain = 0 end
	  else -- crosbleed on gain needed
	   crossbleed1to2_gain=crossbleed1to2_gain-0.1
	   if crossbleed1to2_gain <= -10 then crossbleed1to2_gain = -10 end
	   crossbleed2to1_gain=crossbleed2to1_gain+0.1
	   if crossbleed2to1_gain >= 10 then crossbleed2to1_gain = 10 end
	  end
     else -- valve shut 
      airbleed_from_eng2 = airbleed_from_eng2 - 1
      if airbleed_from_eng2 <= 0 then airbleed_from_eng2 = 0 end
	  airbleed_from_eng1 = airbleed_from_eng1 - 1
      if airbleed_from_eng1 <= 0 then airbleed_from_eng1 = 0 end
