    if AIRBLEED_COND3 ~= 0 then AIRBLEED_COND3_ON = 1 else AIRBLEED_COND3_ON = 0 end
    if AIRBLEED_COND4 ~= 0 then AIRBLEED_COND4_ON = 1 else AIRBLEED_COND4_ON = 0 end
    GROUPS_AVAIL = AIRBLEED_COND1_ON + AIRBLEED_COND2_ON + AIRBLEED_COND3_ON + AIRBLEED_COND4_ON
    CABIN_PRESSURIZED = PRESS_CABIN_DIFF
    --Group 1
    if AIRBLEED_COND1 == 1 then -- on 
     GROUP1_PSI=20+CONDITION_BOOST+CABIN_PRESSURIZED*(1/GROUPS_AVAIL) -- 10 is consumer simulation, divide by zero never happens by this condition 
     if GROUP1_PSI <= 0 then GROUP1_PSI = 0 end
    end
    if AIRBLEED_COND1 == 2 then -- boost 
     GROUP1_PSI=20+CABIN_PRESSURIZED*(1/GROUPS_AVAIL) 
     if GROUP1_PSI <= 0 then GROUP1_PSI = 0 end
    end
    if AIRBLEED_COND1 == 0 then -- off 
     GROUP1_PSI=0 -- isolated
     if GROUP1_PSI <= 0 then GROUP1_PSI = 0 end
    end
    -- Group 2
    if AIRBLEED_COND2 == 1 then -- on 
     GROUP2_PSI=20+CONDITION_BOOST+CABIN_PRESSURIZED*(1/GROUPS_AVAIL)  -- 10 is no boost 
     if GROUP2_PSI <= 0 then GROUP2_PSI = 0 end
    end
    if AIRBLEED_COND2 == 2 then -- boost 
     GROUP2_PSI=20+CABIN_PRESSURIZED*(1/GROUPS_AVAIL) 
     if GROUP2_PSI <= 0 then GROUP2_PSI = 0 end
    end
    if AIRBLEED_COND2 == 0 then -- off 
     GROUP2_PSI=0
     if GROUP2_PSI <= 0 then GROUP2_PSI = 0 end
    end
	--Group 3
    if AIRBLEED_COND3 == 1 then -- on 
     GROUP3_PSI=20+CONDITION_BOOST+CABIN_PRESSURIZED*(1/GROUPS_AVAIL) 
     if GROUP3_PSI <= 0 then GROUP3_PSI = 0 end
    end
    if AIRBLEED_COND3 == 2 then -- boost 
     GROUP3_PSI=20+CABIN_PRESSURIZED*(1/GROUPS_AVAIL) 
     if GROUP3_PSI <= 0 then GROUP3_PSI = 0 end
    end
    if AIRBLEED_COND3 == 0 then -- off 
     GROUP3_PSI=0 -- isolated
     if GROUP3_PSI <= 0 then GROUP3_PSI = 0 end
    end
    -- Group 4
    if AIRBLEED_COND4 == 1 then -- on 
     GROUP4_PSI=20+CONDITION_BOOST+CABIN_PRESSURIZED*(1/GROUPS_AVAIL)
     if GROUP4_PSI <= 0 then GROUP4_PSI = 0 end
    end
    if AIRBLEED_COND4 == 2 then -- boost 
     GROUP4_PSI=20+CABIN_PRESSURIZED*(1/GROUPS_AVAIL) 
     if GROUP4_PSI <= 0 then GROUP4_PSI = 0 end
    end
    if AIRBLEED_COND4 == 0 then -- off 
     GROUP4_PSI=0
     if GROUP4_PSI <= 0 then GROUP4_PSI = 0 end
    end
	 --
	 GROUP1_PSI_CONSUMED = bleed_pressure_group1 - GROUP1_PSI
	 if GROUP1_PSI_CONSUMED <= 0 then GROUP1_PSI_CONSUMED = 0 end
	 GROUP2_PSI_CONSUMED = bleed_pressure_group2 - GROUP2_PSI
	 if GROUP2_PSI_CONSUMED <= 0 then GROUP2_PSI_CONSUMED = 0 end
	 GROUP3_PSI_CONSUMED = bleed_pressure_group3 - GROUP3_PSI
	 if GROUP3_PSI_CONSUMED <= 0 then GROUP3_PSI_CONSUMED = 0 end
	 GROUP4_PSI_CONSUMED = bleed_pressure_group4 - GROUP4_PSI
	 if GROUP4_PSI_CONSUMED <= 0 then GROUP4_PSI_CONSUMED = 0 end
	     --debug
	 --TEST1 = bleed_pressure_group1 --debug
     --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
     --TEST2 = GROUP1_PSI --debug
     --setDataf(findDataref("Colimata/CON_TESTVALUE_2_f"),TEST2)
     --TEST3 = GROUP1_PSI_CONSUMED --debug
     --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
	 --heritage_debug1=airbleed_from_eng1
	-- setDataf(findDataref("Gastonreif/Heritage/debug1"),heritage_debug1)
    -- heritage_debug2=crossbleed1to2_gain
	-- setDataf(findDataref("Gastonreif/Heritage/debug2"),heritage_debug2)
     --heritage_debug3=crossbleed2to1_gain
	-- setDataf(findDataref("Gastonreif/Heritage/debug3"),heritage_debug3)
    -- heritage_debug4=bleed_pressure_group1
	-- setDataf(findDataref("Gastonreif/Heritage/debug4"),heritage_debug4) 
    --dials 
    if battery_on == 1 then 
	 -- Group 1
     -- increasing 
     --if GROUP1_PSI >= dial_bleed1 then 
	 if GROUP1_PSI_CONSUMED >= dial_bleed1 then 
      dial_bleed1=dial_bleed1+1
      --if dial_bleed1 >= GROUP1_PSI then dial_bleed1 = GROUP1_PSI end
	  --if dial_bleed1 >= bleed_pressure_group1 then dial_bleed1 = bleed_pressure_group1 end
	  if dial_bleed1 >= GROUP1_PSI_CONSUMED then dial_bleed1 = GROUP1_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed1"),dial_bleed1)
     else 
     -- decreasing 
      dial_bleed1=dial_bleed1-1
      --if dial_bleed1 < GROUP1_PSI then dial_bleed1 = GROUP1_PSI end
	  if dial_bleed1 < GROUP1_PSI_CONSUMED then dial_bleed1 = GROUP1_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed1"),dial_bleed1)
     end
      --limits
	  if GROUP1_PSI_CONSUMED >= 85 then 
      --GROUP1_PSI_CONSUMED = 85 -- top limit 
	  -- here you can add 10 sec shortuc switchover for bleedair 1
      group1_overpressed = 1
      else
      group1_overpressed = 0	
      end
	 -- Group 2
    -- increasing 
     --if GROUP2_PSI >= dial_bleed2 then 
	 if GROUP2_PSI_CONSUMED >= dial_bleed2 then 
      dial_bleed2=dial_bleed2+1
      --if dial_bleed2 >= GROUP2_PSI then dial_bleed2 = GROUP2_PSI end
	  --if dial_bleed2 >= bleed_pressure_group2 then dial_bleed2 = bleed_pressure_group2 end
	  if dial_bleed2 >= GROUP2_PSI_CONSUMED then dial_bleed2 = GROUP2_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed2"),dial_bleed2)
     else 
      dial_bleed2=dial_bleed2-1
      --if dial_bleed2 < GROUP2_PSI then dial_bleed2 = GROUP2_PSI end
	  if dial_bleed2 < GROUP2_PSI_CONSUMED then dial_bleed2 = GROUP2_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed2"),dial_bleed2)
     end
	 -- limits
	  if GROUP2_PSI_CONSUMED >= 85 then 
      --GROUP2_PSI_CONSUMED = 85 -- top limit 
      group2_overpressed = 1
      else
      group2_overpressed = 0	
      end
	   -- Group 3
    -- increasing 
	 if GROUP3_PSI_CONSUMED >= dial_bleed3 then 
      dial_bleed3=dial_bleed3+1
	  if dial_bleed3 >= GROUP3_PSI_CONSUMED then dial_bleed3 = GROUP3_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed3"),dial_bleed3)
     else 
      dial_bleed3=dial_bleed3-1
	  if dial_bleed3 < GROUP3_PSI_CONSUMED then dial_bleed3 = GROUP3_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed3"),dial_bleed3)
     end
	 -- limits
	  if GROUP3_PSI_CONSUMED >= 85 then 
      group3_overpressed = 1
      else
      group3_overpressed = 0	
      end
	  -- Group 4
    -- increasing 
	 if GROUP4_PSI_CONSUMED >= dial_bleed4 then 
      dial_bleed4=dial_bleed4+1
	  if dial_bleed4 >= GROUP4_PSI_CONSUMED then dial_bleed4 = GROUP4_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed4"),dial_bleed4)
     else 
      dial_bleed4=dial_bleed4-1
	  if dial_bleed4 < GROUP4_PSI_CONSUMED then dial_bleed4 = GROUP4_PSI_CONSUMED end
      setDataf(findDataref("Gastonreif/Heritage/dial_bleed4"),dial_bleed4)
     end
	 -- limits
	  if GROUP4_PSI_CONSUMED >= 85 then 
      group4_overpressed = 1
      else
      group4_overpressed = 0	
      end
    else -- no battery
     dial_bleed1=dial_bleed1-1
     if dial_bleed1 <= 0 then dial_bleed1 = 0 end
     setDataf(findDataref("Gastonreif/Heritage/dial_bleed1"),dial_bleed1)
     dial_bleed2=dial_bleed2-1
     if dial_bleed2 <= 0 then dial_bleed2 = 0 end
     setDataf(findDataref("Gastonreif/Heritage/dial_bleed2"),dial_bleed2)
	 dial_bleed3=dial_bleed3-1
     if dial_bleed3 <= 0 then dial_bleed3 = 0 end
     setDataf(findDataref("Gastonreif/Heritage/dial_bleed3"),dial_bleed3)
	 dial_bleed4=dial_bleed4-1
     if dial_bleed4 <= 0 then dial_bleed4 = 0 end
     setDataf(findDataref("Gastonreif/Heritage/dial_bleed4"),dial_bleed4)
    end
    -- Airbleed ends 
    -- Airflow gauge 
    if WEHAVEPOWER ~= 0 then
     if PRESS_CABIN_DIFF <= 2 then -- fans at auto are on 
      if FWD_FAN2 == 2 or FWD_FAN2 == 1 then fan2_multiplier = 1 else fan2_multiplier = 0 end
      if FWD_FAN13 == 2 or FWD_FAN13 == 1 then fan13_multiplier = 1 else fan13_multiplier = 0 end
     else
      if FWD_FAN2 == 2 then fan2_multiplier = 1 else fan2_multiplier = 0 end
      if FWD_FAN13 == 2 then fan13_multiplier = 1 else fan13_multiplier = 0 end
     end 
     if FWD_SUPPLY == 1 then fan_supply_multiplier = 2 end
     if FWD_SUPPLY == 2 then fan_supply_multiplier = 1 end
     if FWD_SUPPLY == 0 then fan_supply_multiplier = 0 end
     fan_multiplier = fan2_multiplier + fan13_multiplier + fan_supply_multiplier
     AIRFLOW_BY_FANS = fan_multiplier*(2-altitude/60000)
     --limits no necessary i think 
     --
     --increasing 
     if AIRFLOW_BY_FANS >= dial_airflow then
      dial_airflow=dial_airflow+0.02
      if dial_airflow >= AIRFLOW_BY_FANS then dial_airflow = AIRFLOW_BY_FANS end
      setDataf(findDataref("Gastonreif/Heritage/dial_airflow"),dial_airflow) 
     else -- decreasing 
      dial_airflow=dial_airflow-0.02
      if dial_airflow < AIRFLOW_BY_FANS then dial_airflow = AIRFLOW_BY_FANS end
      setDataf(findDataref("Gastonreif/Heritage/dial_airflow"),dial_airflow) 
     end
    else
     dial_airflow=dial_airflow-0.05
     if dial_airflow <= 0 then dial_airflow = 0 end
     setDataf(findDataref("Gastonreif/Heritage/dial_airflow"),dial_airflow) 
    end
    -- Aircondition temperatures, massflow is for init taken from init even if its below this 
   if battery_on ~= 0 then
    --if WEHAVEPOWER ~= 0 then -- main function
	--if ENG1_POWER ~= 0 then -- main function
	-- initials
	--Aircon groups failed logic
    if GROUP34_FAILED_SWITCH == 1 then
     knob_temperature4 = knob_temperature3
     setDataf(findDataref("Gastonreif/Heritage/knob_temperature4"),knob_temperature4)
    end
    if GROUP2_FAILED_SWITCH == 1 then
     knob_temperature2 = knob_temperature3
     setDataf(findDataref("Gastonreif/Heritage/knob_temperature2"),knob_temperature2)
    end
    if GROUP1_FAILED_SWITCH == 1 then
     knob_temperature1 = knob_temperature2
     setDataf(findDataref("Gastonreif/Heritage/knob_temperature1"),knob_temperature1)
    end
	--
	if ENG1_POWER ~= 0 then -- Engine running 
	 if ENG1_BLEED_AIR == 0 then --providing bleed air
	  BLEED_FROM_ENG1=1
	 else
	  BLEED_FROM_ENG1=0
	 end
	else
	 BLEED_FROM_ENG1=0
	end
	if ENG2_POWER ~= 0 then -- Engine running 
	 if ENG2_BLEED_AIR == 0 then --providing bleed air
	  BLEED_FROM_ENG2=1
	 else
	  BLEED_FROM_ENG2=0
	 end
	else
	 BLEED_FROM_ENG2=0
	end
	if ENG3_POWER ~= 0 then -- Engine running 
	 if ENG3_BLEED_AIR == 0 then --providing bleed air
	  BLEED_FROM_ENG3=1
	 else
	  BLEED_FROM_ENG3=0
	 end
	else
	 BLEED_FROM_ENG3=0
	end
	if ENG4_POWER ~= 0 then -- Engine running 
	 if ENG4_BLEED_AIR == 0 then --providing bleed air
	  BLEED_FROM_ENG4=1
	 else
	  BLEED_FROM_ENG4=0
	 end
	else
	 BLEED_FROM_ENG4=0
	end
    -- crossbleed effect
	if CROSSBLEED12 == 1 then
     GROUP1_HAS_AIR = BLEED_FROM_ENG1 + BLEED_FROM_ENG2
	 GROUP2_HAS_AIR = BLEED_FROM_ENG2 + BLEED_FROM_ENG1
	else
     GROUP1_HAS_AIR = BLEED_FROM_ENG1
	 GROUP2_HAS_AIR = BLEED_FROM_ENG2
	end
	if CROSSBLEED34 == 1 then
     GROUP3_HAS_AIR = BLEED_FROM_ENG3 + BLEED_FROM_ENG4
	 GROUP4_HAS_AIR = BLEED_FROM_ENG4 + BLEED_FROM_ENG3
	else 
     GROUP3_HAS_AIR = BLEED_FROM_ENG3
	 GROUP4_HAS_AIR = BLEED_FROM_ENG4
	end
    -- Group1 
    if GROUP1_HAS_AIR ~= 0 and AIRBLEED_COND1_ON ~= 0 then -- condition valve is open, engine is running and can provide hotncold air via exchangers 
     -- constants
     if dial_massflow1 > 0 then -- airflow is increasing 
      cau_inlet1 = cau_inlet1+0.1 -- rotating when air flows in 
	  --limit 
	  --if cau_inlet1 >= ENG1_N1 then cau_inlet1 = ENG1_N1 end 
      if cau_inlet1 >= 100 then cau_inlet1 = 100 end -- rotation generates heat upto 100C
     else -- massflow can be cut with power on 
      cau_inlet1 = cau_inlet1-0.1
      if cau_inlet1 <= 0 then cau_inlet1 = 0 end
     end
     if dial_massflow1 > 0 then -- airflow is increasing 
      cau_outlet1 = cau_outlet1-0.1 -- rotating when air flows in and pressure drops causes loss of heat 
      --if cau_outlet1 <= -ENG1_N1 then cau_outlet1 = -ENG1_N1 end -- rotation generates chill down to -25C with drop of 105C
	  -- limit 
	  if cau_outlet1 <= -105 then cau_outlet1 = -105 end -- rotation generates chill down to -25C with drop of 105C
     else -- massflow can be cut with power on 
      cau_outlet1 = cau_outlet1+0.1
      if cau_outlet1 >= 0 then cau_outlet1 = 0 end
     end	  
	 -- mass flow valve - regulates heat from engine automatic by temperature differential
     --delta_primary_exchanger=math.abs(tca_eng1_temp-TAT) -- not used 
	 --if dial_temp1 < TAT then 
	 --if dial_temp1 > TAT then 
	 if tca_eng1_temp <= Total then -- Engine temperature is lower then inside the duct 
	  -- BUG must be regulated, not 0 or 1
	  massflow_valve1=massflow_valve1+0.01
	  if massflow_valve1 >= 1 then massflow_valve1 = 1 end -- fully open, heat cabin
	 else
	  massflow_valve1=massflow_valve1-0.01
	  if massflow_valve1 <= 0 then massflow_valve1 = 0 end -- closed valve, isolated, low temp needed 
	 end
     -- primary exchanger
     --if primary_exchanger1_temp <= TAT then -- heating 
      primary_exchanger1_temp = (tca_eng1_temp*massflow_valve1)+Total
     --else -- cooling, temperature of air causes lower the temperature and excess is blown away 
      --primary_exchanger1_temp = (tca_eng1_temp*massflow_valve1)-TAT -- here add extraction of temperature by hotcold automatic below 170C
     --end
	 -- limits 
	 if primary_exchanger1_temp <= -50 then primary_exchanger1_temp = -50 end
	 -- ejector extraction of temperature above 170C
	 if AIRCON_EJECTOR1_FAIL == 0 then
      if primary_exchanger1_temp >= 169 then primary_exchanger1_temp = 169 end -- rest of temperature excess is blown into exhaust nozzle 
	 else
	  if primary_exchanger1_temp >= 170 then primary_exchanger1_temp = 170 end -- causes exchanger fail
	 end
     --if secondary_exchanger1_temp <= TAT then -- heating 
      secondary_exchanger1_temp=(primary_exchanger1_temp+cau_inlet1)+Total -- here add also bypass hot extraction
     --else -- cooling 
     -- secondary_exchanger1_temp=(primary_exchanger1_temp+cau_inlet1)-TAT -- here add also bypass hot extraction
     --end
     -- limits 
     if secondary_exchanger1_temp <= -50 then secondary_exchanger1_temp = -50 end
	 -- ejector extraction of temperature above 170C
	 if AIRCON_EJECTOR1_FAIL == 0 then
      if secondary_exchanger1_temp >= 169 then secondary_exchanger1_temp = 169 end -- rest of temperature excess is blown into exhaust nozzle 
	 else
	  if secondary_exchanger1_temp >= 170 then secondary_exchanger1_temp = 170 end -- causes exchanger fail
	 end
     -- CAU dial is temperature beyond primary_exchanger
     -- increasing 
     if primary_exchanger1_temp >= dial_cau1 then 
      dial_cau1 = dial_cau1 + 0.01
      if dial_cau1 >= primary_exchanger1_temp then dial_cau1 = primary_exchanger1_temp end
      -- limits 
      if dial_cau1 >= 200 then dial_cau1 = 200 end
      setDataf(findDataref("Gastonreif/Heritage/dial_cau1"),dial_cau1)
     else -- decreasing 
      dial_cau1 = dial_cau1 - 0.01
      if dial_cau1 < primary_exchanger1_temp then dial_cau1 = primary_exchanger1_temp end
      -- limits 
      if dial_cau1 <= 50 then dial_cau1 = 50 end
      setDataf(findDataref("Gastonreif/Heritage/dial_cau1"),dial_cau1)
     end 
     -- fuel valve selector with controller
	 if RESULT_COUNT_ACC1 <= 2 then -- some fuel pumps operating, 3 is all off
      if FUEL_VALVE_BLEED1 == 1 then -- fuel valve is shut means temperature needs to be hot, no cool by fuel
       fuel_exchanger1_valve = fuel_exchanger1_valve - 0.1
       if fuel_exchanger1_valve <= 0 then fuel_exchanger1_valve = 0 end
      end
      --if FUEL_VALVE_BLEED1 == 2 then -- fuel valve is open means temperature needs to be cooled, temporary diasabled 
      -- fuel_exchanger1_valve = fuel_exchanger1_valve + 0.1
      -- if fuel_exchanger1_valve >= 100 then fuel_exchanger1_valve = 100 end
      --end
      if FUEL_VALVE_BLEED1 == 0 then -- fuel valve is automatic, however in Colimata 1.50 no auto available 
       if fueltemp1_agregated >= 60.0 then -- default setpoint not changeable
        fuel_exchanger1_valve = fuel_exchanger1_valve - 0.1
        if fuel_exchanger1_valve <= 0 then fuel_exchanger1_valve = 0 end -- close it, no more heating, we need cold fuel 
       else
        fuel_exchanger1_valve = fuel_exchanger1_valve + 0.1
        if fuel_exchanger1_valve >= 100 then fuel_exchanger1_valve = 100 end -- open it, allow fuel temp rise a bit 
       end 
      end
	 end
     fuel_valve_temperature1 = fueltemp1_agregated*(fuel_exchanger1_valve/100) -- 0 means closed and no cooling effect by fuel 
     -- Fuel exchanger
     --if secondary_exchanger1_temp <= fueltemp1_agregated then -- heating 
     if secondary_exchanger1_temp <= fueltemp1_agregated then -- heating 
      --fuel_exchanger1 = secondary_exchanger1_temp + fueltemp1_agregated -- heating by fuel 
      fuel_exchanger1 = secondary_exchanger1_temp + fuel_valve_temperature1 -- heating by fuel 
     else -- cooling by fuel temp 
      --fuel_exchanger1 = secondary_exchanger1_temp - fueltemp1_agregated -- cooling by fuel 
      fuel_exchanger1 = secondary_exchanger1_temp - fuel_valve_temperature1 -- cooling by fuel 
     end
     -- limits 
     if fuel_exchanger1 <= -50 then fuel_exchanger1 = -50 end
     --if fuel_exchanger1 >= 120 then fuel_exchanger1 = 120 end -- rest of temperature excess is blown into exhaust nozzle 
	 if fuel_exchanger1 >= 119 then fuel_exchanger1 = 119 end -- rest of temperature excess is blown into exhaust nozzle 
     -- CAU unit freezing provide duct air temperature 
	 -- duct ajustment
	 -- VR fix temporary
	--if VR_FIX_RT_ON == 0 then  -- VR fix is off, maybe not needed here because selector is set correctly
	 if knob_temperature1 == -1.0 then -- lower the ductemp by 10
	 -- if dial_duct1 >= forced_duct1_temp then -- increase
	   forced_duct1_temp = forced_duct1_temp +0.01
	   if forced_duct1_temp >= 10 then forced_duct1_temp = 10 end
	--  else -- decrease
	 --  forced_duct1_temp = forced_duct1_temp +0.01
	 --  if forced_duct1_temp >= 10 then forced_duct1_temp = 10 end
	  --end  
	 end
	 if knob_temperature1 == 1.0 then -- rise the ductemp by 10
	 -- if dial_duct1 <= forced_duct1_temp then -- increase
	   forced_duct1_temp = forced_duct1_temp -0.01
	   if forced_duct1_temp <= -10 then forced_duct1_temp = -10 end
	 -- else
	 --  forced_duct1_temp = forced_duct1_temp -0.01
	 --  if forced_duct1_temp <= -10 then forced_duct1_temp = -10 end
	 -- end
	 end
	-- else -- VR fix is ON
	-- if VR_FIX_TEMP1 >= 7.5 and VR_FIX_TEMP1 < 8.0 then -- lower the ductemp by 10
	--  if dial_duct1 >= forced_duct1_temp then -- increase
	--   forced_duct1_temp = forced_duct1_temp +0.01
	--   if forced_duct1_temp >= 10 then forced_duct1_temp = 10 end
	--  else -- decrease
	--   forced_duct1_temp = forced_duct1_temp -0.01
	--   if forced_duct1_temp <= 10 then forced_duct1_temp = 10 end
	--  end  
	-- end
	-- if VR_FIX_TEMP1 >= 10 then -- rise the ductemp by 10
	--  if dial_duct1 <= forced_duct1_temp then -- increase
	--   forced_duct1_temp = forced_duct1_temp -0.01
	--   if forced_duct1_temp <= -10 then forced_duct1_temp = -10 end
	--  else
	--   forced_duct1_temp = forced_duct1_temp +0.01
	--   if forced_duct1_temp >= -10 then forced_duct1_temp = -10 end
	--  end
	-- end
	--end -- end VR fix both on and off
	 -- reset of forced_duct1_temp to 0 is in dials section 
     duct1_temperature = fuel_exchanger1 + cau_outlet1 - forced_duct1_temp -- usually below 0, forced_duct1_temp is standby mode adjustment
     -- Duct gauges 
     if duct1_temperature >= dial_duct1 then  -- increasing 
      dial_duct1 = dial_duct1 + 0.01 
      if dial_duct1 >= duct1_temperature then dial_duct1 = duct1_temperature end
      -- limits 
      if dial_duct1 >= 120 then dial_duct1 = 120 end
      setDataf(findDataref("Gastonreif/Heritage/dial_duct1"),dial_duct1) -- -50 - 100
     else -- decreasing
      dial_duct1 = dial_duct1 - 0.01
      if dial_duct1 < duct1_temperature then dial_duct1 = duct1_temperature end
      -- limits 
      if dial_duct1 <= -50 then dial_duct1 = -50 end
      setDataf(findDataref("Gastonreif/Heritage/dial_duct1"),dial_duct1)
     end
     -- main cabin temperature logic 
     -- auto mode we assume 25C is comfort temperature 
	 --delta_CAU=math.abs(duct1_temperature-primary_exchanger1_temp)
	 -- presets first - knob positions are in various_timers section
	  --delta_CAU=preset_temp1-group1_temperature
	  --BUG here, temperature1_control_valve is steady only with group1_temperature, with dial_temp1 not
      --if dial_temp1 >= preset_temp1 then -- closing tcv valve is cooling the duct 
	  if group1_temperature >= preset_temp1 then -- closing tcv valve is cooling the duct 
       temperature1_control_valve = temperature1_control_valve - 1
       if temperature1_control_valve <= 0 then temperature1_control_valve = 0 end -- 0 is closed 
      else
       temperature1_control_valve = temperature1_control_valve + 1
       if temperature1_control_valve >= 100 then temperature1_control_valve = 100 end -- 100 is fully open hot air comes in 
