      if dial_bleed_coldhot1 >= temperature1_control_valve then dial_bleed_coldhot1 = temperature1_control_valve end
	  --if dial_bleed_coldhot1 >= TCV1_position then dial_bleed_coldhot1 = TCV1_position end
	  --if dial_bleed_coldhot1 <= TCV1_position then dial_bleed_coldhot1 = TCV1_position end
