    -- Mass flow gauges
	if battery_on == 1 then
	-- constants
	if GPU_UNIT_ON == 1 then
	 if GROUP1_HAS_AIR == 0 then
	  ground_flow1_surplus = -0.20 -- only GPU so lower massflow value
	 else
	  ground_flow1_surplus = 0.1 -- air from engine, high flow
	 end
	 if GROUP2_HAS_AIR == 0 then
	  ground_flow2_surplus = -0.20
	 else
	  ground_flow2_surplus = 0.1
	 end
	 if GROUP3_HAS_AIR == 0 then
	  ground_flow3_surplus = -0.20
	 else
	  ground_flow3_surplus = 0.1
	 end
	 if GROUP4_HAS_AIR == 0 then
	  ground_flow4_surplus = -0.20
	 else
	  ground_flow4_surplus = 0.1
	 end
	else
	 ground_flow1_surplus = 0
	 ground_flow2_surplus = 0
	 ground_flow3_surplus = 0
	 ground_flow4_surplus = 0
	end
	 if CROSSBLEED12 == 1 then
	   if BLEED_FROM_ENG1 == 1 then 
	    ENG1_POWERS_GROUP2 = 1
		flow1_multiplier=0.35
		else
		ENG1_POWERS_GROUP2 = 0
		flow1_multiplier=0.3
	   end 
	   if BLEED_FROM_ENG2 == 1 then 
	    ENG2_POWERS_GROUP1 = 1
		flow2_multiplier=0.35
		else
		ENG2_POWERS_GROUP1 = 0
		flow2_multiplier=0.3
	   end 
	 else
	  ENG1_POWERS_GROUP2 = 0
	  flow1_multiplier=0.3
	  ENG2_POWERS_GROUP1 = 0
	  flow2_multiplier=0.3
	 end 
	 if CROSSBLEED34 == 1 then
	   if BLEED_FROM_ENG3 == 1 then 
	    ENG3_POWERS_GROUP4 = 1
		flow3_multiplier=0.35
		else
		ENG3_POWERS_GROUP4 = 0
		flow3_multiplier=0.3
	   end 
	   if BLEED_FROM_ENG4 == 1 then 
	    ENG4_POWERS_GROUP3 = 1
		flow4_multiplier=0.35
		else
		ENG4_POWERS_GROUP3 = 0
		flow4_multiplier=0.3
	   end 
	 else
	  ENG3_POWERS_GROUP4 = 0
	  flow3_multiplier=0.3
	  ENG4_POWERS_GROUP3 = 0
	  flow4_multiplier=0.3
	 end 
	 --group1
	 if BLEED_FROM_ENG1 ~= 0 or GPU_UNIT_ON == 1 then 
     if AIRBLEED_COND1 == 0 then -- off
      dial_massflow1=dial_massflow1-0.01
      if dial_massflow1 <= 0 then dial_massflow1 = 0 end
      setDataf(findDataref("Gastonreif/Heritage/dial_massflow1"),dial_massflow1)
     else -- condition valve open 
      if GROUP1_PSI*(flow1_multiplier+ground_flow1_surplus) >= dial_massflow1 then -- increase 
       dial_massflow1=dial_massflow1+0.01
       if dial_massflow1 >= GROUP1_PSI*(flow1_multiplier+ground_flow1_surplus) then dial_massflow1 = GROUP1_PSI*(flow1_multiplier+ground_flow1_surplus) end
       setDataf(findDataref("Gastonreif/Heritage/dial_massflow1"),dial_massflow1)
      else -- decrease 
       dial_massflow1=dial_massflow1-0.01
       if dial_massflow1 <= GROUP1_PSI*(flow1_multiplier+ground_flow1_surplus) then dial_massflow1 = GROUP1_PSI*(flow1_multiplier+ground_flow1_surplus) end
       setDataf(findDataref("Gastonreif/Heritage/dial_massflow1"),dial_massflow1)
      end	  
     end
