      setDataf(findDataref("Gastonreif/Heritage/dial_massflow1"),dial_massflow1)
	 else -- condition valve is on
	  if ENG2_POWERS_GROUP1 == 0 then
	   dial_massflow1=dial_massflow1-0.01
       if dial_massflow1 <= 0 then dial_massflow1 = 0 end
       setDataf(findDataref("Gastonreif/Heritage/dial_massflow1"),dial_massflow1)
	  else -- yes, massflow from second engine
	   if GROUP2_PSI*(flow2_multiplier+ground_flow2_surplus) >= dial_massflow1 then -- increase 
        dial_massflow1=dial_massflow1+0.01
        if dial_massflow1 >= GROUP2_PSI*(flow2_multiplier+ground_flow2_surplus) then dial_massflow1 = GROUP2_PSI*(flow2_multiplier+ground_flow2_surplus) end
        setDataf(findDataref("Gastonreif/Heritage/dial_massflow1"),dial_massflow1)
       else -- decrease 
