        if dial_massflow1 <= GROUP2_PSI*(flow2_multiplier+ground_flow2_surplus) then dial_massflow1 = GROUP2_PSI*(flow2_multiplier+ground_flow2_surplus) end
        setDataf(findDataref("Gastonreif/Heritage/dial_massflow1"),dial_massflow1)
       end	     
