        setDataf(findDataref("Gastonreif/Heritage/dial_elec_freq_hz"),dial_elec_freq_hz)
       end
      end -- end last position was 3
      if last_ac_switch_position == 5 then -- was switched from next position 
       if gen4_frq_hz >= gen3_frq_hz then -- decrease value to match current is lower 
       	dial_elec_freq_hz=dial_elec_freq_hz-1
        if dial_elec_freq_hz <= gen3_frq_hz then 
        dial_elec_freq_hz = gen3_frq_hz 
        last_ac_switch_position = 4 -- matched current, exit 
        end
        setDataf(findDataref("Gastonreif/Heritage/dial_elec_freq_hz"),dial_elec_freq_hz)
       else -- increase value to current which is higher 
       	dial_elec_freq_hz=dial_elec_freq_hz+1
        if dial_elec_freq_hz >= gen3_frq_hz then 
        dial_elec_freq_hz = gen3_frq_hz 
        last_ac_switch_position = 4 -- matched current, exit and continue to current which is the same logic 
        end
        setDataf(findDataref("Gastonreif/Heritage/dial_elec_freq_hz"),dial_elec_freq_hz)
       end
      end -- end last position was 5
      if last_ac_switch_position == 4 then -- we are working in current selection
       dial_elec_freq_hz=dial_elec_freq_hz+1
       if dial_elec_freq_hz >= gen3_frq_hz then dial_elec_freq_hz = gen3_frq_hz end
       setDataf(findDataref("Gastonreif/Heritage/dial_elec_freq_hz"),dial_elec_freq_hz)
      end -- end switchover
     end -- end Generator no.3
     --..
     if ELEC_AC_VOLTAGE == 3 then -- Generator no.4 measuring 
      if last_ac_switch_position == 4 then -- was swicthed from previous position
       if gen3_frq_hz >= gen4_frq_hz then -- decrease value to match current is lower 
       	dial_elec_freq_hz=dial_elec_freq_hz-1
        if dial_elec_freq_hz <= gen4_frq_hz then 
        dial_elec_freq_hz = gen4_frq_hz 
