function brakes_hot() -- calculates brake temperature according to user braking
BRAKES_EFFORT = (brake_ratio + brake_ratio_left + brake_ratio_right)/3
if AFT_LIGHTS_TEST ~= 2 then 
 YELLOW_HYD_NOT_AVAIL=HYD_PUMP_LEFT_LP_YELLOW_LIGHT+HYD_PUMP_RIGHT_LP_YELLOW_LIGHT+HYD_LP_YELLOW_LIGHT
 else
 YELLOW_HYD_NOT_AVAIL=0 -- test is active, set no lights 
end
if WEHAVEPOWER ~= 0 then 
 if YELLOW_HYD_NOT_AVAIL == 0 or WEHAVEAIR_G == 1 then --yellow system powers brakes
  dial_brake_press=dial_brake_press-0.01
  if dial_brake_press <= BRAKES_EFFORT then dial_brake_press=BRAKES_EFFORT end 
  if dial_brake_press <= 0 then dial_brake_press = 0 end
  if dial_brake_press >= 1 then dial_brake_press = 1 end
  setDataf(findDataref("Gastonreif/Heritage/dial_brake_press"),dial_brake_press)
 else --no yellows
  dial_brake_press=dial_brake_press+0.01
  if dial_brake_press >= 1 then dial_brake_press = 1 end
  setDataf(findDataref("Gastonreif/Heritage/dial_brake_press"),dial_brake_press)
 end
else
 dial_brake_press=dial_brake_press+0.01
 if dial_brake_press >= 1 then dial_brake_press = 1 end
 setDataf(findDataref("Gastonreif/Heritage/dial_brake_press"),dial_brake_press)
end

