--Brakes logic and tests
REAR_BRAKES_TEST_ON=BRAKES_MAIN_FWD1_PUSH+BRAKES_MAIN_FWD2_PUSH+BRAKES_MAIN_FWD3_PUSH+BRAKES_MAIN_FWD4_PUSH+BRAKES_MAIN_REAR1_PUSH+BRAKES_MAIN_REAR2_PUSH+BRAKES_MAIN_REAR3_PUSH+BRAKES_MAIN_REAR4_PUSH
