  if braketemp >= 600 then braketemp = 600 end
  --bridge_dial_braketemp[0] = braketemp --export braketemp
  if REAR_BRAKES_TEST_ON ~= 0 then
   dial_brake_temp = (CON_BRAKE_TEMP_REAR+braketemp)/2
   setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
