  braketemp = braketemp-0.005 + tire_blown_multiplier --*brake_fans_effect --+ WHEELS_ROTATE/25000 --+ hold_time*BRAKES_EFFORT*0.01  --rotate wheels must be between 0-1, 250 is 250kts
  --TEST2 = braketemp -- debug item 2 can be shown on datarefs TESTVALUE2 
  -- brake temp dial
 --limits/dial range 
  if braketemp <= 0 then braketemp = 0 end
  if braketemp >= 600 then braketemp = 600 end
  --bridge_dial_braketemp[0] = braketemp
  if REAR_BRAKES_TEST_ON ~= 0 then
   dial_brake_temp = (CON_BRAKE_TEMP_REAR+braketemp)/2
   setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
  else -- default operation
  dial_brake_temp = braketemp
  setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
  end
 end
 if BRAKE_FANS == 0 then
  brake_fans_effect = 1
  --braketemp = braketemp+0.0001*brake_fans_effect + WHEELS_ROTATE/2500 + 10*hold_time*BRAKES_EFFORT  --rotate wheels must be between 0-1, 250 is 250kts
  braketemp = braketemp+0.0001*brake_fans_effect + WHEELS_ROTATE/5000 + BRAKES_EFFORT + tire_blown_multiplier  --rotate wheels must be between 0-1, 250 is 250kts
  --TEST3 = BRAKES_EFFORT
  --TEST3 = braketemp -- debug item 3 can be shown on datarefs TESTVALUE3 
  -- brake temp dial
 --limits/dial range 
  if braketemp <= 0 then braketemp = 0 end
  if braketemp >= 600 then braketemp = 600 end
  --bridge_dial_braketemp[0] = braketemp
  if REAR_BRAKES_TEST_ON ~= 0 then
   dial_brake_temp = (CON_BRAKE_TEMP_REAR+braketemp)/2
   setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
  else -- default operation
  dial_brake_temp = braketemp
  setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
  end
 end
--end cooling

--the formula for braking action including fan cooling
--braketemp = braketemp-0.0001*brake_fans_effect

--limit brakes value
if braketemp <= my_oat then braketemp = my_oat end --lowest limit
if braketemp >= 700 then 
 braketemp = 700 --upper limit
 TYRE_BLOW = 1 --triggers failure
 setDatai(findDataref("Colimata/CON_A_LGEAR_nose_tire_blowup_i"),TYRE_BLOW)
end --lowest limit, tire blown

  if IP_LIGHTS_TEST == 0 then
   if braketemp >= 220 and braketemp <= 600 then
    CON_BRAKES_OHEAT = 1
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
    else 
    CON_BRAKES_OHEAT = 0
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
   end

   if braketemp >= 601 then
    BRAKE_FAIL = 1
    CON_BRAKES_OHEAT = 1
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
    else 
    BRAKE_FAIL = 0
   end
  end
------------------------------------------------
 end
 
 -- airplane is not moving
 if WHEELS_ROTATE <= 4 and GEAR_DOWN == 1 then
 ------------------------------------------------
 --this is becnrmark-elapsed time for routine FOR
--timer1 = os.clock()
--TEST3 = timer1
timestamp = 0
--heating--

 --brakes not needed to be applied-------------------------------------------------------------

  --hold_time = os.clock() - timer1 
  --TEST1 = hold_time -- debug item 1 can be shown on datarefs TESTVALUE1
--end-------------------------------------------------------------------------
--cooling--
--TEST1 = braketemp -- debug item 1 can be shown on datarefs TESTVALUE1 
 if BRAKE_FANS == 1 then
  brake_fans_effect = 1.59
 else
  brake_fans_effect = 1.1
 end
--end cooling

--the formula for standstill cooling including fan cooling
  --for w=1,100000 do 
  -- timestamp = timestamp + w 
  -- TEST3 = timestamp
   --if BRAKES_EFFORT <= 0.19 then --failsafe exit
   --  do return end --this should exit this loop
 --  --or break 
   --end
   --braketemp = braketemp*brake_fans_effect+1
   --braketemp = braketemp+0.00001
   braketemp = braketemp-0.001*brake_fans_effect + tire_blown_multiplier
   -- brake temp dial
 --limits/dial range 
   if braketemp <= 0 then braketemp = 0 end
   if braketemp >= 600 then braketemp = 600 end
   --bridge_dial_braketemp[0] = braketemp
   if REAR_BRAKES_TEST_ON ~= 0 then
    dial_brake_temp = (CON_BRAKE_TEMP_REAR+braketemp)/2
    setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
   else -- default operation
   dial_brake_temp = braketemp
   setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
   end
   --limit brakes value
   if braketemp <= my_oat then braketemp = my_oat end --lowest limit
   if braketemp >= 700 then 
     braketemp = 700 --upper limit
     TYRE_BLOW = 1 --triggers failure
	 setDatai(findDataref("Colimata/CON_A_LGEAR_nose_tire_blowup_i"),TYRE_BLOW)
   end --lowest limit, tire blown

  if IP_LIGHTS_TEST == 0 then
   if braketemp >= 220 and braketemp <= 600 then
    CON_BRAKES_OHEAT = 1
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
   else 
    CON_BRAKES_OHEAT = 0
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
   end

   if braketemp >= 601 then
    BRAKE_FAIL = 1
	CON_BRAKES_OHEAT = 1
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
   else 
    BRAKE_FAIL = 0
   end
  end
-------


------------------------------------------------
 end
 
 --airplane is flying with gear up
 if GEAR_DOWN == 0 then
 ------------------------------------------------
 --this is becnrmark-elapsed time for routine FOR
--timer1 = os.clock()
timestamp = 0
--heating--

 --brakes not needed to be applied-------------------------------------------------------------

  --hold_time = os.clock() - timer1 
--end-------------------------------------------------------------------------
--cooling inside bay--
 if BRAKE_FANS == 1 then
  brake_fans_effect = 1.59
 else
  brake_fans_effect = 1.1
 end
--end cooling

--the formula for gearup
braketemp = braketemp-0.0001*brake_fans_effect
-- brake temp dial
 --limits/dial range 
 if braketemp <= 0 then braketemp = 0 end
 if braketemp >= 600 then braketemp = 600 end
 --bridge_dial_braketemp[0] = braketemp
 if REAR_BRAKES_TEST_ON ~= 0 then
  dial_brake_temp = (CON_BRAKE_TEMP_REAR+braketemp)/2
  setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
 else -- default operation
 dial_brake_temp = braketemp
 setDataf(findDataref("Gastonreif/Heritage/dial_brake_temp"),dial_brake_temp)
 end
--limit brakes value
if braketemp <= my_oat then braketemp = my_oat end --lowest limit
if braketemp >= 700 then 
 braketemp = 700 --upper limit
 TYRE_BLOW = 1 --triggers failure
 setDatai(findDataref("Colimata/CON_A_LGEAR_nose_tire_blowup_i"),TYRE_BLOW)
end --lowest limit, tire blown

  if IP_LIGHTS_TEST == 0 then
   if braketemp >= 220 and braketemp <= 600 then
    CON_BRAKES_OHEAT = 1
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
    else 
    CON_BRAKES_OHEAT = 0
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
   end

   if braketemp >= 601 then
    BRAKE_FAIL = 1
    CON_BRAKES_OHEAT = 1
	setDatai(findDataref("Colimata/CON_IP_lgt_oheat_wheels_i"),CON_BRAKES_OHEAT)
    else 
    BRAKE_FAIL = 0
   end
  end
------------------------------------------------
 end
end

