	CON_CG_POINTER_MOD = CON_CG_POINTER_ORIG
	setDataf(findDataref("Gastonreif/Heritage/con_cg_pointer_mod"),CON_CG_POINTER_MOD) 
else 
 -- !!!!!! below is my fuel system 
 -- initial load
 if WEHAVEPOWER ~= 0 and first_fuel_init == 0 then
  --if first_fuel_init == 0 then
   -- load fuel status into new gauges
    FUEL_TOTAL_KG_MOD=FUEL_TOTAL_KG_ORIG -- load once original to modified
	CON_TANK1 = CON_TANK1_ORIG
	dial_con_tank1 = CON_TANK1
	setDataf(findDataref("Gastonreif/Heritage/fueltank1"),dial_con_tank1)
