	CON_TANK3 = CON_TANK3_ORIG
	dial_con_tank3 = CON_TANK3
	setDataf(findDataref("Gastonreif/Heritage/fueltank3"),dial_con_tank3)
	CON_TANK4 = CON_TANK4_ORIG
	dial_con_tank4 = CON_TANK4
	setDataf(findDataref("Gastonreif/Heritage/fueltank4"),dial_con_tank4)
	CON_TANK5 = CON_TANK5_ORIG
	dial_con_tank5 = CON_TANK5
	setDataf(findDataref("Gastonreif/Heritage/fueltank5"),dial_con_tank5)
	CON_TANK5A = CON_TANK5A_ORIG
	dial_con_tank5a = CON_TANK5A
	setDataf(findDataref("Gastonreif/Heritage/fueltank5A"),dial_con_tank5a)
	CON_TANK6 = CON_TANK6_ORIG
	dial_con_tank6 = CON_TANK6
	setDataf(findDataref("Gastonreif/Heritage/fueltank6"),dial_con_tank6)
	CON_TANK7 = CON_TANK7_ORIG
	dial_con_tank7 = CON_TANK7
	setDataf(findDataref("Gastonreif/Heritage/fueltank7"),dial_con_tank7)
	CON_TANK7A = CON_TANK7A_ORIG
	dial_con_tank7a = CON_TANK7A
	setDataf(findDataref("Gastonreif/Heritage/fueltank7A"),dial_con_tank7a)
	CON_TANK8 = CON_TANK8_ORIG
	dial_con_tank8 = CON_TANK8
	setDataf(findDataref("Gastonreif/Heritage/fueltank8"),dial_con_tank8)
	CON_TANK9 = CON_TANK9_ORIG
	dial_con_tank9 = CON_TANK9
	setDataf(findDataref("Gastonreif/Heritage/fueltank9"),dial_con_tank9)
	CON_TANK10 = CON_TANK10_ORIG
	dial_con_tank10 = CON_TANK10
	setDataf(findDataref("Gastonreif/Heritage/fueltank10"),dial_con_tank10)
	CON_TANK11 = CON_TANK11_ORIG
	dial_con_tank11 = CON_TANK11
	setDataf(findDataref("Gastonreif/Heritage/fueltank11"),dial_con_tank11)
	delay_counter_init = delay_counter_init + 0.5
	if delay_counter_init >= 1 then  -- no reset
     first_fuel_init = 1
	end
  --end 
 end
 -- Refuelling 
 if GPU_UNIT_ON == 1 then -- only at ground 
  if REFUEL_AVAILABLE == 9 then -- start loading fuel when all inlet valves are on 
   -- here added CSD reconnect at ground 
   csd1_was_disconnected = 0
   csd2_was_disconnected = 0
   csd3_was_disconnected = 0
   csd4_was_disconnected = 0
   --
  	if stopover_refuel == 0 then 
  	 FUEL_TOTAL_KG_MOD = FUEL_TOTAL_KG_ORIG -- load new target fuel selected from menu
  	 stopover_refuel = 1 -- refueled
  	end
  	-- Main tanks filling surplus 
  	-- TANK1 4240 kg 
	--fuel_total_tank1 = CON_TANK1_ORIG+CON_TANK1
	--fuel_total_tank1 = CON_TANK1
	if CON_TANK1 < FUEL_TOTAL_KG_MOD then 
  	 CON_TANK1=CON_TANK1+(38/4) -- speed is 38kg/s from the tanker, as 4 tanks are filled at the same time reduce per one
  	 if CON_TANK1 >= 4240 then 
  	  CON_TANK1 = 4240 
  	  fueltank1full = 1
  	 else
      fueltank1full = 0
  	 end
  	end
  	-- TANK2 4620 kg 
	--fuel_total_tank2 = CON_TANK2_ORIG+CON_TANK2
	--fuel_total_tank2 = CON_TANK2
  	if CON_TANK2 < FUEL_TOTAL_KG_MOD then 
  	 CON_TANK2=CON_TANK2+(38/4)
  	 if CON_TANK2 >= 4620 then 
  	  CON_TANK2 = 4620 
  	  fueltank2full = 1
  	 else
      fueltank2full = 0
  	 end
  	end
  	-- TANK3 4620 kg 
	--fuel_total_tank3 = CON_TANK3_ORIG+CON_TANK3
	--fuel_total_tank3 = CON_TANK3
  	if CON_TANK3 < FUEL_TOTAL_KG_MOD then 
  	 CON_TANK3=CON_TANK3+(38/4)
  	 if CON_TANK3 >= 4620 then 
  	  CON_TANK3 = 4620
      fueltank3full = 1
  	 else  
      fueltank3full = 0
  	 end
  	end
  	-- TANK4 4240 kg 
	--fuel_total_tank4 = CON_TANK4_ORIG+CON_TANK4
	--fuel_total_tank4 = CON_TANK4
  	if CON_TANK4 < FUEL_TOTAL_KG_MOD then 
  	 CON_TANK4=CON_TANK4+(38/4)
  	 if CON_TANK4 >= 4240 then 
  	  CON_TANK4 = 4240 
  	  fueltank4full = 1
  	 else
  	  fueltank4full = 0
  	 end
  	end
  	-- total after main tanks filled
  	--fuel_totalizer_main = (CON_TANK1_ORIG+CON_TANK1) + (CON_TANK2_ORIG+CON_TANK2) + (CON_TANK3_ORIG+CON_TANK3) + (CON_TANK4_ORIG+CON_TANK4)
	fuel_totalizer_main = CON_TANK1 + CON_TANK2 + CON_TANK3 + CON_TANK4
	--heritage_debug1=fuel_totalizer_main
    --setDataf(findDataref("Gastonreif/Heritage/debug1"),heritage_debug1)
    --heritage_debug2=(FUEL_TOTAL_KG_MOD-fuel_totalizer_main)
    --setDataf(findDataref("Gastonreif/Heritage/debug2"),heritage_debug2)
    --heritage_debug3=fueltank1full+fueltank2full
    --setDataf(findDataref("Gastonreif/Heritage/debug3"),heritage_debug3)
    --heritage_debug4=fueltank3full+fueltank4full
    --setDataf(findDataref("Gastonreif/Heritage/debug4"),heritage_debug4)
  	-- first main feeder tanks 5 and 8
  	if fueltank1full == 1 and fueltank4full == 1 then
  	 -- TANK5 7270 kg
  	 if CON_TANK5 < (FUEL_TOTAL_KG_MOD-fuel_totalizer_main) then -- remaining fuel to be filled after counting main tanks
  	  CON_TANK5=CON_TANK5+(38/4)
  	  if CON_TANK5 >= 7270 then 
  	   CON_TANK5 = 7270 
  	   fueltank5full = 1
  	  else
  	   fueltank5full = 0
  	  end
  	 end
  	 -- TANK8 12970 kg
  	 if CON_TANK8 < (FUEL_TOTAL_KG_MOD-fuel_totalizer_main) then 
  	  CON_TANK8=CON_TANK8+(38/4)
  	  if CON_TANK8 >= 12970 then 
  	   CON_TANK8 = 12970 
  	   fueltank8full = 1
  	  else
  	   fueltank8full = 0
  	  end
  	 end
  	end
  	-- total after 5 and 8 filled
  	fuel_totalizer_58 = fuel_totalizer_main + CON_TANK5 + CON_TANK8
  	-- first main feeder tanks 6 and 7
  	if fueltank2full == 1 and fueltank3full == 1 then
  	 -- TANK6 11700 kg
  	 if CON_TANK6 < (FUEL_TOTAL_KG_MOD-fuel_totalizer_58) then 
  	  CON_TANK6=CON_TANK6+(38/4)
  	  if CON_TANK6 >= 11700 then 
  	   CON_TANK6 = 11700 
  	   fueltank6full = 1
  	  else
  	   fueltank6full = 0
  	  end
  	 end
  	 -- TANK7 7480 kg
  	 if CON_TANK7 < (FUEL_TOTAL_KG_MOD-fuel_totalizer_58) then 
  	  CON_TANK7=CON_TANK7+(38/4)
  	  if CON_TANK7 >= 7480 then 
  	   CON_TANK7 = 7480 
  	   fueltank7full = 1
  	  else
  	   fueltank7full = 0
  	  end
  	 end
  	end
  	-- total after 6 and 7 filled
  	fuel_totalizer_67 = fuel_totalizer_58 + CON_TANK6 + CON_TANK7
    -- second main feeder tanks 5a and 7a 
  	if fueltank5full == 1 and fueltank7full == 1 then
  	 -- TANK5a 2250 kg
  	 if CON_TANK5A < (FUEL_TOTAL_KG_MOD-fuel_totalizer_67) then 
  	  CON_TANK5A=CON_TANK5A+(38/4)
  	  if CON_TANK5A >= 2250 then 
  	   CON_TANK5A = 2250
  	   fueltank5afull = 1
  	  else
  	   fueltank5afull = 0
  	  end
  	 end
  	 -- TANK7a 2250 kg
  	 if CON_TANK7A < (FUEL_TOTAL_KG_MOD-fuel_totalizer_67)/2 then 
  	  CON_TANK7A=CON_TANK7A+(38/4)
  	  if CON_TANK7A >= 2250 then 
  	   CON_TANK7A = 2250
  	   fueltank7afull = 1
  	  else
  	   fueltank7afull = 0
  	  end
  	 end
  	end
  	-- total after 5a and 7a filled
  	fuel_totalizer_5a7a = fuel_totalizer_67 + CON_TANK5A + CON_TANK7A
  	-- TANK10 12060 kg
  	if fueltank5afull == 1 and fueltank7afull == 1 then
  	 if CON_TANK10 < (FUEL_TOTAL_KG_MOD-fuel_totalizer_5a7a) then 
  	  CON_TANK10=CON_TANK10+38
  	  if CON_TANK10 >= 12060 then 
  	   CON_TANK10 = 12060
  	   fueltank10full = 1
  	  else
  	   fueltank10full = 0
  	  end
  	 end
  	end
  	-- total after 10 filled
  	fuel_totalizer_10 = fuel_totalizer_5a7a + CON_TANK10
  	-- TANK9 11210 kg
  	if fueltank10full == 1 then
  	 if CON_TANK9 < (FUEL_TOTAL_KG_MOD-fuel_totalizer_10) then 
  	  CON_TANK9=CON_TANK9+38
  	  if CON_TANK9 >= 11210 then 
  	   CON_TANK9 = 11210
  	   fueltank9full = 1
  	  else
  	   fueltank9full = 0
  	  end
  	 end
  	end
  	-- total after 9 filled
  	fuel_totalizer_9 = fuel_totalizer_10 + CON_TANK9
  	-- last is TANK11 10520 kg
  	if fueltank9full == 1 then
  	 if CON_TANK11 < (FUEL_TOTAL_KG_MOD-fuel_totalizer_9) then 
  	  CON_TANK11=CON_TANK11+38
  	  if CON_TANK11 >= 10520 then 
  	   CON_TANK11 = 10520
  	   fueltank11full = 1
  	  else
  	   fueltank11full = 0
  	  end
  	 end
  	end
    -- total after 11 filled
  	fuel_totalizer_11 = fuel_totalizer_9 + CON_TANK11
  	CON_TOTALIZER = fuel_totalizer_11 -- show current total fuel loaded during refuel 
  	setDataf(findDataref("Gastonreif/Heritage/fueltotalizer"),CON_TOTALIZER)
  end -- end refuel 
 else
  stopover_refuel = 0 -- reset refuel loading after disconnecting GPU, will be available after connecting GPU again 
 end -- end GPU 
  if REFUEL_AVAILABLE ~= 9 then -- no refuel then totalizer shows current fuel quantity
   -- normal indication of current total fuel at engineers panel
