  --CG_M=cg_speed_effect
  ----cg_speed_effect -- just a shorter version
  --FORCE_FUEL_ORIG1=(CON_TANK1_ORIG*33*CG_M)+(CON_TANK2_ORIG*45.5*CG_M)+(CON_TANK3_ORIG*45.5*CG_M)+(CON_TANK4_ORIG*33*CG_M)+(CON_TANK5A_ORIG*44*CG_M)+(CON_TANK7A_ORIG*44*CG_M)
  --FORCE_FUEL_ORIG2=(CON_TANK5_ORIG*36.5*CG_M)+(CON_TANK6_ORIG*41.5*CG_M)+(CON_TANK7_ORIG*40.5*CG_M)+(CON_TANK8_ORIG*34*CG_M)
  --FORCE_FUEL_ORIG3=(CON_TANK9_ORIG*24.5*CG_M)+(CON_TANK10_ORIG*29*CG_M)+(CON_TANK11_ORIG*52*CG_M)
  --FORCE_FUEL_ORIG=FORCE_FUEL_ORIG1+FORCE_FUEL_ORIG2+FORCE_FUEL_ORIG3
  --cg_shift_meters_orig=FORCE_FUEL_ORIG/FUEL_TOTAL_KG_ORIG
  ----modified totals 
  --FORCE_FUEL_MOD1=(CON_TANK1*33*CG_M)+(CON_TANK2*45.5*CG_M)+(CON_TANK3*45.5*CG_M)+(CON_TANK4*33*CG_M)+(CON_TANK5A*44*CG_M)+(CON_TANK7A*44*CG_M)
  --FORCE_FUEL_MOD2=(CON_TANK5*36.5*CG_M)+(CON_TANK6*41.5*CG_M)+(CON_TANK7*40.5*CG_M)+(CON_TANK8*34*CG_M)+(CON_TANK9*24.5*CG_M)+(CON_TANK10*29*CG_M)+(CON_TANK11*52*CG_M)
  --FORCE_FUEL_MOD=FORCE_FUEL_MOD1+FORCE_FUEL_MOD2
  --cg_total_aircraft=operating_weight*(61.6*0.5275*CG_M) -- CG for ACF weight without fuel 
