  fuelrem_digits_set = fuelrem_digit1_set + fuelrem_digit2_set + fuelrem_digit3_set + fuelrem_digit4_set -- 4 is set 
  total_fuel_consumption = ENG1_FUEL_FLOW/3600 + ENG2_FUEL_FLOW/3600 + ENG3_FUEL_FLOW/3600 + ENG4_FUEL_FLOW/3600 -- per second 
  -- here push reset
  if pushbutton_totalrem == 1 then -- pressed 
   delay_pushbutton_totalrem = delay_pushbutton_totalrem + 1
   if delay_pushbutton_totalrem >= 3 then -- reset condition met 
   	N_position_state = 0
   	delay_pushbutton_totalrem = 0 -- reset pushbutton_totalrem counter 
   	-- reset displays
