    setDataf(findDataref("Gastonreif/Heritage/display_cgacweight"), display_cgacweight)
   end
  else -- pushbutton depressed
   delay_pushbutton_totalrem = 0 -- reset delay
  end
  -- main function 
  if knob_acweight == 0 then -- N normal ops 
