    acweight_digit2_set = 0
    acweight_digit3_set = 0
    acweight_digit4_set = 0
    acweight_digit5_set = 0
    fuelrem_digit1_set = 0
    fuelrem_digit2_set = 0
    fuelrem_digit3_set = 0
    fuelrem_digit4_set = 0
    fuelrem_surpluss = 0
   end
   if N_position_state == 1 then -- all set, normal ops 
   	-- to again set this up full reset is needed section above and pushbutton 3 sec.
   	-- add Fuelrem to AC weight only once
     if fuelrem_surpluss == 0 then
      display_cgfuelrem = display_cgfuelrem_stored -- load set value 
