      setDataf(findDataref("Gastonreif/Heritage/display_cgacweight"), display_cgacweight)
      fuelrem_surpluss = 1
     end
    -- decrease fuelweight 
    display_cgfuelrem = display_cgfuelrem - (total_fuel_consumption*0.1) -- 0.1 is 10xkg
    setDataf(findDataref("Gastonreif/Heritage/display_cgfuelrem"), display_cgfuelrem)
    display_cgacweight = display_cgacweight - (total_fuel_consumption*0.1)
    setDataf(findDataref("Gastonreif/Heritage/display_cgacweight"), display_cgacweight)
    -- limits 
    if display_cgfuelrem <= 0 then 
     display_cgfuelrem = 0
     setDataf(findDataref("Gastonreif/Heritage/display_cgfuelrem"), display_cgfuelrem)
    end
    if display_cgfuelrem >= 9999 then -- more than max. fuel
     display_cgfuelrem = 9999
     setDataf(findDataref("Gastonreif/Heritage/display_cgfuelrem"), display_cgfuelrem)
    end
    if display_cgacweight <= 7870 then -- Operating empty weight 
     display_cgacweight = 7870
     setDataf(findDataref("Gastonreif/Heritage/display_cgacweight"), display_cgacweight)
    end
    if display_cgacweight >= 19999 then -- more than max. taxi weight 
     display_cgacweight = 19999
     setDataf(findDataref("Gastonreif/Heritage/display_cgacweight"), display_cgacweight)
    end
   end
  else
  -- AC/weight
  	-- first digit 
  	if knob_acweight == -1 and acweight_digits_set ~= 5 then 
  	 if pushbutton_totalrem == 1 then -- pushed
  	  display_acweight_buffer = display_acweight_buffer + 1
  	  if display_acweight_buffer >= 10 then display_acweight_buffer = 0 end -- start over again 
  	  display_acweight_digit1 = display_acweight_buffer
