  	  if display_acweight_buffer >= 10 then display_acweight_buffer = 0 end -- start over again 
  	  display_acweight_digit5 = display_acweight_buffer
  	 end
     acweight_digit5_set = 1
    end
    -- now go back 
  -- FUEL total REM 
    -- first digit 
  	if knob_acweight == -4 and acweight_digits_set == 5 then 
  	 if pushbutton_totalrem == 1 then -- pushed
  	  display_acweight_buffer = display_acweight_buffer + 1
  	  if display_acweight_buffer >= 10 then display_acweight_buffer = 0 end -- start over again 
  	  display_fuelrem_digit1 = display_acweight_buffer
  	 end
     fuelrem_digit1_set = 1
    end
    -- second digit 
  	if knob_acweight == -3 and acweight_digits_set == 5 then 
  	 if pushbutton_totalrem == 1 then -- pushed
  	  display_acweight_buffer = display_acweight_buffer + 1
  	  if display_acweight_buffer >= 10 then display_acweight_buffer = 0 end -- start over again 
  	  display_fuelrem_digit2 = display_acweight_buffer
  	 end
     fuelrem_digit2_set = 1
    end
    -- third digit 
  	if knob_acweight == -2 and acweight_digits_set == 5 then 
  	 if pushbutton_totalrem == 1 then -- pushed
  	  display_acweight_buffer = display_acweight_buffer + 1
  	  if display_acweight_buffer >= 10 then display_acweight_buffer = 0 end -- start over again 
  	  display_fuelrem_digit3 = display_acweight_buffer
  	 end
     fuelrem_digit3_set = 1
    end
    -- fourth digit 
  	if knob_acweight == -1 and acweight_digits_set == 5 then 
  	 if pushbutton_totalrem == 1 then -- pushed
  	  display_acweight_buffer = display_acweight_buffer + 1
  	  if display_acweight_buffer >= 10 then display_acweight_buffer = 0 end -- start over again 
  	  display_fuelrem_digit4 = display_acweight_buffer
  	 end
     fuelrem_digit4_set = 1
    end
    -- set complete if: 
    if acweight_digits_set == 5 and fuelrem_digits_set == 4 then N_position_state = 1 end
    -- not compleeted if:
    -- if acweight_digits_set < 5 and fuelrem_digits_set < 4 then N_position_state = 0 end
    -- displays show
    display_cgacweight = 1*display_acweight_digit1 + 10*display_acweight_digit2 + 100*display_acweight_digit3 + 1000*display_acweight_digit4 + 10000*display_acweight_digit5
    setDataf(findDataref("Gastonreif/Heritage/display_cgacweight"), display_cgacweight)
    display_cgacweight_stored = display_cgacweight
    display_cgfuelrem = 1*display_fuelrem_digit1 + 10*display_fuelrem_digit2 + 100*display_fuelrem_digit3 + 1000*display_fuelrem_digit4
    setDataf(findDataref("Gastonreif/Heritage/display_cgfuelrem"), display_cgfuelrem)
    display_cgfuelrem_stored = display_cgfuelrem
  end
  -- ZFW knobs, actually dummy 
  if pushknob_ZFW == 0 then
