  else -- hold value when pushed
  	knob_ZFWCG = store_value_ZFWCG
  	setDatai(findDataref("Gastonreif/Heritage/knob_ZFWCG"),knob_ZFWCG) 
  end
   -- alternative differental method, seems best working
  cg_shift_meters_orig=cg_shift_meters_orig_last
  FORCE_FUEL_ORIG1=(CON_TANK1_ORIG*33)+(CON_TANK2_ORIG*45.5)+(CON_TANK3_ORIG*45.5)+(CON_TANK4_ORIG*33)+(CON_TANK5A_ORIG*44)+(CON_TANK7A_ORIG*44)
  FORCE_FUEL_ORIG2=(CON_TANK5_ORIG*36.5)+(CON_TANK6_ORIG*41.5)+(CON_TANK7_ORIG*40.5)+(CON_TANK8_ORIG*34)
  FORCE_FUEL_ORIG3=(CON_TANK9_ORIG*24.5)+(CON_TANK10_ORIG*29)+(CON_TANK11_ORIG*52)
  FORCE_FUEL_ORIG=FORCE_FUEL_ORIG1+FORCE_FUEL_ORIG2+FORCE_FUEL_ORIG3
  cg_shift_meters_orig=FORCE_FUEL_ORIG/FUEL_TOTAL_KG_ORIG
  --tunned to smooth the originals prevents trim jumps
  cg_trimjump = cg_shift_meters_orig_last-cg_shift_meters_orig -- example 35-33 is 2 which shifted to forward
  if cg_trimjump >= 2 then -- big jump forward 
   cg_shift_meters_orig_last = cg_shift_meters_orig_last - 0.1
   if cg_shift_meters_orig_last <= cg_shift_meters_orig then cg_shift_meters_orig_last = cg_shift_meters_orig end -- match 
  end 
  -- anything between is ok
  if cg_trimjump >= -2 and cg_trimjump < 2 then cg_shift_meters_orig_last = cg_shift_meters_orig end -- store last value
  if cg_trimjump < -2 then  -- big jump rearwards 
   cg_shift_meters_orig_last = cg_shift_meters_orig_last + 0.1
   if cg_shift_meters_orig_last >= cg_shift_meters_orig then cg_shift_meters_orig_last = cg_shift_meters_orig end
  end
 
  --modified totals 
  FORCE_FUEL_MOD1=(CON_TANK1*33)+(CON_TANK2*45.5)+(CON_TANK3*45.5)+(CON_TANK4*33)+(CON_TANK5A*44)+(CON_TANK7A*44)
  FORCE_FUEL_MOD2=(CON_TANK5*36.5)+(CON_TANK6*41.5)+(CON_TANK7*40.5)+(CON_TANK8*34)+(CON_TANK9*24.5)+(CON_TANK10*29)+(CON_TANK11*52)
  FORCE_FUEL_MOD=FORCE_FUEL_MOD1+FORCE_FUEL_MOD2
  cg_shift_meters_mod=FORCE_FUEL_MOD/CON_TOTALIZER
  --cg_total_aircraft=operating_weight*(61.6*0.5275) -- CG for ACF weight without fuel 
  --cg_shift_meters_mod=(FORCE_FUEL_MOD+cg_total_aircraft)/(CON_TOTALIZER+operating_weight)
  --cg_mod_meters = ((CON_CG_POINTER_ORIG/100)*61.6*cg_speed_effect)+cg_shift_diff -- example 0.58 * 61.6 - 2 = 33m
  --cg_position_metres_orig = ((CON_CG_POINTER_ORIG/100)*61.6)
  --cg_position_metres_orig = cg_shift_meters_orig
  cg_position_metres_orig = cg_shift_meters_orig_last
  --cg_mod_meters_diff = cg_position_metres_orig-cg_shift_meters_mod -- example 0.58 * 61.6 = 35.7m - 32m = 3.7
  cg_mod_meters_diff = cg_shift_meters_mod-cg_position_metres_orig -- example 0.58 * 61.6 = 35.7m - 32m = 3.7
  --cg_mod_ratio = CON_CG_POINTER_ORIG*(1+(cg_shift_meters/2))
  cg_mod_ratio = CON_CG_POINTER_ORIG+((cg_mod_meters_diff/100)*61.6) -- example 58% + 2% = 60 %
  --limits
  if cg_mod_ratio <= 50.01 then cg_mod_ratio = 50.01 end
  if cg_mod_ratio >= 60.10 then cg_mod_ratio = 60.10 end
  --TEST1=cg_shift_meters_mod 
  --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
  --TEST2=cg_position_metres_orig 
  --setDataf(findDataref("Colimata/CON_TESTVALUE_2_f"),TEST2)
  --TEST3=cg_mod_meters_diff 
  --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
 end
 -- Automatic trim callouts
 if FUEL_AUTOTRIM_DISABLED == 0 then
 --switch off because the manual trim is selected 
 if FUEL_TRIM_COMMAND == 5 then 
  FUEL_AUTOTRIM_DISABLED = 1
  setDatai(findDataref("Colimata/CON_EG_TANK_sw_fuel_lp_protect_i"),FUEL_AUTOTRIM_DISABLED)
 end
 trim_callout_takeoff = ENG1_POWER + ENG1_POWER + ENG3_POWER + ENG4_POWER
 if trim_sequence == 0 and cg_mod_ratio >= 52.75 then
  if trim_callout_takeoff == 4 and touch_down == 1 then -- ready for takeoff
   FUEL_TRIM_COMMAND = 1
   setDatai(findDataref("Colimata/CON_SYS_TRIM_fuel_request_i"),FUEL_TRIM_COMMAND) -- 1 takeoff, 2 flight, 3 descend, 4 landing
   trim_sequence = 1 -- do it only once
  end
 end
 trim_callout_flight = FLIGHT_RATING_1 + FLIGHT_RATING_2 + FLIGHT_RATING_3 +FLIGHT_RATING_4 -- 1111 are flight, 0000 takeoff
 if trim_sequence == 1 and cg_mod_ratio >= cg_flight_cheat then -- after takeoff watch for flight, was already takeoff 53.5
  if trim_callout_flight == 4 and touch_down == 0 then -- airborne and ENG rating set for flight 
   FUEL_TRIM_COMMAND = 2
   setDatai(findDataref("Colimata/CON_SYS_TRIM_fuel_request_i"),FUEL_TRIM_COMMAND) -- 1 takeoff, 2 flight, 3 descend, 4 landing
   trim_sequence = 2 -- do it only once
  end
 end
 if trim_sequence == 2 and cg_mod_ratio <= 55.5 then -- going to land, was already flight
  if trim_callout_flight == 0 and touch_down == 0 then -- airborne and ENG rating set for takeoff mostly by lowering gear 
   FUEL_TRIM_COMMAND = 4
   setDatai(findDataref("Colimata/CON_SYS_TRIM_fuel_request_i"),FUEL_TRIM_COMMAND) -- 1 takeoff, 2 flight, 3 descend, 4 landing
   trim_sequence = 3 -- do it only once 
  end
 end
 if trim_sequence == 3 and cg_mod_ratio <= 52.5 then -- landed, was already landing
  if speed <= 100 and touch_down == 1 then -- airborne and ENG rating set for flight 
   FUEL_TRIM_COMMAND = 0
   setDatai(findDataref("Colimata/CON_SYS_TRIM_fuel_request_i"),FUEL_TRIM_COMMAND) -- 1 takeoff, 2 flight, 3 descend, 4 landing
   trim_sequence = 0 -- reset for stopover
  end
 end
 end -- end autotrim switch 
 --!!!!!! end of my fuel system
end
 --!!!!!!
 --..
end -- end battery 
 -- LP valves , this is battery independent, shut off the engine 
 if FUEL_LP_SWITCH1 ~= 0 then
  HP1_VALVE = 0
  setDatai(findDataref("Colimata/CON_RP_ENG_sw_hp_eng_1_i"),HP1_VALVE)
 end
 if FUEL_LP_SWITCH2 ~= 0 then
  HP2_VALVE = 0
  setDatai(findDataref("Colimata/CON_RP_ENG_sw_hp_eng_2_i"),HP2_VALVE)
 end
 if FUEL_LP_SWITCH3 ~= 0 then
  HP3_VALVE = 0
  setDatai(findDataref("Colimata/CON_RP_ENG_sw_hp_eng_3_i"),HP3_VALVE)
 end
 if FUEL_LP_SWITCH4 ~= 0 then
  HP4_VALVE = 0
  setDatai(findDataref("Colimata/CON_RP_ENG_sw_hp_eng_4_i"),HP4_VALVE)
 end
 -- battery off displays
 if battery_on == 0 then
  display_cgacweight = 0
  setDataf(findDataref("Gastonreif/Heritage/display_cgacweight"), display_cgacweight)
  display_cgfuelrem = 0
  setDataf(findDataref("Gastonreif/Heritage/display_cgfuelrem"), display_cgfuelrem)
 end
end	-- end function 

function fuel_gauges()
 if battery_on == 1 then 
  -- CG AFT limit
  CON_CG_AFT_LIMIT_MOD = CON_CG_AFT_LIMIT_POINTER + cg_aft_offset + test_cg_aft_offset -- test and offset driven elswhere 
  setDataf(findDataref("Gastonreif/Heritage/CON_CG_AFT_LIMIT_MOD"), CON_CG_AFT_LIMIT_MOD)
  if fuel_gauges_test_active == 0 then 
  -- CG is at Master 
   if knob_cgcompmain == 0 then
   -- tank1 
   if CON_TANK1 > dial_con_tank1 then
    dial_con_tank1 = dial_con_tank1 + 1
    if dial_con_tank1 >= CON_TANK1 then dial_con_tank1 = CON_TANK1 end 
    setDataf(findDataref("Gastonreif/Heritage/fueltank1"),dial_con_tank1)
   else
    dial_con_tank1 = dial_con_tank1 - 1
    if dial_con_tank1 <= CON_TANK1 then dial_con_tank1 = CON_TANK1 end 
    setDataf(findDataref("Gastonreif/Heritage/fueltank1"),dial_con_tank1)
   end -- end contank1 
   -- tank2 
   if CON_TANK2 > dial_con_tank2 then
    dial_con_tank2 = dial_con_tank2 + 1
    if dial_con_tank2 >= CON_TANK2 then dial_con_tank2 = CON_TANK2 end 
    setDataf(findDataref("Gastonreif/Heritage/fueltank2"),dial_con_tank2)
   else
    dial_con_tank2 = dial_con_tank2 - 1
    if dial_con_tank2 <= CON_TANK2 then dial_con_tank2 = CON_TANK2 end 
    setDataf(findDataref("Gastonreif/Heritage/fueltank2"),dial_con_tank2)
