function engineers_right_panel_lights()
 if battery_on == 1 then
  if AFT_LIGHTS_TEST ~= 2 then --test is not active
  	--overheated hydraulics
   if hyd_green_temperature > 140 then
   	HYD_OHEAT_GREEN_LIGHT = 1
   	setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_G_oh_i"),HYD_OHEAT_GREEN_LIGHT)
   else
   	HYD_OHEAT_GREEN_LIGHT = 0
   	setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_G_oh_i"),HYD_OHEAT_GREEN_LIGHT)
   end
   if hyd_blue_temperature > 140 then
   	HYD_OHEAT_BLUE_LIGHT = 1
   	setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_B_oh_i"),HYD_OHEAT_BLUE_LIGHT)
   else
   	HYD_OHEAT_BLUE_LIGHT = 0
   	setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_B_oh_i"),HYD_OHEAT_BLUE_LIGHT)
   end
   if hyd_yellow_temperature > 140 then
   	HYD_OHEAT_YELLOW_LIGHT = 1
   	setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_Y_oh_i"),HYD_OHEAT_YELLOW_LIGHT)
   else
   	HYD_OHEAT_YELLOW_LIGHT = 0
   	setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_Y_oh_i"),HYD_OHEAT_YELLOW_LIGHT)
   end
  	--low level in hydraulics 
   if dial_green_hyd_qty < 3.5 then 
    HYD_LOW_GREEN_LIGHT = 1
    setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_G_LL_i"),HYD_LOW_GREEN_LIGHT)
   else -- OK	
    HYD_LOW_GREEN_LIGHT = 0
    setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_G_LL_i"),HYD_LOW_GREEN_LIGHT)
   end
   if dial_blue_hyd_qty < 1.75 then 
    HYD_LOW_BLUE_LIGHT = 1
    setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_B_LL_i"),HYD_LOW_BLUE_LIGHT)
   else -- OK	
    HYD_LOW_BLUE_LIGHT = 0
    setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_B_LL_i"),HYD_LOW_BLUE_LIGHT)
   end
   if dial_yellow_hyd_qty < 6.1 then 
    HYD_LOW_YELLOW_LIGHT = 1
    setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_Y_LL_i"),HYD_LOW_YELLOW_LIGHT)
   else -- OK	
    HYD_LOW_YELLOW_LIGHT = 0
    setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_Y_LL_i"),HYD_LOW_YELLOW_LIGHT)
   end
  	--logic from tank, this was previously on fwd section 
   if HYDR_B ~= 0 and WEHAVEPOWER_E == 0 then --no pressure in blue tanks
   	 HYD_LP_BLUE_LIGHT = 1
   	 setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_B_LP_i"),HYD_LP_BLUE_LIGHT)
   	else
     HYD_LP_BLUE_LIGHT = 0
   	 setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_B_LP_i"),HYD_LP_BLUE_LIGHT)
   end
   if HYDR_C ~= 0 and WEHAVEPOWER_E == 0 then --no pressure in green tanks
   	 HYD_LP_GREEN_LIGHT = 1
   	 setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_G_LP_i"),HYD_LP_GREEN_LIGHT)
   	else
     HYD_LP_GREEN_LIGHT = 0
   	 setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_G_LP_i"),HYD_LP_GREEN_LIGHT)
   end
   WEHAVEHYD_SOURCE = WEHAVEPOWER_E + WEHAVEPOWER_B + HYD_AIR_COMP + WEHAVEAIR_G
   --TEST1=WEHAVEHYD_SOURCE
   --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
   --if HYDR_G >= 2 then --no pressure in yellow tanks and no power source available
     if WEHAVEHYD_SOURCE == 0 then
   	  HYD_LP_YELLOW_LIGHT = 1
   	  setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_Y_LP_i"),HYD_LP_YELLOW_LIGHT)
   	 else
      HYD_LP_YELLOW_LIGHT = 0
   	  setDatai(findDataref("Colimata/CON_ENG_lgt_HYD_tank_Y_LP_i"),HYD_LP_YELLOW_LIGHT)
