   if GEN5_ISOL == 1 then --ISOL
    GEN5_FAIL_LIGHT=1
    setDatai(findDataref("Colimata/CON_ENG_lgt_ELEC_EGEN_fail_i"),GEN5_FAIL_LIGHT) 
