function engineers_center_panel_lights()
 if battery_on == 1 then
  -- first everyframe logic for CG and fuel
  --!!! my fuel CG bypass below 
 if FUEL_TRIM_COMMAND == 5 then 
  CON_CG_POINTER_MOD = CON_CG_POINTER_ORIG
  setDataf(findDataref("Gastonreif/Heritage/con_cg_pointer_mod"),CON_CG_POINTER_MOD)
  -- CG light 
  if CON_CG_POINTER_MOD < CON_CG_FWD_LIMIT_POINTER then -- out of limits 
   --CON_CG_ENG_WARNING=1 -- original
   --setDatai(findDataref("Colimata/CON_ENG_lgt_FUEL_cg_warn_i"),CON_CG_ENG_WARNING)
   CON_EG_CGWARNING_MOD = 1 -- mod 
   setDataf(findDataref("Gastonreif/Heritage/con_eg_cgwarning_mod"),CON_EG_CGWARNING_MOD)
  end
  if  CON_CG_POINTER_MOD > CON_CG_AFT_LIMIT_MOD then -- out of limits 
   --CON_CG_ENG_WARNING=1 -- original
   --setDatai(findDataref("Colimata/CON_ENG_lgt_FUEL_cg_warn_i"),CON_CG_ENG_WARNING)
   CON_EG_CGWARNING_MOD = 1 -- mod 
   setDataf(findDataref("Gastonreif/Heritage/con_eg_cgwarning_mod"),CON_EG_CGWARNING_MOD)
  end
  if CON_CG_POINTER_MOD >= CON_CG_FWD_LIMIT_POINTER and CON_CG_POINTER_MOD <= CON_CG_AFT_LIMIT_MOD then -- within limits
   --CON_CG_ENG_WARNING=0
   --setDatai(findDataref("Colimata/CON_ENG_lgt_FUEL_cg_warn_i"),CON_CG_ENG_WARNING)
   CON_EG_CGWARNING_MOD = 0 -- mod 
   setDataf(findDataref("Gastonreif/Heritage/con_eg_cgwarning_mod"),CON_EG_CGWARNING_MOD)
  end
 else 
  --!!! my fuel CG below 
  if cg_mod_ratio >= CON_CG_POINTER_MOD then -- cg is increasing 
   CON_CG_POINTER_MOD=CON_CG_POINTER_MOD+0.1
   if CON_CG_POINTER_MOD >= cg_mod_ratio then
   	CON_CG_POINTER_MOD = cg_mod_ratio
   end
   setDataf(findDataref("Gastonreif/Heritage/con_cg_pointer_mod"),CON_CG_POINTER_MOD)
  else -- cg is decreasing 
   CON_CG_POINTER_MOD=CON_CG_POINTER_MOD-0.1
   if CON_CG_POINTER_MOD <= cg_mod_ratio then
   	CON_CG_POINTER_MOD = cg_mod_ratio
   end
   setDataf(findDataref("Gastonreif/Heritage/con_cg_pointer_mod"),CON_CG_POINTER_MOD)
  end
  -- CG light 
  if CON_CG_POINTER_MOD < CON_CG_FWD_LIMIT_POINTER then -- out of limits 
   --CON_CG_ENG_WARNING=1 -- original
   --setDatai(findDataref("Colimata/CON_ENG_lgt_FUEL_cg_warn_i"),CON_CG_ENG_WARNING)
   CON_EG_CGWARNING_MOD = 1 -- mod 
   setDataf(findDataref("Gastonreif/Heritage/con_eg_cgwarning_mod"),CON_EG_CGWARNING_MOD)
  end
  if  CON_CG_POINTER_MOD > CON_CG_AFT_LIMIT_MOD then -- out of limits 
   --CON_CG_ENG_WARNING=1 -- original
