   CON_EG_CGWARNING_MOD = 0 -- mod 
   setDataf(findDataref("Gastonreif/Heritage/con_eg_cgwarning_mod"),CON_EG_CGWARNING_MOD)
  end
  --!!! my fuel CG below end 
 end
  -- end cg and fuel 
  if CTR_LIGHTS_TEST ~= 2 then --test is not active
   --fuel exchangers
   if fueltemp1_agregated >= 150 then FUEL1_HIGH_TEMP = 1 else FUEL1_HIGH_TEMP = 0 end
   if fueltemp2_agregated >= 150 then FUEL2_HIGH_TEMP = 1 else FUEL2_HIGH_TEMP = 0 end
   if fueltemp3_agregated >= 150 then FUEL3_HIGH_TEMP = 1 else FUEL3_HIGH_TEMP = 0 end
   if fueltemp4_agregated >= 150 then FUEL4_HIGH_TEMP = 1 else FUEL4_HIGH_TEMP = 0 end
   if fuel_exchanger1 >= 120 then FUEL1_EXCH_HIGH_TEMP = 1 else FUEL1_EXCH_HIGH_TEMP = 0 end -- ..add here other below
   if fuel_exchanger2 >= 120 then FUEL2_EXCH_HIGH_TEMP = 1 else FUEL2_EXCH_HIGH_TEMP = 0 end
   if fuel_exchanger3 >= 120 then FUEL3_EXCH_HIGH_TEMP = 1 else FUEL3_EXCH_HIGH_TEMP = 0 end
   if fuel_exchanger4 >= 120 then FUEL4_EXCH_HIGH_TEMP = 1 else FUEL4_EXCH_HIGH_TEMP = 0 end
