--
function lights_on() -- links Concorde taxi and landing lights to x-plane lights datarefs
--taxi light
if CON_TAXI_LIGHT2 == 1 or CON_TAXI_LIGHT1 == 1 then 
 k = k + 1
 if k <= 0 then k = 0 end 
 if k >= 50 then
  k = 50
  --Q = 0 
  --l = 0
  --R = 0
 end 
  landing_lights_fade2 = 0 + k/50
  if landing_lights_fade2 <= 0 then landing_lights_fade2 = 0 end 
  if landing_lights_fade2 >= 0.9 then
   landing_lights_fade2 = 1
   taxi_lights = 1
  end
 else 
  Q = Q + 1
  if Q <= 0 then Q = 0 end
  if Q >= 50 then
   Q = 50
  --k = 0
  --l = 0
 -- R = 0
  end  
  landing_lights_fade2 = 1 - Q/50
  if landing_lights_fade2 >= 1 then landing_lights_fade2 = 1 end 
  if landing_lights_fade2 <= 0.1 then
   landing_lights_fade2 = 0
   taxi_lights = 0
  end
end
--main landing light1
if CON_LAND_LIGHT2 == 1 or CON_LAND_LIGHT1 == 1 then
 l = l + 1
 if l <= 0 then l = 0 end 
 if l >= 50 then
  l = 50
  --Q = 0 
  --l = 0
  --R = 0
 end 
 landing_lights_fade1 = 0 + l/50
 if landing_lights_fade1 <= 0 then landing_lights_fade1 = 0 end
 if landing_lights_fade1 >= 0.9 then 
 landing_lights_fade1 = 1
 landing_lights = 1 
 end
else
 R = R + 1
 if R <= 0 then R = 0 end
 if R >= 50 then
   R = 50
  --k = 0
  --l = 0
 -- R = 0
 end  
 landing_lights_fade1 = 1 - R/50
 if landing_lights_fade1 >= 1 then landing_lights_fade1 = 1 end
 if landing_lights_fade1 <= 0.1 then
  landing_lights_fade1 = 0
  landing_lights = 0
 end
end
 if strobe_lights == 1 then beacon_lights = 1 else beacon_lights = 0 end
 -- Exterior lights
 --frame rate
 match_frame_rate = 1/simulator_framerate_period
 if ROOF_SW_ANTICOLL == 1 and EMERG_EVAC_SWITCH == 1 then -- strobes are on and override in wait_for_sim_loaded
   -- standing or without additional lights 
   if CON_TAXI_LIGHT2 == 0 and touch_down == 1  then -- only at ground 
  --if CON_TAXI_LIGHT2 == 2 and touch_down == 1  then -- only for debug
   	flash_mode_strobes = 0 -- used elsewhere 
   	-- red strobes 
   	if red_flash_counted <= 12 then -- red flash 12 times 
   	 light_strobe_white = 0 
     counter_light_strobe_red = counter_light_strobe_red + 1
     if counter_light_strobe_red >= match_frame_rate then -- flash after some miliseconds
   	  light_strobe_red = 1 -- full flash 
   	  -- counter elswehere (red_flash_counted)
   	  --reset 
   	  counter_light_strobe_red = 0
   	 else
   	  light_strobe_red = 0 -- no flash 
     end
    else
    -- here comes white flashes 
    -- after 12 reds 
     light_strobe_red = 0
     if white_flash_counted <= 4 then -- white flash 4 times
      counter_light_strobe_white = counter_light_strobe_white + 1
      if counter_light_strobe_white >= match_frame_rate then -- flash after some miliseconds
   	   light_strobe_white = 1 -- full flash 
   	   -- counter elswehere (white_flash_counted)
   	   --reset 
   	   counter_light_strobe_white = 0
   	  else
   	   light_strobe_white = 0 -- no flash 
      end
     end
    end
   end
   -- during taxi 
   if CON_TAXI_LIGHT2 == 1 and touch_down == 1  then -- only taxi light at ground 
   	flash_mode_strobes = 1 -- used elswhere 
   	-- red strobes 
   	if red_flash_counted <= 4 then -- red flash 4 times 
   	 light_strobe_white = 0 
     counter_light_strobe_red = counter_light_strobe_red + 1
     if counter_light_strobe_red >= match_frame_rate then -- flash after some miliseconds
   	  light_strobe_red = 1 -- full flash 
   	  -- counter elswehere (red_flash_counted)
   	  --reset 
   	  counter_light_strobe_red = 0
   	 else
   	  light_strobe_red = 0 -- no flash 
     end
    else
    -- here comes white flashes 
    -- after 4 reds 
     light_strobe_red = 0
     if white_flash_counted <= 4 then -- white flash 4 times
      counter_light_strobe_white = counter_light_strobe_white + 1
      if counter_light_strobe_white >= match_frame_rate then -- flash after some miliseconds
   	   light_strobe_white = 1 -- full flash 
   	   -- counter elswehere (white_flash_counted)
   	   --reset 
      counter_light_strobe_white = 0
   	  else
   	   light_strobe_white = 0 -- no flash 
      end
     end
    end
   end
   -- airborne 
   --if touch_down == 0  then -- only airborne
   ----if touch_down == 1 and CON_TAXI_LIGHT1 == 1 then -- only for debug
   --	flash_mode_strobes = 2 -- used elsewhere 
   --	-- red strobes 
   --	if red_flash_counted <= 1 then -- red flash 1 times 
   --	 light_strobe_white = 0
   --  counter_light_strobe_red = counter_light_strobe_red + 1
   --  if counter_light_strobe_red >= match_frame_rate then -- flash after some miliseconds
   --	  light_strobe_red = 1 -- full flash 
   --	  -- counter elswehere (red_flash_counted)
   --	  --reset 
   --	  counter_light_strobe_red = 0
   --	 else
   --	  light_strobe_red = 0 -- no flash 
   --  end
   -- else
   -- -- here comes white flashes 
   -- -- after 1 red 
   --  light_strobe_red = 0
   --  if white_flash_counted <= 1 then -- white flash 1 times
   --   counter_light_strobe_white = counter_light_strobe_white + 1
   --   if counter_light_strobe_white >= match_frame_rate then -- flash after some miliseconds
   --	   light_strobe_white = 1 -- full flash 
   --	   -- counter elswehere (white_flash_counted)
   --	   --reset 
   --	   counter_light_strobe_white = 0
   --	  else
   --	   light_strobe_white = 0 -- no flash 
   --   end
   --  end
   -- end
   --end
   -- end of V1 buggy
   -- V2, opossite function, here shutting off the flash 
   -- airborne 
   if touch_down == 0 then -- only airborne
   --if touch_down == 1 and CON_TAXI_LIGHT1 == 1 then -- only for debug
    flash_mode_strobes = 2
	if LIGHT_STROBE_FLASH == 1 then
	 -- red
	 if red_flash_counted == 1 then 
	  counter_light_strobe_red = counter_light_strobe_red - match_frame_rate
	  if counter_light_strobe_red <= 0 then
	   light_strobe_red = 0
	   counter_light_strobe_red = 0
	   LIGHT_STROBE_FLASH=0 -- exit function 
       setDatai(findDataref("sim/flightmodel2/lights/strobe_flash_now"),LIGHT_STROBE_FLASH)
	  end
	 end
	 -- white 
	 if white_flash_counted == 1 then 
	  counter_light_strobe_white = counter_light_strobe_white - match_frame_rate
	  if counter_light_strobe_white <= 0 then
	   light_strobe_white = 0
	   counter_light_strobe_white = 0
	   LIGHT_STROBE_FLASH=0 -- exit function 
       setDatai(findDataref("sim/flightmodel2/lights/strobe_flash_now"),LIGHT_STROBE_FLASH)
	  end
	 end
	end
   end 
   -- end of modes 
   -- duration of flashing strobes
   --heritage_debug6=counter_light_strobe_red
   --setDataf(findDataref("Gastonreif/Heritage/debug6"),heritage_debug6)
   --heritage_debug7=counter_light_strobe_white
   --setDataf(findDataref("Gastonreif/Heritage/debug7"),heritage_debug7)
 end
end

