function total_temp() --was disabled, finished by Colimata from V1.1
   ------kts_speed_last = kts_speed -- save current speed as last speed
   ------delta_speed = kts_speed - kts_speed_last
----if kts_speed <= 500 then Q = 1 --else 
  
  ------Q = (kts_speed_last+k)/kts_speed 
  
  ------k = Q+1
 ------ end
------Total = Total_C*Q
 -- v200 affected by ISA, this function is critical on priority, do not disable it  
 Total = TAT -- feed from x-plane total temperature
 if altitude >= 18000 then
  if CON_ISA_SIGN == 0 then -- 0 means +
   CON_ISA_adjusting = CON_ISA_adjusting + 0.0001
   if CON_ISA_adjusting >= CON_ISA then CON_ISA_adjusting = CON_ISA end --- slowly match isa difference
   Total_C = TAT + CON_ISA_adjusting -- value for broken dislay
   Total = TAT + CON_ISA_adjusting -- value for logic 
  else
   CON_ISA_adjusting = CON_ISA_adjusting + 0.0001
   if CON_ISA_adjusting >= CON_ISA then CON_ISA_adjusting = CON_ISA end
   Total_C = TAT - CON_ISA_adjusting
   Total = TAT - CON_ISA_adjusting
  end 
 else -- below 18.000ft
  Total_C = TAT 
  Total = TAT -- value for logic
 end 
 if Total_C <= 0 then 
  Total_C = -999 - Total
 --if Total_C < 0 then 
  Total_C_plus = 1 -- 1 is -
 else
  Total_C_plus = 0 -- 0 is +
 end
 CON_TAT = Total_C -- set the counter on the centre console 
 setDataf(findDataref("Gastonreif/Heritage/mytat"),CON_TAT)
 CON_TAT_SIGN = Total_C_plus -- set the counter on the centre console 
 setDataf(findDataref("Gastonreif/Heritage/mytat_sign"),CON_TAT_SIGN)
 --if Total_C >= 0 then Total_C_plus = 0 end --else  
   --Total_C_plus = 1 --this could be bug, delete that if completely
   ----if Total_C == 999 then Total_C = 1 end
----   ----if Total == 999 then Total = 1
 --end
-- SAT generator 
-- generate sign 
-- ISA difference check
 if delay_isa_counter == 0 then 
  current_isa_stored = previous_isa_stored -- store last value 
 end 
 delay_isa_counter = delay_isa_counter + 1 -- count once 
 if delay_isa_counter == 5 then -- counter finished 
  previous_isa_stored = CON_ISA
  --delay_isa_counter = 0 -- reset elswhere
 end
 if previous_isa_stored ~= current_isa_stored then
  isa_was_changed = 1
 else 
  isa_was_changed = 0
 end 
 -- OAT adjusted by ISA
 adjusted_OAT = CON_ISA -- feed from x-plane outside temperature
 if altitude >= 18000 then
  if CON_ISA_SIGN == 0 then -- 0 means +
   CON_OAT_adjusting = CON_OAT_adjusting + 0.0001
   if CON_OAT_adjusting >= adjusted_OAT then CON_OAT_adjusting = adjusted_OAT end --- slowly match isa difference
   my_oat = OAT + CON_OAT_adjusting -- OAT adjusted too 
   my_oat_dial = OAT + CON_OAT_adjusting -- only value, write to gauge later
  else
   CON_OAT_adjusting = CON_OAT_adjusting + 0.0001
   if CON_OAT_adjusting >= adjusted_OAT then CON_OAT_adjusting = adjusted_OAT end --- slowly match isa difference
   my_oat = OAT - CON_OAT_adjusting 
   my_oat_dial = OAT - CON_OAT_adjusting
  end 
 else -- below 18.000ft
  my_oat = OAT -- value for logic 
  my_oat_dial = OAT -- only value, write to gauge below
 end 
 -- sign oat, split value from sign for gauges  
 --if my_oat_dial <= 0 then
 if my_oat <= 0 then
  my_oat_sign = 1 -- 1 is -
  setDatai(findDataref("Gastonreif/Heritage/my_oat_sign"),my_oat_sign)
  --my_oat_dial = -99 - my_oat -- drive gauge with adjusted drum 
  my_oat_dial = - my_oat -- try this one if previous dont work 
  setDataf(findDataref("Gastonreif/Heritage/my_oat_dial"),my_oat_dial)
 else  
  my_oat_sign = 0 -- 0 is + 
  setDatai(findDataref("Gastonreif/Heritage/my_oat_sign"),my_oat_sign)
  my_oat_dial = my_oat -- drive gauge 
  setDataf(findDataref("Gastonreif/Heritage/my_oat_dial"),my_oat_dial)
 end
 -- debug
 --TEST1 = adjusted_OAT --debug
 --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
 --TEST2 = my_oat --debug
 --setDataf(findDataref("Colimata/CON_TESTVALUE_2_f"),TEST2)
 --TEST3 = CON_OAT_adjusting --debug
 --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
end -- end function 
----end

