  ---AP alert during LAND
  if AUTOPILOT == 0 and AP1_WAS_ON == 1 then
   --if timer_finished == 1 then --play only once after first flash of AP warning
   if timer_was_one == 1 then --play only once after first flash of AP warning
      pause_sound(lastsound3)
      play_sound(C_CAVALRY)
      lastsound3=C_CAVALRY
	  timer_was_one = 0 --reset
   end
  end
  ---overspeed
  if VMO_EXCEEDED == 2 then
    pause_sound(lastsound3)
    play_sound(C_WARBLE)
    lastsound3=C_WARBLE
  end
  -- engine fire
  if WARN_CANCEL == 0 then
  if FIRE_HANDLE_1_LIGHT == 1 then
   pause_sound(lastsound3)
   play_sound(C_BELL)
   lastsound3=C_BELL
  end
  if FIRE_HANDLE_2_LIGHT == 1 then
   pause_sound(lastsound3)
   play_sound(C_BELL)
   lastsound3=C_BELL
  end
  if FIRE_HANDLE_3_LIGHT == 1 then
   pause_sound(lastsound3)
   play_sound(C_BELL)
   lastsound3=C_BELL
  end
  if FIRE_HANDLE_4_LIGHT == 1 then
   pause_sound(lastsound3)
   play_sound(C_BELL)
   lastsound3=C_BELL
  end
  end
--TEST1 = timer_finished4 --debug dataref
--setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
--TEST2 = WARN_CANCELED --debug dataref
--setDataf(findDataref("Colimata/CON_TESTVALUE_2_f"),TEST2)
-- new air warning from FANS
   ----AIR horn--
   timer_finished7 = timer_finished7 + 1
   if timer_finished7 >= 5 then
	timer_finished7 = 0 --count from 0 again
	timer_constant7 = 1 --5 seconds reached 
   else
	timer_constant7 = 0
   end
  --if airringed == 0 then
   NOAIRFLOW2 = FWD2_BAY_COOL_LIGHT + FWD1_BAY_COOL_LIGHT + REAR_BAY_COOL_LIGHT
   --if NOAIRFLOW2 >= 1 then 
    if WARN_CANCEL == 0 then --check and play until cancelled
     if timer_constant7 == 1 and NOAIRFLOW2 >= 1 then
     pause_sound(lastsound4)
     play_sound(C_HORN)
     lastsound4=C_HORN
     --played_trim = 0  -- dont play now 
     end
    end
  --end
 
 --end
 -- --END of new air fans horn--
  --marker sounds
  if touch_down == 0 and MARKER_TEST == 0 then --airborne no test
   if INNER_ON == 1 then
	  play_sound(audio_inner)
   end
   if MIDDLE_ON == 1 then
	  play_sound(audio_middle)
   end
   if OUTER_ON == 1 then
	  play_sound(audio_outer)
   end
  end
   --test is on
  if MARKER_TEST == 1 then
    --4 sec timer every sound has one second
       timer_finished5 = timer_finished5 + 1 --count every 2 seconds/positive pings
	   if timer_finished5 >= 5 then --3 sec passed
	      --timer_finished5 = 0 --count from 0 again
		  timer_constant5 = 1 --4 seconds reached 
	   else
	      timer_constant5 = 0 --not reached
	   end
	 if timer_finished5 < 2 then --first play
	   let_sound_loop(audio_outer, true)
	   pause_sound(lastsound5)
	   play_sound(audio_outer)
	   lastsound5=audio_outer
	 end
	 if timer_finished5 >= 2 and timer_finished5 < 3 then --second play
	   let_sound_loop(audio_middle, true)
	   pause_sound(lastsound5)
	   play_sound(audio_middle)
	   lastsound5=audio_middle
	 end
	 if timer_finished5 >= 3 and timer_finished5 < 4 then --last play
	   let_sound_loop(audio_inner, true)
	   pause_sound(lastsound5)
	   play_sound(audio_inner)
	   lastsound5=audio_inner
	   --timer_constant6 = timer_constant6 + 1 --last sound played
	 end
	 --if timer_constant6 > 1 then -- dont play those sounds until we have new test
	  -- pause_sound(lastsound5)
	  -- pause_sound(audio_outer)
	  -- pause_sound(audio_middle)
	  --pause_sound(audio_inner)
	  -- timer_finished5 = 5 -- playing sequence ended
	 --end
	 --if timer_finished5 >= 4 then --continuous play silence
	   --let_sound_loop(DUMMY_2, true)
	   --pause_sound(lastsound5)
	   --play_sound(DUMMY_2)
	   --lastsound5=DUMMY_2
	  -- stop_sound()
	 --end
  else -- reset the loop sounds for normal function
   let_sound_loop(audio_outer, false)
   let_sound_loop(audio_middle, false)
   let_sound_loop(audio_inner, false)
   --let_sound_loop(DUMMY_2, false)
   --timer_constant6 = 0
   timer_finished5 = 0
  end
  --end marker sounds
	
end
-- end MWS sounds
end --end my sounds protection
end



function heritage_sounds() --used from my tunable ATC for concorde atc annoucements
if VS_ACTUAL >= 2000 then
ASCEND = true
DESCEND = false
elseif VS_ACTUAL <= -2000 then
ASCEND = false
DESCEND = true
end
--if os.clock() > sim_time_run + 20 then
if os.clock() > sim_time_run + 1 then
--geardown = GEAR_DOWN
--play clearance sound
--VOLUME_1 = VOL_COPVHF1
VOLUME_1 = VOL_PINAV1/10
if VOLUME_1 <= 0.05 then VOLUME_1 = 0.1 end
if VOLUME_1 >= 0.95 then VOLUME_1 = 0.9 end
set_sound_gain(atc_departure, VOLUME_1);
--if COPVHF1 == 1 then pause_sound(lastsound2); play_sound(atc_departure); lastsound2=atc_departure; else pause_sound(atc_departure) end --COPVHF1 = 0;
--if played_1 == 0 and battery_on ==1 then 
if played_1 == 0 and PILOTVOICE == 1 then 
 pause_sound(lastsound2)
 play_sound(atc_departure)
 lastsound2=atc_departure
 played_1 = 1 
end
--play takeoff sound
VOLUME_2 = VOL_COPVHF2/10
if VOLUME_2 <= 0.05 then VOLUME_2 = 0.1 end
if VOLUME_2 >= 0.95 then VOLUME_2 = 0.9 end
set_sound_gain(atc_takeoff, VOLUME_2);
--if COPVHF2 == 1 then pause_sound(lastsound2); play_sound(atc_takeoff); lastsound2=atc_takeoff; else pause_sound(atc_takeoff) end

if speed >= 5 then 
 if played_2 == 0 and TO_MONITOR == 1 then
  pause_sound(lastsound2)
  play_sound(atc_takeoff)
  lastsound2=atc_takeoff
  played_2 = 1 
 end
end
--play after takeoff sound
VOLUME_3 = VOL_COPHF1/10
if VOLUME_3 <= 0.05 then VOLUME_3 = 0.1 end
if VOLUME_3 >= 0.95 then VOLUME_3 = 0.9 end
set_sound_gain(atc_after_takeoff, VOLUME_3);
--if COPHF1 == 1 then pause_sound(lastsound2); play_sound(atc_after_takeoff); lastsound2=atc_after_takeoff; else pause_sound(atc_after_takeoff) end
--if played_3 == 0 and speed >= 220 and CON_VVI_ACT >= 2000 then 
if played_3 == 0 and GEAR_DOWN == 0 and ASCEND == true then 
 pause_sound(lastsound2)
 play_sound(atc_after_takeoff)
 lastsound2=atc_after_takeoff
 played_3 = 1 
end
--play climb sound
VOLUME_4 = VOL_COPHF2/10
if VOLUME_4 <= 0.05 then VOLUME_4 = 0.1 end
if VOLUME_4 >= 0.95 then VOLUME_4 = 0.9 end
set_sound_gain(atc_climb, VOLUME_4);
--if COPHF2 == 1 then pause_sound(lastsound2); play_sound(atc_climb); lastsound2=atc_climb; else pause_sound(atc_climb) end
if played_4 == 0 and played_3 == 1 and altitude >= 13000 and CON_VVI_ACT >= 1500 then 
 pause_sound(lastsound2)
 play_sound(atc_climb)
 lastsound2=atc_climb
 played_4 = 1 
end
--play descent sound
VOLUME_5 = VOL_COPADF1/10
if VOLUME_5 <= 0.05 then VOLUME_5 = 0.1 end
if VOLUME_5 >= 0.95 then VOLUME_5 = 0.9 end
set_sound_gain(atc_descent, VOLUME_5);
if played_5 == 0 and DESCEND == true and altitude >= 39000 then 
 pause_sound(lastsound2)
 play_sound(atc_descent)
 lastsound2=atc_descent
 played_5 = 1 
end
--play approach sound
VOLUME_6 = VOL_COPADF2/10
if VOLUME_6 <= 0.05 then VOLUME_6 = 0.1 end
if VOLUME_6 >= 0.95 then VOLUME_6 = 0.9 end
set_sound_gain(atc_approach, VOLUME_6);
if played_6 == 0 and DESCEND == true and altitude >= 10000 and altitude <= 11000 then 
 pause_sound(lastsound2)
 play_sound(atc_approach)
 lastsound2=atc_approach
 played_6 = 1 
end
--play landing sound
VOLUME_7 = VOL_COPNAV1/10
if VOLUME_7 <= 0.05 then VOLUME_7 = 0.1 end
if VOLUME_7 >= 0.95 then VOLUME_7 = 0.9 end
set_sound_gain(atc_landing, VOLUME_7);
--if played_7 == 0 and played_6 == 1 and DESCEND == true and geardown == 1 and altitude <= 13000 and speed >= 170 then 
if played_7 == 0 and played_6 == 1 and GEAR_DOWN == 1 then --and DESCEND == true and and altitude <= 13000 and speed >= 170 then 
 pause_sound(lastsound2)
 play_sound(atc_landing)
 lastsound2=atc_landing
 played_7 = 1 
end
--play heritage sound
VOLUME_8 = VOL_COPNAV2/10
if VOLUME_8 <= 0.05 then VOLUME_8 = 0.1 end
if VOLUME_8 >= 0.95 then VOLUME_8 = 0.9 end
set_sound_gain(atc_heritage, VOLUME_8);
if played_8 == 0 and PILOTVOICE2 == 1 then 
 pause_sound(lastsound2)
 play_sound(atc_heritage)
 lastsound2=atc_heritage
 played_8 = 1 
end
--set gain for marker
VOLUME_10 = VOL_MKR1/10
if VOLUME_10 <= 0.05 then VOLUME_10 = 0.1 end
if VOLUME_10 >= 0.95 then VOLUME_10 = 0.9 end
set_sound_gain(audio_inner, VOLUME_10);
set_sound_gain(audio_middle, VOLUME_10);
set_sound_gain(audio_outer, VOLUME_10);

end
end


