function enhanced_autopilot_modes()
--TURB mode for 1.20 disabled
--if TURB_ON == 1 then
 --TURB_LIGHT = 1
 --TURB_WAS_ON = 1
 --setDatai(findDataref("Colimata/CON_AP_button_turbulence_lgt_i"),TURB_LIGHT)
 --HDG_HOLD = 1
 --setDatai(findDataref("Colimata/CON_AP_button_hdg_hold_i"),HDG_HOLD) 
 --HDG_HOLD_LIGHT = 0
 --setDatai(findDataref("Colimata/CON_AP_button_hdg_hold_lgt_i"),HDG_HOLD_LIGHT)
 --CON_PITCH = 1 --apply the pitch hold
 ----CON_PITCH = PITCH
 --setDatai(findDataref("Colimata/CON_AP_button_pitch_hold_i"),CON_PITCH)
 --CON_PITCH_LIGHT = 0
 --setDatai(findDataref("Colimata/CON_AP_button_pitch_hold_lgt_i"),CON_PITCH_LIGHT)
--end
----if TURB_ON == 0 and TURB_WAS_ON == 1 then --protection swicth of the 
--BACK beam
if AUTOPILOT == 1 and CON_FD1 == 1 then
  if BACK_BEAM_ON == 1 and touch_down == 0 then 
     --BACK_BEAM_WAS_ON = 1
	 BACK_BEAM_LIGHT = 1
	 setDatai(findDataref("Colimata/CON_AP_button_back_beam_lgt_i"),BACK_BEAM_LIGHT)
     ---bug resolver
	 OVERRIDE_GPS_PLEASE = 1
	 setDatai(findDataref("sim/operation/override/override_gps"),OVERRIDE_GPS_PLEASE) 
	 GPS_TO_HSI = 1
	 setDatai(findDataref("sim/cockpit/radios/gps_has_glideslope"),GPS_TO_HSI) 
	 --NAV2GPS feeder
	 GPS_HDEF_DOT = NAV1_HDEV_DOT
	 setDataf(findDataref("sim/cockpit/radios/gps_hdef_dot"),GPS_HDEF_DOT) 
	 GPS_VDEF_DOT = NAV1_VDEV_DOT
	 setDataf(findDataref("sim/cockpit/radios/gps_vdef_dot"),GPS_VDEF_DOT) 
	 GPS_DME_DIST = NAV1_DME_DIST_M
	 setDataf(findDataref("sim/cockpit/radios/gps_dme_dist_m nm"),GPS_DME_DIST)
	 GPS_COURSE_DEGTM = NAV1_COURSE_DEGM
	 setDataf(findDataref("sim/cockpit/radios/gps_course_degtm"),GPS_COURSE_DEGTM) 
	 GPS_SLOPE_DEGT = NAV1_SLOPE_DEGT
	 setDataf(findDataref("sim/cockpit/radios/gps_slope_degt"),GPS_SLOPE_DEGT) 
	 --bug resolver end
    if NAV1_COURSE_DEGM == 0 then 
	 BACK_BEAM_ON = 0 
	 setDatai(findDataref("Colimata/CON_AP_button_back_beam_i"),BACK_BEAM_ON)
	end --protection for HNAV
	--maybe no needed not used now
    ADJUST_COURSE = NAV1_COURSE_DEGM + 180
    if ADJUST_COURSE >= 360 then 
      ADJUST_COURSE = ADJUST_COURSE - 360
    end
	if BACK_BEAM_WAS_ON == 0 then
     OVERRIDE_AP = 1
	 setDatai(findDataref("sim/operation/override/override_autopilot"),OVERRIDE_AP)
	 --AUTOPILOT_LR = 128 --vertical mode pitch react to speed
	 --setDatai(findDataref("sim/cockpit/autopilot/autopilot_state"),AUTOPILOT_LR)
	 AUTOPILOT_LR = 512 --engage HNAV , fly the heading from nav1
     setDatai(findDataref("sim/cockpit/autopilot/autopilot_state"),AUTOPILOT_LR)	
	 BACK_BEAM_WAS_ON = 1
	 --TEST1 = BACK_BEAM_WAS_ON --debug dataref
	 --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
	end
  end
  if BACK_BEAM_WAS_ON == 1 and BACK_BEAM_ON == 0 then --protection, disable overrides
   OVERRIDE_GPS_PLEASE = 0
   setDatai(findDataref("sim/operation/override/override_gps"),OVERRIDE_GPS_PLEASE) 
   AUTOPILOT_LR = 0 --default state of AP
   setDatai(findDataref("sim/cockpit/autopilot/autopilot_state"),AUTOPILOT_LR)
   OVERRIDE_AP = 0
   setDatai(findDataref("sim/operation/override/override_autopilot"),OVERRIDE_AP)
   BACK_BEAM_WAS_ON = 0 --do only once
   --TEST1 = BACK_BEAM_WAS_ON --debug dataref
   --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
  end -- end protection overrides
end
--GO Around
--Goaround (only light)is no AT on, full throttles and Glide or Land active.
--It switch the pitch hold of 15°, disengage by HDG mode or AP off.
--make this alone, not inside glideslope
--if altitude <= 1000 and HDG_HOLD ~= 1 then--limiter
if altitude <= 1000 and IP_LIGHTS_TEST == 0 then --limiter, HDG hold removed, we need it because of wings level bad x-plane stability
   	HDG_HOLD_LIGHT = 0
	setDatai(findDataref("Colimata/CON_AP_button_hdg_hold_lgt_i"),HDG_HOLD_LIGHT)
	--if GOTTEN_PITCH == 1 and touch_down ~= 1 then
	-- GO_AROUND_LIGHT = 1
    -- setDatai(findDataref("Colimata/CON_AP_button_go_around_lgt_i"),GO_AROUND_LIGHT)
	--end
--Colimata Glideslope
 if GLIDESLOPE_WAS_ON_BUT_IS_NOT_NOW == 1 or GLIDESLOPE_WAS_ON == 1 then --prevent quick end
 GLIDESLOPE_WAS_ON_BUT_IS_NOT_NOW = 1 -- continue going around, maybe lateral ap mode needed
 --if GO_AROUND_PITCH_HIT == 1 then --stay lit until 1000ft
  -- if GO_AROUND_LIGHT ~= 1 then
  --  GO_AROUND_LIGHT = 1
  --  setDatai(findDataref("Colimata/CON_AP_button_go_around_lgt_i"),GO_AROUND_LIGHT)
  -- end
 --end
 
  if THRO_PCT > 99 and touch_down ~= 1 then --if throttles will be 100% and then set back go around is disabled
  if REVERSERS_IDLE == 0 then -- protection/bug fixer when users hitting revmax before touchdown
   GO_AROUND_LIGHT = 1
   setDatai(findDataref("Colimata/CON_AP_button_go_around_lgt_i"),GO_AROUND_LIGHT)
   --disable modes
   GLIDESLOPE_ACTIVE = 0
   setDatai(findDataref("Colimata/CON_AP_button_glide_i"),GLIDESLOPE_ACTIVE)
   GLIDESLOPE_ACTIVE_LIGHT = 0
   setDatai(findDataref("Colimata/CON_AP_button_glide_lgt_i"),GLIDESLOPE_ACTIVE_LIGHT)
   --AUTOLAND_ON = 0 DISABLED FOR MY AUTOLAND
   --setDatai(findDataref("Colimata/CON_AP_button_land_i"),AUTOLAND_ON) DISABLED FOR MY AUTOLAND
   --get_pitch
   if GOTTEN_PITCH == 0 then --only once
    PITCH_ACTUAL = PITCH_AP
    GOTTEN_PITCH = 1
	OVERRIDE_PITCH = 1
    setDatai(findDataref("sim/operation/override/override_joystick_pitch"),OVERRIDE_PITCH)
   end 
   if PITCH_WAS_OVERIDE == 0 then--only once
    HDG_HOLD_ON = 1
	setDatai(findDataref("Colimata/CON_AP_button_hdg_hold_i"),HDG_HOLD_ON)
    HDG_HOLD_LIGHT = 0
	setDatai(findDataref("Colimata/CON_AP_button_hdg_hold_lgt_i"),HDG_HOLD_LIGHT)
    PITCH_WAS_OVERIDE = 1
   end
   if GO_AROUND_PITCH_HIT == 0 then --do until max pitch achieved
   PITCH_AP=PITCH_AP + 0.005
   --end
    if PITCH_AP >= 0.2 then
    --PITCH_AP = PITCH_ACTUAL 
	PITCH_AP = 0.2
	GO_AROUND_PITCH_HIT = 1
    end --3000 should be pitch 15°
   end
   --OVERRIDE_PITCH = 0
   --setDatai(findDataref("sim/operation/override/override_joystick_pitch"),OVERRIDE_PITCH)
   --TEST1 = OVERRIDE_PITCH --debug dataref
   --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
   --TEST3 = GO_AROUND_PITCH_HIT --debug dataref
   --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
  end -- end bugfixer
  end -- end thrust condition 
 end--end glideslope was on
--end of Colimata Glideslope

 else --above 1000 ft
 if GO_AROUND_PITCH_HIT == 1 then --do only once
   GO_AROUND_LIGHT = 0
   setDatai(findDataref("Colimata/CON_AP_button_go_around_lgt_i"),GO_AROUND_LIGHT)
   PITCH_AP = 0
   OVERRIDE_PITCH = 0
   setDatai(findDataref("sim/operation/override/override_joystick_pitch"),OVERRIDE_PITCH)
   GO_AROUND_PITCH_HIT = 0
   --TEST3 = GO_AROUND_PITCH_HIT --debug dataref
   --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
 end
 --OVERRIDE_PITCH = 0
 --setDatai(findDataref("sim/operation/override/override_joystick_pitch"),OVERRIDE_PITCH)
 --TEST1 = OVERRIDE_PITCH --debug dataref
 --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
end -- end go-around 


end

-- alt hold--
function vertical_speed_hold() --V/S mode and ALT HOLD mode
 ----sim/cockpit2/gauges/indicators/altitude_ft_pilot (ALT)
 ----sim/cockpit/autopilot/vertical_velocity (VS_ACTUAL)
 --if CON_ALT_HOLD_VALUE > altitude then -- compare desired and current altitudes and set logical ascend or descend
 -- DESCEND = false
 -- ASCEND = true
 -- else 
 -- DESCEND = true
 -- ASCEND = false
 --end
 --LAST CHANGED if GLIDESLOPE_ACTIVE == 0 and CON_FD1 == 1 then 
 ----sim/flightmodel/position/vh_ind_fpm NOT USED
 --if CON_VS_BUTTON == 1 and AUTOPILOT_ON == 1 then 
 if CON_VS_BUTTON == 1 and AUTOPILOT == 1 then 
   CON_PITCH = 0  --disarm pitch mode because we are now in V/S mode
   setDatai(findDataref("Colimata/CON_AP_button_pitch_hold_i"),CON_PITCH)
--VS BUG RESLOVER ?
   GLIDESLOPE_WAS_ON = 0 --glideslope recovery possible
   --AUTOLAND_WAS_ON = 0 --autoland recovery possible
   converted_vvi = -1000*CON_VVI_SEL --conversion between bugs
 --  --VS_ACTUAL = converted_vvi -- set V/S plane according to CON_VVI_SEL knob, this should turn the plane --bug here causes concorde stall
  CON_VVI_DES = converted_vvi -- send to bug indicator
  setDataf(findDataref("Colimata/CON_IP_VSI_BUG_1kft_p_min_f"),CON_VVI_DES)
   --OVERRIDE_PITCH = 1
 --  --here you can add slowing factor/protector for sudden pitch changes
 --  PITCH_AP = converted_vvi/10000
 -- if CON_ALT_HOLD_BUTTON == 1 then set("sim/cockpit/autopilot/vertical_velocity", 0) end -- ALT HOLD is pressed, no V/S movement please
 -- if CON_ALT_HOLD_BUTTON == 1 and CON_VVI_ACT > 200 then CON_ALT_HOLD_BUTTON = 0 end -- disengage alt holt conditions are not met
 -- if CON_ALT_HOLD_BUTTON == 1 and CON_VVI_ACT > -200 then CON_ALT_HOLD_BUTTON = 0 end -- disengage alt holt conditions are not met
 ---- matching the desired altitude
 -- if DESCEND == true then
 --  DIFF_ALT = ALT - CON_ALT_HOLD_VALUE -- difference lowers
 -- end 
 -- if ASCEND == true then
 --  DIFF_ALT = CON_ALT_HOLD_VALUE - ALT -- difference lowers
 -- end
 ----end
  else if CON_FD1 == 1 then
  --BUG RESOLVER? OVERRIDE_PITCH = 0
   converted_vvi = -1000*CON_VVI_SEL --conversion between bugs
   CON_VVI_DES = converted_vvi -- send to bug indicator
   setDataf(findDataref("Colimata/CON_IP_VSI_BUG_1kft_p_min_f"),CON_VVI_DES)
 ----end
 ----copntinue here to slow here to mach alt_hold slowly
---- if CON_VS_BUTTON == 1 and 
  end
 -- -- if CON_PITCH == 1 and AUTOPILOT_ON == 1 and CON_VS_BUTTON == 1 then 
 -- --  CON_VS_BUTTON = 0 --disarm v/s mode we are in pitch mode
--  -- end 
 --LAST CHANGED end
 end
end

