function glideslope_by_ap() --actualy is a preparation for autoland
--condtions for glideslope
--if altitude >= 100 and speed >= 150 then 
--if altitude >= 75 then --and speed >= 20 then 
 --DEBUG5 = 0
 --setDatai(findDataref("Colimata/CON_IP_lgt_TOP_ap_i"),DEBUG5)
 --DEBUG6 = 0
 --setDatai(findDataref("Colimata/CON_IP_lgt_TOP_at_i"),DEBUG6)
 DEBUG3 = 0
 setDatai(findDataref("Colimata/CON_IP_lgt_TOP_vorfgy_i"),DEBUG3)
 --DEBUG2 = 0
 --setDatai(findDataref("Colimata/CON_IP_lgt_TOP_tkos_i"),DEBUG2)
 CAPTURING_ILS = 0
 setDatai(findDataref("Colimata/CON_IP_lgt_TOP_acf_warn_i"),CAPTURING_ILS)
 --DEBUG4 = 0
 --setDatai(findDataref("Colimata/CON_IP_lgt_TOP_wxrdr_i"),DEBUG4)
 --autoland brute force attack
-- if AUTOLAND_ON == 1 then 
     
--    if AUTOPILOT ~= 1 then
--    AUTOPILOT = 1
--	setDatai(findDataref("Colimata/CON_AP_sw_AP1_i"),AUTOPILOT) 
--	end
--	if AUTOPILOT2 ~= 1 and altitude <= 400 then
--	AUTOPILOT2 = 1
--	setDatai(findDataref("Colimata/CON_AP_sw_AP2_i"),AUTOPILOT2) 
--	end
--	if AUTOTHROTTLE1 ~= 1 and altitude <= 400 then
--	AUTOTHROTTLE1 = 1
--	setDatai(findDataref("Colimata/CON_AP_sw_AT1_i"),AUTOTHROTTLE1) 
--	end
 --end
 
  if AUTOPILOT == 1 then
     
	 
     --DEBUG5 = 1
	 --setDatai(findDataref("Colimata/CON_IP_lgt_TOP_ap_i"),DEBUG5)
	  --atomic counters
	  if counter_init == 0 then
      counter_a = 0
      counter_b = 0
      previous_deviation = 0
      previous_vspeed = 0
      next_deviation = 0
      next_vspeed = 0
	  counter_init = 1
	  end
	  
       --counter a is for glideslope deviation
      counter_a = counter_a + 5
      if counter_a >= 360 then counter_a = 0 end --simulate circle clock 0=0 90=1 180=0 270=-1 360=0 
      setpoint_for_a = math.sin(math.rad(counter_a))
      if setpoint_for_a == 1 then
       --peak one
       --TEST1 = setpoint_for_a --debug dataref
       --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
       previous_deviation = math.abs(GLIDESLOPE_DEVIATION)
   
      end  
      if setpoint_for_a == -1 then
       --peak two
       --TEST3 = setpoint_for_a --debug dataref
       --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
       next_deviation = math.abs(GLIDESLOPE_DEVIATION)
      end  
	   deviation_error = math.abs(next_deviation-previous_deviation)
	   --TEST1 = deviation_error --debug dataref
       --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
	 --counter a is for vspeed deviation
	   counter_b = counter_b + 5
      if counter_b >= 360 then counter_b = 0 end --simulate circle clock 0=0 90=1 180=0 270=-1 360=0 
      setpoint_for_b = math.sin(math.rad(counter_b))
	  --TEST1 = setpoint_for_b --debug dataref
      --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
      if setpoint_for_b == 1 then
       --peak one
       --TEST1 = setpoint_for_b --debug dataref
       --setDataf(findDataref("Colimata/CON_TESTVALUE_1_f"),TEST1)
       previous_vspeed = CON_VVI_ACT --in fpm
      end  
      if setpoint_for_a == -1 then
       --peak two
       --TEST3 = setpoint_for_a --debug dataref
       --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
       next_vspeed = CON_VVI_ACT --in fpm
      end  
	  vspeed_error = math.abs(next_vspeed-previous_vspeed)
	  --TEST3 = vspeed_error --debug dataref
      --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
	  
	  ---------------------------------
	  ---height check
	        loc_distance=NAV1_DISTANCE --already in nm
			height_nm=loc_distance*math.tan(math.rad(3))
			height_ft=height_nm*6072.12
			if altitude > height_ft then -- altitude in feets? i think yes
				--we_need_go_up = 0
				we_need_go_down = -1
			else
				--we_need_go_up = 1
				we_need_go_down = 1
			end
			if next_vspeed > previous_vspeed then --increasing the change  1500 vs 1400 or 1500 vs 1600
				increasing_pitch_change = 1
				decreasing_pitch_change = 0
			else 
				increasing_pitch_change = 0
				decreasing_pitch_change = 1
			end

			if CON_VVI_ACT > 0 then
				we_are_descending = 0
				we_are_ascending = 1
			else
				we_are_descending = 1
				we_are_ascending = 0
			end
	   
	  ---------------------------------
	  
     if CON_FD1 == 1 then 
	 --if CON_FD2 == 1 then 
      -- if we_have_glideslope == 1 then --we have correct frequency and range
	      --DEBUG6 = 1
	      --setDatai(findDataref("Colimata/CON_IP_lgt_TOP_at_i"),DEBUG6)
		  --breakpoint4 = OVERRIDE_PITCH -- is pitch overriden?
	     if GLIDESLOPE_ACTIVE == 1 then  --glideslope activated 
		    --TEST3 = 0 --debug dataref
	        --setDataf(findDataref("Colimata/CON_TESTVALUE_3_f"),TEST3)
		 --if GLIDESLOPE_ACTIVE == 1 or AUTOLAND_ON == 1 then  --glideslope or autoland activated
		    GLIDESLOPE_WAS_ON = 1
			--AUTOLAND_WAS_ON = 1
		    setDatai(findDataref("Colimata/CON_AP_button_glide_i"),GLIDESLOPE_ACTIVE)
		    CON_ALT_HOLD_BUTTON = 0 -- disable alt hold (does not have a function now)
	        CON_PITCH = 0 -- disable pitch hold
			setDatai(findDataref("Colimata/CON_AP_button_pitch_hold_i"),CON_PITCH)
		    CON_VS_BUTTON = 0 -- disable V/S hold
			setDatai(findDataref("Colimata/CON_AP_button_vert_speed_i"),CON_VS_BUTTON)
			--engage VORLOC if not
