				 --setDatai(findDataref("Colimata/CON_AP_button_vor_loc_ACQ_lgt_i"),VOR_LOC_ACQ_LIGHT)
				--end
			   --end
			  end
			--autoland prerequisites
			BOTH_AUTOPILOTS = AUTOPILOT + AUTOPILOT2
			if AUTOLAND_ON == 1 and BOTH_AUTOPILOTS == 2 then
			 AUTOLAND_LIGHT = 1
