 function HSI_corrector() --something blocking trk/hdg
  --corrected AFCS system logic
  ----hdg trk label on both sides
  if HDG1_TRK_SWITCH == 1 then --0 is track/1 is heading
     HDG1_TRK_DISP = 0 --0 is hdg
	 setDataf(findDataref("Colimata/CON_IP_HSI_display_hdg_trk_f"),HDG1_TRK_DISP) --0-10
	elseif HDG1_TRK_SWITCH == 0 then
	HDG1_TRK_DISP = 10 --10 is trk
	setDataf(findDataref("Colimata/CON_IP_HSI_display_hdg_trk_f"),HDG1_TRK_DISP) --0-10
  end
  if HDG2_TRK_SWITCH == 1 then --0 is track/1 is heading
     HDG2_TRK_DISP = 0 --0 is hdg
	 setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_hdg_trk_f"),HDG2_TRK_DISP) --0-10
	elseif HDG2_TRK_SWITCH == 0 then
	HDG2_TRK_DISP = 10 --10 is trk
	setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_hdg_trk_f"),HDG2_TRK_DISP) --0-10
  end
  --lin/ang for HSI pilot side
  if HSI1_RAD == 1 then --1 is track
    HSI1_LIN = 0 -- 0 is LIN
	setDatai(findDataref("Colimata/CON_IP_HSI_display_displ_ang_lin_i"),HSI1_LIN)
  else
    HSI1_LIN = 1 -- 1 is ang only for rad
	setDatai(findDataref("Colimata/CON_IP_HSI_display_displ_ang_lin_i"),HSI1_LIN)
  end
  --complete set for HSI2
  if HSI2_RAD == 0 then -- HSI2 is set for RAD
     --HDG2_TRK_DISP = 0 --hdg
	 --setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_hdg_trk_f"),HDG2_TRK_DISP)
	 --HDG2_TRK_SWITCH is done
	 HSI2_LIN = 1 --ang
	 setDatai(findDataref("Colimata/CON_IP_COP_HSI_display_displ_ang_lin_i"),HSI2_LIN)
	 COPILOT_TRUE = 10 --shows MAG
     setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_mag_true_f"),COPILOT_TRUE)
	 COPILOT_INS = 10 --shows RAD
	 setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_rad_ins_f"),COPILOT_INS)
	 COPILOT_INS_NO = 10 -- shows 10 always
	 setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_rad_ins_no_f"),COPILOT_INS_NO)
  else -- HSI is INS
	 --HDG2_TRK_DISP = 1 --trk
	 --setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_hdg_trk_f"),HDG2_TRK_DISP)
	 --HDG2_TRK_SWITCH is done
	 HSI2_LIN = 0 --lin
	 setDatai(findDataref("Colimata/CON_IP_COP_HSI_display_displ_ang_lin_i"),HSI2_LIN)
	 COPILOT_TRUE = 0 --shows TRUE
     setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_mag_true_f"),COPILOT_TRUE)
	 COPILOT_INS = 0 --shows INS
	 setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_rad_ins_f"),COPILOT_INS)
	 COPILOT_INS_NO = 10 -- shows 10 always
	 setDataf(findDataref("Colimata/CON_IP_COP_HSI_display_rad_ins_no_f"),COPILOT_INS_NO)
  end
  -- comp/dev/nav copilot/pilot
  --pilot side
  if PILOT_COMP == 0 then
     COPILOT_COMP = 1
     setDatai(findDataref("Colimata/CON_IP_COP_source_comp_i"),COPILOT_COMP)
  end    
  if PILOT_COMP == 1 then
     COPILOT_COMP = 0
     setDatai(findDataref("Colimata/CON_IP_COP_source_comp_i"),COPILOT_COMP)
  end 
  if PILOT_DEV == 0 then
     COPILOT_DEV = 1
	 setDatai(findDataref("Colimata/CON_IP_COP_source_dev_i"),COPILOT_DEV)
  end
  if PILOT_DEV == 1 then
     COPILOT_DEV = 0
	 setDatai(findDataref("Colimata/CON_IP_COP_source_dev_i"),COPILOT_DEV)
  end
  if PILOT_NAV == 0 then
     COPILOT_NAV = 1
	 setDatai(findDataref("Colimata/CON_IP_COP_source_nav_i"),COPILOT_NAV)
  end
  if PILOT_NAV == 1 then
     COPILOT_NAV = 0
	 setDatai(findDataref("Colimata/CON_IP_COP_source_nav_i"),COPILOT_NAV)
  end
  --copilot side
  if COPILOT_COMP == 0 then
     PILOT_COMP = 1
     setDatai(findDataref("Colimata/CON_IP_LE_source_comp_i"),PILOT_COMP)
  end    
  if COPILOT_COMP == 1 then
     PILOT_COMP = 0
     setDatai(findDataref("Colimata/CON_IP_LE_source_comp_i"),PILOT_COMP)
  end 
  if COPILOT_DEV == 0 then
     PILOT_DEV = 1
	 setDatai(findDataref("Colimata/CON_IP_LE_source_dev_i"),PILOT_DEV)
  end
  if COPILOT_DEV == 1 then
     PILOT_DEV = 0
	 setDatai(findDataref("Colimata/CON_IP_LE_source_dev_i"),PILOT_DEV)
  end
  if COPILOT_NAV == 0 then
     PILOT_NAV = 1
	 setDatai(findDataref("Colimata/CON_IP_LE_source_nav_i"),PILOT_NAV)
  end
  if COPILOT_NAV == 1 then
     PILOT_NAV = 0
	 setDatai(findDataref("Colimata/CON_IP_LE_source_nav_i"),PILOT_NAV)
  end
 end
 
 function roll_by_ap() -- heading knob autopilot works
   --AP_TURN_HDG_DIFF = 0 -- default zero
  --if HDG_HOLD == 0 and AUTOPILOT == 1 then
  -----AP disconnect check
  if AP1_WAS_ON == 0 and AUTOPILOT == 1 then --often is OK
   AP1_WAS_ON = 1
  end
  if AT1_WAS_ON == 0 and AUTOTHROTTLE1 == 1 then --often is OK
   AT1_WAS_ON = 1
  end
  ----main procedure
  if AUTOPILOT == 1 then
   OVERRIDE_ROLL = 1
   --AP_TURN_HDG_DIFF = abs(CON_AP_TURN)
   
  
  --if AP_TURN_TO_MUCH == false then
  --  AP_TURN_HDG_DIFF = abs(CON_AP_TURN)
  -- if AP_TURN_HDG_DIFF >> 0.3 then 
  --    AP_TURN_HDG_DIFF = 0.3
	--  AP_TURN_TO_MUCH = true
--	  else
--	  AP_TURN_TO_MUCH = false
  -- end 
  --end
 --  if AP_TURN_HDG < 0.3 then 
  --    AP_TURN_HDG = 0.3
	--  AP_TURN_TO_MUCH = true
	--  else
	--  AP_TURN_TO_MUCH = false
  -- end 
  -- steps
   --if CON_AP_TURN >= 0.1 then 
   --CON_AP_TURN_SMOOTH = CON_AP_TURN - CON_AP_TURN_DIFF
   --end
   --if CON_AP_TURN <= -0.1 then 
   --CON_AP_TURN_SMOOTH = CON_AP_TURN - CON_AP_TURN_DIFF
   --end
   --10 deg right is>
   -- yoke roll ratio 0.15
   --turnratenoroll 3.5
   --turnrateroll 2.0 --react faster to turn knob
   --COn IP ADI value 10
   --smooth removed--
   --CON_AP_TURN_ABS = math.abs(CON_AP_TURN)
   --if CON_AP_TURN_ABS >= 1 then TURN_FACTOR = 20 else TURN_FACTOR = 15 end --slowing turn factor
   --ROLL = CON_AP_TURN/TURN_FACTOR
   ROLL = CON_AP_TURN/10
   --if ROLL <= -0.3 then ROLL = -0.3 end --limiter
   --if ROLL >= 0.3 then ROLL = 0.3 end
   if ROLL <= -0.4 then ROLL = -0.4 end --limiter
   if ROLL >= 0.4 then ROLL = 0.4 end
  ---- else if AUTOPILOT == 0 then
  -- --OVERRIDE_ROLL = 0
  end 
   if AUTOPILOT == 0 then OVERRIDE_ROLL = 0 end
   if AUTOPILOT == 1 and INS_ON == 1 then
      ROLL = 0
      OVERRIDE_ROLL = 0
   end
   if AUTOPILOT == 1 and HDG_HOLD == 1 then
      ROLL = 0
      OVERRIDE_ROLL = 0 
   end
   if AUTOPILOT == 1 and VOR_LOC == 1 then 
      ROLL = 0
      OVERRIDE_ROLL = 0
   end
   if AUTOPILOT == 1 and TRK_HDG == 1 then 
      ROLL = 0
      OVERRIDE_ROLL = 0
   end
  --end
 --end
 end
 
 --WX radar
 function wxradar_rbr4()
  if battery_on == 1 then
    --modes
    if WXRAD_LEFTMODE == 0 then  --off, only left switches plugin
	 RDR4B_MODE = 0
	 setDatai(findDataref("custom/rdr4b/mode"),RDR4B_MODE)
	end
	--system 1
	if WXRAD_SYS == 0 then
	 if WXRAD_LEFTMODE == 1 and WXRAD_RIGHTMODE == 0 then  --on WXR
	  RDR4B_MODE = 2
	  setDatai(findDataref("custom/rdr4b/mode"),RDR4B_MODE)
	 end
	 if WXRAD_LEFTMODE == 1 and WXRAD_RIGHTMODE == 1 then  --on WXRA
	  RDR4B_MODE = 3
	  setDatai(findDataref("custom/rdr4b/mode"),RDR4B_MODE)
	 end
	end
	--system 2
	if WXRAD_SYS == 1 then
	 if WXRAD_LEFTMODE == 1 and WXRAD_RIGHTMODE == 0 then  --on WXRA
	  RDR4B_MODE = 3
	  setDatai(findDataref("custom/rdr4b/mode"),RDR4B_MODE)
	 end
	 if WXRAD_LEFTMODE == 1 and WXRAD_RIGHTMODE == 1 then  --on WXRMAP
	  RDR4B_MODE = 4
	  setDatai(findDataref("custom/rdr4b/mode"),RDR4B_MODE)
	 end
	end
	if WXRAD_LEFTMODE == 2 then  --test
	 RDR4B_MODE = 1
	 setDatai(findDataref("custom/rdr4b/mode"),RDR4B_MODE)
	end
	--gain
	RDR4B_GAIN = WXRAD_GAIN * 0.1
	setDataf(findDataref("custom/rdr4b/gain"),RDR4B_GAIN)
	--range L 0, 1, -1, R 0, 1, 2, -1
	--if WXRAD_LEFTRANGE == -1 then  --4NM
	-- RDR4B_RANGE = 0
	-- setDatai(findDataref("custom/rdr4b/range"),RDR4B_RANGE) 
	--end
	if WXRAD_LEFTRANGE == 0 then  --10NM
	 RDR4B_RANGE = 1
	 setDatai(findDataref("custom/rdr4b/range"),RDR4B_RANGE) 
	end
	if WXRAD_LEFTRANGE == 1 then  --20NM
	 RDR4B_RANGE = 2
	 setDatai(findDataref("custom/rdr4b/range"),RDR4B_RANGE) 
	end
	if WXRAD_RIGHTRANGE == -1 and WXRAD_LEFTRANGE == -1 then  --4NM
	 RDR4B_RANGE = 0
	 setDatai(findDataref("custom/rdr4b/range"),RDR4B_RANGE) 
	end
	if WXRAD_RIGHTRANGE == 1 and WXRAD_LEFTRANGE == -1 then  --80NM
	 RDR4B_RANGE = 4
	 setDatai(findDataref("custom/rdr4b/range"),RDR4B_RANGE) 
	end
	if WXRAD_RIGHTRANGE == 0 and WXRAD_LEFTRANGE == -1 then  --40NM
	 RDR4B_RANGE = 3
	 setDatai(findDataref("custom/rdr4b/range"),RDR4B_RANGE) 
	end
	if WXRAD_RIGHTRANGE == 2 and WXRAD_LEFTRANGE == -1 then  --160NM
	 RDR4B_RANGE = 5
	 setDatai(findDataref("custom/rdr4b/range"),RDR4B_RANGE) 
	end
	--tilt
	RDR4B_TILT = WXRAD_TILT
	setDataf(findDataref("custom/rdr4b/tilt"),RDR4B_TILT) 
  else --loss of power
    RDR4B_MODE = 0
	setDatai(findDataref("custom/rdr4b/mode"),RDR4B_MODE)
  end
 end
