 function pvs1580()
  -- switch to power when no ground avail 
  if PVS1580_ON == 1 and WEHAVEPOWER_G == 0 then 
   if battery_on == 1 then 
    PVS1580_ON = 0
    setDatai(findDataref("Colimata/CON_EG_RL_sw_acf_ids_power_i"),PVS1580_ON)
   end 
  end 
  PVS_GROUND_OPS = WEHAVEPOWER_G + PVS1580_ON -- ground override when 2
  if battery_on == 1 then
   if WEHAVEPOWER_G == 0 or PVS_GROUND_OPS == 2 then -- regular operations
    -- pressed keys
	skip_keypad_after_press = 0 -- pause one second between next input 
    aids_keypad_pressed=keypad_aids_0+keypad_aids_1+keypad_aids_2+keypad_aids_3+keypad_aids_4+keypad_aids_5+keypad_aids_6+keypad_aids_7+keypad_aids_8+keypad_aids_9
	if keypad_aids_0 == 1 then display_aids_code_buffer = 0 end
    if keypad_aids_1 == 1 then display_aids_code_buffer = 1 end 	
	if keypad_aids_2 == 1 then display_aids_code_buffer = 2 end 
	if keypad_aids_3 == 1 then display_aids_code_buffer = 3 end 
	if keypad_aids_4 == 1 then display_aids_code_buffer = 4 end 
	if keypad_aids_5 == 1 then display_aids_code_buffer = 5 end 
	if keypad_aids_6 == 1 then display_aids_code_buffer = 6 end 
	if keypad_aids_7 == 1 then display_aids_code_buffer = 7 end 
	if keypad_aids_8 == 1 then display_aids_code_buffer = 8 end 
	if keypad_aids_9 == 1 then display_aids_code_buffer = 9 end 
	-- key order pressed
	 -- first digit entered
	if skip_keypad_after_press == 0 then
	 if order_keypad_numbers == 0 and aids_keypad_pressed ~= 0 then
	  first_digit_code_set = 1
	  display_aids_code_digit1 = display_aids_code_buffer
	  order_keypad_numbers = 1
	  skip_keypad_after_press = 1
	 end 
	end
	 -- second digit entered
	if skip_keypad_after_press == 0 then
	 if order_keypad_numbers == 1 and aids_keypad_pressed ~= 0 then
	  second_digit_code_set = 1
	  display_aids_code_digit2 = display_aids_code_buffer
	  order_keypad_numbers = 2
	  skip_keypad_after_press = 1
	 end
	end
	 -- third digit entered
	if skip_keypad_after_press == 0 then
	 if order_keypad_numbers == 2 and aids_keypad_pressed ~= 0 then
	  third_digit_code_set = 1
	  display_aids_code_digit3 = display_aids_code_buffer
	  order_keypad_numbers = 3
	  skip_keypad_after_press = 1
	 end 
	end 
	 -- fourth digit entered
	if skip_keypad_after_press == 0 then
	 if order_keypad_numbers == 3 and aids_keypad_pressed ~= 0 then
	  fourth_digit_code_set = 1
	  display_aids_code_digit4 = display_aids_code_buffer
	  order_keypad_numbers = 4
	  skip_keypad_after_press = 1
	 end
	end
    -- code data inserted
	 -- displayed on code side 
	if keypad_aids_dis == 0 then -- show code dipslay entering codes
	 total_digits_set=first_digit_code_set+second_digit_code_set+third_digit_code_set+fourth_digit_code_set
	 if total_digits_set == 0 then
	  display_aids_code = 0
	  setDatai(findDataref("Gastonreif/Heritage/aids_code"),display_aids_code)
	 end
	 if total_digits_set == 1 then
	  display_aids_code = 1*display_aids_code_digit1
	  setDatai(findDataref("Gastonreif/Heritage/aids_code"),display_aids_code)
	 end
	 if total_digits_set == 2 then 
	  display_aids_code = 10*display_aids_code_digit1 + 1*display_aids_code_digit2
	  setDatai(findDataref("Gastonreif/Heritage/aids_code"),display_aids_code)
	 end
	 if total_digits_set == 3 then 
	  display_aids_code = 100*display_aids_code_digit1 + 10*display_aids_code_digit2 + 1*display_aids_code_digit3
	  setDatai(findDataref("Gastonreif/Heritage/aids_code"),display_aids_code)
	 end
	 if total_digits_set == 4 then 
	  display_aids_code = 1000*display_aids_code_digit1 + 100*display_aids_code_digit2 + 10*display_aids_code_digit3 + 1*display_aids_code_digit4
	  setDatai(findDataref("Gastonreif/Heritage/aids_code"),display_aids_code)
	 end
	end
	-- display also data
    if keypad_aids_dis == 1 then keypad_aids_dis_pressed = 1 end -- continuous display 
	-- Data sources from max and peak values here 
	-- 2003 Peak positive G in flight 
	if GEAR_DOWN == 0 and speed >= 35 then
	   if ALPHA_G_FORCE >= 0 then
	    absolute_alpha_g_force = ALPHA_G_FORCE
	    positive_alpha_g = math.ceil(absolute_alpha_g_force)
		if positive_alpha_g > peak_positive_alpha_g then peak_positive_alpha_g = positive_alpha_g end -- store largest value 
	   end
    end
    -- 2004 - Peak negative G in flight 	
	if GEAR_DOWN == 0 and speed >= 35 then
	   if ALPHA_G_FORCE < 0 then
	    absolute_alpha_g_force = ALPHA_G_FORCE
	    negative_alpha_g = math.ceil(absolute_alpha_g_force)
		if negative_alpha_g > peak_negative_alpha_g then peak_negative_alpha_g = negative_alpha_g end -- store largest value 
	   end
